/* Contenido de charlas (construccion): más información y preguntas más exigentes. Lo aplica mejoras_comunes.js (sección 23). */
window.__mjContenidoAplicar && window.__mjContenidoAplicar({"grupo":"con","temas":[{"id":"autocuidado","sec":"todos","title":"Actos inseguros, condiciones inseguras y autocuidado","thumb":"pz_compromiso","learn":[{"s":"c5au_cadena","t":"Un accidente casi nunca es mala suerte","x":"Detrás de casi todo accidente hay una <b>cadena</b> de pequeñas fallas: el apuro, un paso del procedimiento que te saltas, un EPP que no te pones, una condición que nadie corrigió. Basta con <b>cortar un eslabón</b> para que el accidente no ocurra. Por eso cada persona de la obra, desde el jornal hasta el jefe de obra, tiene en sus manos la posibilidad de evitarlo.","k":"Tú puedes cortar la cadena."},{"s":"pz_alt_vano_mal","t":"Condición insegura","x":"Es algo del <b>lugar, del equipo o del material</b> que puede dañar a alguien, aunque nadie esté haciendo nada mal en ese momento. Ejemplos en obra:<ul><li>un vano en la losa sin tapa;</li><li>un andamio sin baranda o con tablones sueltos;</li><li>una extensión con el cable pelado;</li><li>tablas con clavos hacia arriba;</li><li>una zanja sin entibar.</li></ul>Si la ves, se corrige o se avisa de inmediato."},{"s":"pz_escala_mal","t":"Acción insegura","x":"Es algo que una <b>persona hace o deja de hacer</b> y que la pone en riesgo a ella o a otros. Ejemplos en obra:<ul><li>pararse en el último peldaño de la escala;</li><li>sacar la protección de la sierra circular;</li><li>pasar bajo una carga suspendida;</li><li>trabajar sin arnés “porque es un ratito”;</li><li>no usar el EPP entregado.</li></ul>La diferencia es simple: la condición está en el lugar; la acción, en la conducta."},{"s":"auto_porque","t":"¿Por qué nos arriesgamos?","x":"Casi siempre por las mismas cuatro razones: <b>apuro</b> por terminar, <b>costumbre</b> (“siempre lo he hecho así”), <b>cansancio</b> y <b>exceso de confianza</b> (“a mí no me va a pasar”). Que algo nunca haya fallado no prueba que sea seguro: solo que hasta hoy hubo suerte. Ninguna de esas razones vale una caída, una mano o una vida."},{"s":"c5au_ppa","t":"Para, piensa y actúa","x":"Antes de empezar cada tarea, y cada vez que algo cambie:<ul><li><b>Para</b> un momento.</li><li><b>Piensa</b> qué puede fallar: caer, golpearte, cortarte, quedar atrapado o electrocutarte.</li><li><b>Actúa</b> con el control correcto: EPP, herramienta adecuada, ayuda de un compañero o el permiso de trabajo que corresponda.</li></ul>Si no sabes cómo hacerlo seguro, pregunta antes de empezar."},{"s":"pz_derechos","t":"Derecho a detenerte","x":"Si ves un <b>riesgo grave e inminente</b> para tu vida o tu salud, por ejemplo un andamio sin baranda, una zanja que se está desmoronando o un cable energizado en el suelo, tienes derecho a <b>interrumpir tu trabajo y retirarte</b>. Debes <b>avisar de inmediato</b> a tu jefatura. Así lo establece el Código del Trabajo en su artículo 184 bis, y no pueden sancionarte por ejercerlo.","k":"Ante un riesgo grave, detente y avisa de inmediato."},{"s":"c5au_alcohol","t":"Cero alcohol y drogas","x":"En obra se trabaja en altura, con sierras, esmeriles, máquinas y electricidad. El alcohol y las drogas <b>bajan los reflejos, la atención y el equilibrio</b>, y sus efectos pueden durar hasta el día siguiente. Llegar con hálito alcohólico o bajo efecto de drogas está <b>prohibido</b> por el Reglamento Interno. Si un compañero llega así, no debe trabajar: avisa a la jefatura. Los medicamentos que dan sueño también se informan."},{"s":"pz_compromiso","t":"Cuida a tu compañero","x":"Si ves a alguien en riesgo, <b>avísale con respeto</b> y de inmediato: “ponte el arnés”, “no pases bajo la carga”. Si no corrige, informa a tu capataz. Y si te avisan a ti, <b>agradece y corrige</b>: nadie te está acusando. En la obra todos dependemos de todos, y el que mira para el lado también es parte de la cadena."},{"s":"nearMiss","t":"Reporta también los casi accidentes","x":"Un <b>cuasi accidente</b> es un hecho que pudo lesionar a alguien y no lo hizo por poco: un tablón que cae cerca, un resbalón en la escalera, una carga que se balancea. <b>Repórtalo</b> a tu capataz o a prevención aunque nadie se haya lastimado. Cada casi accidente es un aviso gratis: si se corrige la causa, se evita el accidente de mañana."}],"quiz":[{"s":"pz_alt_vano_mal","v":[{"q":"En la losa del tercer piso hay un vano sin tapa ni señalización. ¿Qué es?","o":["Una condición insegura","Una acción insegura","Un cuasi accidente","Un riesgo aceptable en obra gruesa"],"w":"Es un problema del lugar: existe aunque nadie esté haciendo nada mal. Se tapa, se fija y se señaliza, o se avisa."},{"q":"¿Cuál de estos ejemplos es una condición insegura?","o":["Una zanja abierta sin entibar","Pasar bajo una carga suspendida","Sacar la protección a la sierra","Trabajar sin arnés un momento"],"w":"La condición está en el lugar o el equipo; las otras opciones son conductas, es decir, acciones inseguras."},{"q":"Un vano sin tapa en la losa es una acción insegura del último trabajador que pasó por ahí.","vf":false,"w":"Falso. Es una condición insegura del lugar; se corrige tapándolo y señalizándolo."}]},{"s":"pz_escala_mal","v":[{"q":"Un compañero se para en el último peldaño de la escala para alcanzar más alto. ¿Qué es?","o":["Una acción insegura","Una condición insegura","Un cuasi accidente","Algo permitido si es por poco rato"],"w":"Es una conducta de la persona: se usa una escala más alta o un andamio."},{"q":"¿Cuál de estos ejemplos es una acción insegura?","o":["Pasar bajo una carga suspendida","Una extensión con el cable pelado","Un andamio sin baranda","Clavos hacia arriba en una tabla"],"w":"La acción insegura es algo que la persona hace; los demás son condiciones del lugar o del equipo."},{"q":"Para terminar luego, un maestro saca la protección de la sierra circular. ¿Cómo se clasifica?","o":["Acción insegura","Condición insegura","Cuasi accidente","Falla del equipo"],"w":"La protección se quitó por decisión de una persona: es una acción insegura."}]},{"s":"pz_epp_mal_q","v":[{"q":"Un trabajador entra al frente de trabajo sin casco ni zapatos de seguridad, aunque se los entregaron. ¿Qué es?","o":["Una acción insegura","Una condición insegura","Un cuasi accidente","Una falta solo de la empresa"],"w":"No usar el EPP entregado es una conducta de la persona: acción insegura."},{"q":"Dejar los guantes en el bolsillo mientras manipulas fierros es:","o":["Una acción insegura","Una condición insegura","Un cuasi accidente","Correcto si los fierros son cortos"],"w":"Es algo que la persona deja de hacer y la expone a cortes: acción insegura."},{"q":"¿Cuál de estas situaciones es una acción insegura y no una condición insegura?","o":["Trabajar sin el EPP que te entregaron","Un tablero eléctrico con la tapa rota","Un acopio de ladrillos inestable","Un vano en la losa sin señalizar"],"w":"Las otras tres son fallas del lugar o del equipo; no usar el EPP es una conducta."}]},{"s":"auto_porque","v":[{"q":"“Siempre lo he hecho así y nunca me ha pasado nada”. ¿Qué causa de accidentes refleja esa frase?","o":["Costumbre y exceso de confianza","Falta de herramientas","Una condición insegura del lugar","Mala suerte"],"w":"La costumbre y el exceso de confianza hacen que nos saltemos controles."},{"q":"¿Cuáles son las cuatro razones típicas por las que nos arriesgamos?","o":["Apuro, costumbre, cansancio y exceso de confianza","Calor, lluvia, ruido y polvo en la obra","Falta de EPP, de orden, de luz y de herramientas adecuadas","Edad, peso, estatura y experiencia"],"w":"Son factores de la conducta que llevan a saltarse pasos."},{"q":"Si una forma de trabajar nunca ha causado un accidente, eso demuestra que es segura.","vf":false,"w":"Falso. Solo demuestra que hasta hoy hubo suerte; la costumbre no es una medida de control."}]},{"s":"pz_andamio_mal_q","v":[{"q":"Vas a subir a un andamio y ves que no tiene baranda y está apoyado sobre bloques. ¿Qué haces?","o":["No subo y aviso de inmediato a mi jefatura","Subo con cuidado y me quedo al centro","Subo solo si me amarro a la estructura","Le pido a un compañero que sujete el andamio"],"w":"Es un riesgo grave e inminente: tienes derecho a detenerte y debes avisar (art. 184 bis)."},{"q":"¿Qué ley te permite interrumpir tu trabajo ante un riesgo grave e inminente para tu vida?","o":["El Código del Trabajo, artículo 184 bis","La Ley de Tránsito 18.290","La Ley 20.949 sobre carga manual","El DS 594 sobre condiciones sanitarias"],"w":"El art. 184 bis reconoce el derecho a detenerse y retirarse, avisando de inmediato."},{"q":"Si te detienes ante un riesgo grave e inminente, ¿qué más debes hacer?","o":["Avisar de inmediato a mi jefatura","Esperar a que alguien lo note","Irme a mi casa sin avisar","Corregirlo yo aunque no sepa cómo"],"w":"El derecho a detenerse va junto con el deber de avisar de inmediato."}]},{"s":"c5au_ppa","v":[{"q":"Te piden hacer una tarea que no habías hecho antes. ¿Qué es lo primero?","o":["Parar, pensar qué puede fallar y elegir el control","Empezar y ver cómo resulta","Copiar lo que hace el compañero de al lado","Pedir que otro la haga primero"],"w":"Para, piensa y actúa: así se identifica el riesgo antes de exponerse."},{"q":"En “para, piensa y actúa”, ¿qué significa actuar?","o":["Aplicar el control correcto: EPP, herramienta, ayuda o permiso","Trabajar rápido para reducir el tiempo de exposición","Avisar al final de la jornada lo que pudo fallar","Pedir que el capataz haga la tarea"],"w":"Actuar es hacer la tarea con el control adecuado al riesgo que pensaste."},{"q":"El “para, piensa y actúa” se aplica antes de empezar y también cada vez que la tarea cambia.","vf":true,"w":"Verdadero. Si cambian las condiciones, cambian los riesgos."}]},{"s":"c5au_alcohol","v":[{"q":"Un compañero llega a la obra con hálito alcohólico. ¿Qué corresponde?","o":["Que no trabaje y se avise a la jefatura","Que trabaje solo en el suelo","Que tome café y empiece más tarde","Que trabaje acompañado por otro"],"w":"Está prohibido trabajar bajo efecto de alcohol o drogas: pone en riesgo a todos."},{"q":"Anoche hubo un cumpleaños y en la mañana aún sientes los efectos del alcohol. ¿Qué haces?","o":["Lo informo a mi jefatura antes de empezar","Trabajo normal, pero sin subir a altura","Tomo bastante agua y empiezo","Me tomo un café cargado y empiezo"],"w":"Los efectos pueden durar hasta el día siguiente; a la obra se llega sobrio."},{"q":"¿Por qué el alcohol es especialmente peligroso en una obra?","o":["Baja reflejos, atención y equilibrio en altura y con máquinas","Solo porque lo prohíbe el contrato","Porque produce sed y cansancio durante la tarde","Porque da mal aspecto frente a los vecinos de la obra"],"w":"En altura y con sierras un error de reflejos puede ser fatal."}]},{"s":"pz_compromiso","v":[{"q":"Un compañero te dice que estás trabajando sin barbiquejo en el andamio. ¿Qué haces?","o":["Le agradezco y me lo pongo","Le digo que se preocupe de lo suyo","Me lo pongo cuando baje","Le pido que avise al capataz"],"w":"Recibir avisos con respeto y corregir es parte del autocuidado del equipo."},{"q":"Ves a un compañero pasar bajo una carga del camión pluma. ¿Qué es lo correcto?","o":["Avisarle con respeto de inmediato","Esperar el almuerzo para decirle","No decir nada para no molestar","Avisar después a prevención por escrito"],"w":"Avisar a tiempo evita el accidente; si no corrige, informa al capataz."},{"q":"Si un compañero no corrige una acción insegura después de que le avisas, debes informar al capataz.","vf":true,"w":"Verdadero. Mirar para el lado también es parte de la cadena del accidente."}]}]},{"id":"peligros","sec":"todos","title":"Peligros y riesgos en obra: identificación y control (MIPER)","thumb":"pz_irl","learn":[{"s":"hazRisk","t":"Peligro y riesgo no son lo mismo","x":"El <b>peligro</b> es la fuente del daño: la altura, la sierra circular, la electricidad, la zanja, la carga suspendida. El <b>riesgo</b> es la posibilidad de que ese daño ocurra y qué tan grave sería. Ejemplo: la sierra es el peligro; que el disco te corte la mano es el riesgo. El peligro no siempre se puede quitar, pero el riesgo sí se puede controlar."},{"s":"pz_obra","t":"Los peligros típicos de una obra","x":"<ul><li><b>Caídas</b> desde losas, andamios, escalas, techumbres y vanos.</li><li><b>Golpes y cortes</b> con herramientas, fierros y despuntes.</li><li><b>Caída de objetos</b> y cargas suspendidas de grúa o camión pluma.</li><li><b>Atropellos</b> con retroexcavadoras, camiones y mixer.</li><li><b>Derrumbes</b> de zanjas y excavaciones.</li><li><b>Electricidad</b>, <b>polvo de sílice</b>, <b>ruido</b>, <b>radiación UV</b> y <b>sobreesfuerzo</b>.</li></ul>En obra el peligro cambia cada día con el avance: mira antes de empezar."},{"s":"miper","t":"La matriz de riesgos (MIPER)","x":"La Matriz de Identificación de Peligros y Evaluación de Riesgos registra, por cada <b>tarea</b>: sus <b>peligros</b>, el <b>riesgo</b> evaluado y las <b>medidas de control</b>. {EMP} la elabora con prevención y la actualiza cuando cambia la obra, llega un equipo nuevo u ocurre un accidente. De ella salen tu información de riesgos (IRL) y los procedimientos de trabajo seguro."},{"s":"peligros_eval","t":"¿Qué tan probable y qué tan grave?","x":"Cada riesgo se evalúa combinando dos preguntas: <b>¿qué tan seguido puede pasar?</b> y <b>¿qué tan grave sería?</b> Los riesgos que pueden causar una lesión grave o la muerte se controlan <b>primero</b>, aunque parezcan poco probables: caer de altura, quedar atrapado en una zanja, ser golpeado por una carga o electrocutarse. Un corte leve importa, pero va después.","k":"Lo que puede matar, se controla primero."},{"s":"c5pe_jer","t":"Jerarquía de controles","x":"De lo más eficaz a lo menos eficaz:<ul><li><b>Eliminar</b> el peligro: prefabricar en el suelo para no trabajar en altura.</li><li><b>Sustituir</b>: un material o método menos dañino.</li><li><b>Ingeniería</b>: barandas, tapas de vanos, protección de sierra, entibación.</li><li><b>Administrativos</b>: procedimientos, permisos, señalización, capacitación.</li><li><b>EPP</b>: la última barrera.</li></ul>Se parte siempre desde arriba.","k":"El EPP no reemplaza a una baranda."},{"s":"pz_alt_borde_ok","t":"Ejemplo: borde de losa","x":"Peligro: caer al vacío desde el borde. Controles en orden:<ul><li><b>Ingeniería</b>: baranda a firme con pasamano, travesaño intermedio y rodapié.</li><li><b>Administrativo</b>: procedimiento de trabajo en altura y zona delimitada.</li><li><b>EPP</b>: arnés de cuerpo completo anclado, cuando no se pueda instalar baranda.</li></ul>Sobre 1,8 metros de altura ya es trabajo en altura."},{"s":"pz_irl","t":"Tu derecho a saber (IRL)","x":"Según el DS 44, antes de empezar tienes derecho a ser informado de los <b>riesgos de tu tarea</b>, sus consecuencias y las medidas para controlarlos. Esa información queda registrada con tu firma. Si cambias de tarea, llega un equipo nuevo o cambia el lugar de trabajo, pregunta: <b>¿qué riesgos tiene y cómo me protejo?</b> Si no lo entiendes, pide que te lo expliquen otra vez."},{"s":"auto_reporte","t":"Reporta lo que veas","x":"Si encuentras una condición peligrosa, como un derrame de aceite, un tablero abierto o una baranda suelta, <b>avisa</b> a tu capataz, jefe de obra o prevención. Si puedes corregirla sin exponerte, hazlo; si es eléctrica, estructural o necesita a alguien autorizado, <b>delimita y avisa</b>, no la arregles tú. Un reporte a tiempo evita el accidente de mañana."}],"quiz":[{"s":"hazRisk","v":[{"q":"En la obra hay una sierra circular. ¿Qué es la sierra en sí misma?","o":["Un peligro","Un riesgo","Una medida de control","Un cuasi accidente"],"w":"La sierra es la fuente del daño: un peligro. El riesgo es la posibilidad de cortarte."},{"q":"Que un maestro se corte la mano con el disco de la sierra es:","o":["El riesgo","El peligro","El control","La condición insegura"],"w":"El riesgo es la posibilidad de que el daño ocurra; la sierra es el peligro."},{"q":"¿Cuál de estas frases describe un riesgo y no un peligro?","o":["La posibilidad de caer desde la losa","La altura de la losa del tercer piso","El tablero eléctrico","La zanja abierta"],"w":"El riesgo es la probabilidad de un daño; altura, tablero y zanja son peligros."}]},{"s":"pz_alt_borde_ok_q","v":[{"q":"¿Cuál es la medida MÁS eficaz para evitar caídas desde el borde de una losa?","o":["Baranda a firme con rodapié","Arnés de seguridad sin baranda","Charla diaria sobre altura","Cinta de peligro en el borde"],"w":"La protección colectiva de ingeniería está por sobre los procedimientos y el EPP."},{"q":"Según la jerarquía de controles, ¿qué nivel es instalar tapas en los vanos?","o":["Ingeniería","Administrativo","EPP","Sustitución"],"w":"Es una barrera física que protege a todos: control de ingeniería."},{"q":"Para evitar trabajar en altura, se decide armar las enfierraduras en el suelo y luego izarlas. ¿Qué nivel de control es?","o":["Eliminación","Ingeniería","Administrativo","EPP"],"w":"Si ya no hay que subir, se elimina el peligro para esa tarea: es lo más eficaz."}]},{"s":"c5pe_jer","v":[{"q":"En la jerarquía de controles, ¿qué lugar ocupa el EPP?","o":["El último: es la última barrera","El primero: es lo más importante","El segundo, después de eliminar","Está al mismo nivel que la baranda"],"w":"El EPP protege de lo que no se pudo eliminar ni controlar antes."},{"q":"¿Cuál es el orden correcto de la jerarquía de controles?","o":["Eliminar, sustituir, ingeniería, administrativos y EPP","EPP, administrativos, ingeniería, sustituir y eliminar","Ingeniería, EPP, eliminar, sustituir y administrativos","Administrativos, EPP, ingeniería, eliminar y sustituir"],"w":"Se parte por lo más eficaz, eliminar, y se termina en el EPP."},{"q":"El EPP es la primera y más importante medida de control en una obra.","vf":false,"w":"Falso. Es la última barrera: va después de eliminar, sustituir, ingeniería y administrativos."}]},{"s":"miper","v":[{"q":"¿Dónde se registran las tareas, sus peligros, riesgos y medidas de control?","o":["En la matriz de riesgos (MIPER)","En el libro de obra","En el contrato de trabajo","En la guía de despacho"],"w":"La MIPER define los controles de cada tarea y alimenta tu IRL."},{"q":"¿Cuándo debe actualizarse la MIPER?","o":["Al cambiar la obra, llegar un equipo nuevo u ocurrir un accidente","Solo una vez al año, en el mes de diciembre","Solo cuando lo pide la mutualidad por escrito","Una sola vez, al iniciar la obra"],"w":"La matriz debe reflejar los riesgos reales del momento."},{"q":"¿Qué documento sale directamente de la MIPER?","o":["Tu información de riesgos laborales (IRL)","Tu liquidación de sueldo","El permiso de edificación municipal","El certificado de inicio de obra"],"w":"La IRL informa los riesgos y controles que la MIPER identificó para tu tarea."}]},{"s":"pz_alt_borde_mal_q","v":[{"q":"En tu frente hay: un borde de losa sin protección, sacos mal apilados y polvo. ¿Qué se controla primero?","o":["El borde de losa sin protección","Los sacos mal apilados","El polvo","Lo que sea más rápido de arreglar"],"w":"Se prioriza lo que puede causar la muerte o una lesión grave."},{"q":"¿Qué dos preguntas se combinan para evaluar un riesgo?","o":["Qué tan probable y qué tan grave","Cuánto cuesta y cuánto demora","Quién lo causó y cuándo","Qué EPP se usa y de qué marca"],"w":"El riesgo se evalúa por probabilidad y gravedad."},{"q":"Un riesgo de caída desde 6 metros parece poco probable. ¿Cómo se trata?","o":["Se controla primero por su gravedad","Se deja para después por ser poco probable","Se controla solo si alguien ya cayó","Se resuelve con una charla y nada más"],"w":"Aunque sea poco probable, si puede matar se controla primero."}]},{"s":"pz_irl","v":[{"q":"Te cambian a una tarea que nunca has hecho. ¿Qué haces?","o":["Pregunto sus riesgos y controles antes de empezar","Empiezo y voy aprendiendo","Copio lo que hace otro","Espero a que prevención venga a fin de mes"],"w":"Tienes derecho a ser informado antes de empezar (DS 44)."},{"q":"¿Qué normativa establece tu derecho a ser informado de los riesgos de tu tarea?","o":["El DS 44","La Ley de Tránsito","La Ley 20.949","La Ley 20.580"],"w":"El DS 44, sobre gestión preventiva de los riesgos laborales, incluye la obligación de informar."},{"q":"La información de riesgos se entrega una sola vez y no se repite aunque cambies de tarea.","vf":false,"w":"Falso. Si cambia la tarea, el equipo o el lugar, debes ser informado de los nuevos riesgos."}]},{"s":"pz_elec_tablero_mal_q","v":[{"q":"Encuentras un tablero eléctrico abierto y con cables expuestos. ¿Qué haces?","o":["Delimito, no lo toco y aviso de inmediato","Cierro la tapa y amarro con alambre","Sigo trabajando lejos del tablero","Lo reparo con cinta aisladora"],"w":"Lo eléctrico lo corrige solo personal autorizado; tú delimitas y reportas."},{"q":"Ves aceite derramado en el acceso y tienes material absorbente a mano. ¿Qué es lo correcto?","o":["Lo cubro, señalizo y aviso al capataz","Paso por el lado con cuidado","Espero que alguien de aseo lo vea","Lo tapo con un cartón sin avisar"],"w":"Si puedes corregir sin exponerte, lo haces y además informas."},{"q":"¿Qué condiciones peligrosas NO debes arreglar tú, aunque quieras ayudar?","o":["Las eléctricas o estructurales","Un derrame pequeño de agua","Una herramienta mal guardada","Un despunte en el paso"],"w":"Requieren personal autorizado: se delimitan y se avisan."}]},{"s":"pz_obra","v":[{"q":"¿Por qué hay que revisar el frente de trabajo cada día antes de empezar?","o":["Porque los peligros cambian con el avance","Porque lo exige solo la mutualidad","Porque así se termina más rápido","Porque cambian los horarios y las cuadrillas"],"w":"Cada etapa trae peligros nuevos: vanos, excavaciones, cargas, máquinas."},{"q":"¿Cuál de estos es un peligro típico de obra que suele olvidarse?","o":["El polvo de sílice al cortar hormigón","El color de la ropa de trabajo","La marca de la herramienta","El tipo de lápiz del libro de obra"],"w":"El polvo de sílice daña el pulmón de forma permanente."},{"q":"En una obra, los peligros cambian a medida que avanzan los trabajos.","vf":true,"w":"Verdadero. Por eso hay que mirar el lugar antes de cada tarea."}]}]},{"id":"epp","sec":"todos","mins":5,"title":"Uso y cuidado del EPP en obra","thumb":"pz_epp_ok","learn":[{"s":"c5ep_que","t":"¿Qué es el EPP?","x":"Son los <b>Elementos de Protección Personal</b>: casco, zapatos de seguridad, guantes, lentes, protector auditivo, respirador, ropa de trabajo y arnés, según la tarea. El EPP <b>no elimina el peligro</b>: es la <b>última barrera</b> entre tu cuerpo y lo que no se pudo controlar antes con barandas, protecciones o procedimientos. Por eso protege solo si es el adecuado y está bien puesto."},{"s":"epp_give","t":"Lo que dice la ley","x":"El empleador debe <b>entregar sin costo</b> los EPP adecuados al riesgo y enseñarte a usarlos (Ley 16.744, artículo 68; DS 594, artículo 53). Tú estás <b>obligado a usarlos</b> todo el tiempo que estés expuesto al riesgo, y no usarlos es una falta al Reglamento Interno. La entrega queda registrada con tu firma.","k":"La empresa los entrega gratis; tú los usas siempre."},{"s":"pz_epp_ok","t":"El equipo básico de obra","x":"En terreno se usa siempre: <b>casco con barbiquejo, zapatos de seguridad con puntera, ropa de trabajo con cintas reflectantes y guantes</b>. Según la tarea se suman lentes, protector auditivo, respirador, careta facial o arnés. Tu IRL y tu jefatura indican qué EPP lleva cada tarea. Sin el EPP básico, no se entra a la obra."},{"s":"pz_epp_barbiquejo","t":"Casco con barbiquejo","x":"El casco protege de <b>objetos que caen</b> y de golpes contra fierros y moldajes. El <b>barbiquejo</b> evita que se caiga al agacharte, al mirar hacia arriba o si resbalas, justo cuando más lo necesitas. Antes de usarlo revisa que no tenga <b>trizaduras, golpes fuertes ni el arnés interior roto</b>, y no le hagas perforaciones ni lo pintes."},{"s":"epp_time","t":"Lentes: corte, esmeril y polvo","x":"Cortar con esmeril angular o sierra, picar, perforar, clavar o mezclar mortero lanza <b>partículas</b> a los ojos. Usa lentes de seguridad <b>todo el tiempo</b> que dure la tarea, no solo al empezar. Con esmeril angular, además, <b>careta facial</b> sobre los lentes. Si te entra una partícula, no te frotes: lava con agua limpia y avisa."},{"s":"pz_epp_respirador","t":"Respirador para el polvo","x":"Al cortar hormigón, ladrillo, cerámica o fibrocemento, o al lijar, se genera <b>polvo de sílice</b>, que daña el pulmón para siempre. Se usa <b>respirador con filtro</b> adecuado, bien sellado a la cara y sin barba que impida el sello. La mascarilla de tela o la desechable común no protege. Cambia los filtros cuando cueste respirar o según indique la jefatura."},{"s":"pz_epp_fonos","t":"Protector auditivo","x":"Sierra circular, esmeril, martillo demoledor y vibrador de hormigón superan con facilidad los <b>85 decibeles</b>. Sobre ese nivel se usan <b>fonos o tapones</b>, puestos durante toda la exposición. Los fonos van sobre las orejas, ajustados y sin gorro debajo; los tapones se insertan con las manos limpias. La sordera por ruido es permanente y no duele mientras avanza."},{"s":"c5ep_cuida","t":"Revisa, cuida y pide recambio","x":"<ul><li><b>Revísalo</b> antes de cada uso.</li><li>Guárdalo <b>limpio y seco</b>, lejos del sol directo.</li><li><b>No lo modifiques</b>: nada de cortar guantes ni perforar el casco.</li><li>Si se daña o se pierde, <b>pide recambio</b> sin costo de inmediato.</li><li>Usa solo EPP <b>certificado</b>.</li></ul>Un casco trizado o un guante roto ya no protegen.","k":"EPP dañado no protege: pide recambio de inmediato."},{"s":"pz_epp_mal","t":"Los errores típicos","x":"Casco en la mano o sin barbiquejo, lentes en la frente, fonos colgando del cuello, guantes en el bolsillo, zapatillas en vez de zapatos de seguridad o respirador bajo el mentón. Es como no tenerlo. Tampoco se presta el EPP personal, como respiradores o tapones. Si una talla no te queda, pide otra: no lo uses mal puesto."}],"quiz":[{"s":"epp_give","v":[{"q":"¿Quién debe pagar el EPP que usas en la obra?","o":["La empresa, sin costo para el trabajador","El trabajador, descontado del sueldo","Mitad la empresa y mitad el trabajador","La mutualidad, al inicio de la obra"],"w":"La ley obliga al empleador a entregarlo gratis (Ley 16.744 art. 68; DS 594 art. 53)."},{"q":"Además de entregar el EPP, ¿qué debe hacer el empleador?","o":["Enseñar a usarlo correctamente","Cobrar una garantía por cada elemento","Revisar tu ropa personal","Nada más que entregarlo"],"w":"La entrega va junto con la instrucción de uso."},{"q":"Si pierdes tu casco, la empresa puede cobrarte el recambio en tu liquidación de sueldo.","vf":false,"w":"Falso. El EPP se entrega sin costo para el trabajador, también el recambio."}]},{"s":"pz_epp_ok_q","v":[{"q":"¿Cuál es el EPP básico para entrar a la obra?","o":["Casco con barbiquejo, zapatos de seguridad, ropa y guantes","Casco, zapatillas cómodas y ropa de calle oscura","Lentes, fonos y respirador en toda tarea","Chaleco reflectante y gorro de lana"],"w":"El básico se usa siempre; lo demás se suma según la tarea."},{"q":"¿Quién define qué EPP adicional lleva tu tarea?","o":["Tu IRL y tu jefatura","Cada trabajador según su gusto","El proveedor del EPP","El compañero con más años"],"w":"El EPP se elige según los riesgos de la tarea informados en tu IRL."},{"q":"Llegas a la obra con zapatillas porque tus zapatos de seguridad están mojados. ¿Qué corresponde?","o":["No entro a terreno y aviso a mi jefatura","Entro con cuidado de no pisar clavos","Trabajo solo la mañana con las zapatillas","Me pongo dos pares de calcetines"],"w":"Sin el EPP básico no se entra a la obra."}]},{"s":"pz_epp_barbiquejo","v":[{"q":"¿Para qué sirve el barbiquejo del casco?","o":["Para que el casco no se caiga al agacharte","Para que el casco no se ensucie","Para ajustar el tamaño del arnés interior del casco","Para colgar el casco al terminar"],"w":"Sin barbiquejo el casco se cae justo cuando más se necesita."},{"q":"Antes de ponerte el casco, ¿qué revisas?","o":["Que no tenga trizaduras ni el arnés interior roto","Solo que sea del color de tu cargo","Que tenga tu nombre escrito con plumón","Que esté recién lavado"],"w":"Un casco dañado ya no absorbe el golpe."},{"q":"Estás en un andamio y tienes que agacharte varias veces. ¿Cómo debe ir tu casco?","o":["Con el barbiquejo puesto y ajustado","Con el barbiquejo sobre la visera","Sin barbiquejo para no tener calor","En la mano mientras te agachas"],"w":"El barbiquejo mantiene el casco en su lugar en cualquier postura."}]},{"s":"pz_epp_respirador","v":[{"q":"Vas a cortar cerámica con esmeril angular en seco. ¿Qué EPP necesitas además del básico?","o":["Lentes, careta, protector auditivo y respirador","Solo guantes más gruesos y manga larga","Una mascarilla de tela de doble capa","Solo lentes, sin careta ni fonos"],"w":"El corte genera partículas, ruido y polvo de sílice."},{"q":"¿Qué protege del polvo de sílice al cortar hormigón?","o":["Un respirador con filtro bien sellado","Una mascarilla de tela de doble capa","Un pañuelo húmedo","Un buzo con capucha y mangas ajustadas"],"w":"La tela y la mascarilla común no retienen el polvo fino de sílice."},{"q":"Un compañero con barba usa respirador para cortar ladrillo. ¿Cuál es el problema?","o":["La barba impide que el respirador selle","No hay problema si el filtro es nuevo","La barba lo protege más","Solo afecta en días de lluvia"],"w":"Sin sello, el polvo entra por los bordes."}]},{"s":"c5ep_que","v":[{"q":"¿Qué hace realmente el EPP?","o":["Te protege de lo que no se pudo controlar antes","Elimina el peligro de la tarea","Reemplaza a las barandas y protecciones","Permite trabajar sin procedimiento"],"w":"Es la última barrera: no elimina el peligro."},{"q":"¿Por qué se dice que el EPP es la última barrera?","o":["Porque actúa cuando lo demás no bastó","Porque es lo último que se compra","Porque se usa al final de cada jornada","Porque es el control más barato"],"w":"Primero van eliminar, sustituir, ingeniería y administrativos."},{"q":"Si uso el EPP completo, el peligro de la tarea desaparece.","vf":false,"w":"Falso. El peligro sigue ahí; el EPP solo reduce el daño si está bien puesto."}]},{"s":"c5ep_cuida","v":[{"q":"Tu casco tiene una trizadura pequeña. ¿Qué haces?","o":["Pido uno nuevo de inmediato, sin costo","Le pongo cinta y lo sigo usando","Lo uso hasta fin de mes","Lo cambio por el de un compañero"],"w":"Un casco trizado ya no protege: se reemplaza sin costo."},{"q":"Tus guantes se rompieron en la palma mientras manipulabas fierros. ¿Qué corresponde?","o":["Pedir recambio antes de seguir","Seguir con cuidado hasta terminar","Darlos vuelta y usarlos al revés","Trabajar a mano descubierta"],"w":"EPP dañado es EPP que no protege."},{"q":"¿Cómo se guarda el EPP al terminar la jornada?","o":["Limpio, seco y lejos del sol directo","En el suelo de la obra","Mojado dentro de una bolsa cerrada","Sobre el tablero eléctrico"],"w":"Guardarlo bien alarga su vida útil y su protección."}]},{"s":"muffsBad","v":[{"q":"Un compañero usa la sierra circular con los fonos colgando del cuello. ¿Qué pasa?","o":["No lo protegen: deben ir sobre las orejas","Lo protegen igual por estar cerca","Lo protegen la mitad","Solo importa si el ruido dura todo el día"],"w":"El protector auditivo solo funciona bien puesto."},{"q":"¿Desde qué nivel de ruido se debe usar protector auditivo?","o":["85 decibeles","50 decibeles","120 decibeles","Solo cuando duele el oído"],"w":"Sobre 85 dB(A) el ruido daña el oído con la exposición diaria."},{"q":"El protector auditivo solo protege si está puesto sobre las orejas durante toda la exposición al ruido.","vf":true,"w":"Verdadero. Colgando del cuello o puesto a ratos no protege."}]},{"s":"epp_self","v":[{"q":"Hace calor y llevas dos horas cortando con esmeril. ¿Cuándo puedes sacarte los lentes?","o":["Cuando ya no esté expuesto a partículas","Cuando sienta que se empañan","Cada vez que el capataz no esté mirando","Después de la primera hora de trabajo"],"w":"El EPP se usa todo el tiempo que estés expuesto al riesgo."},{"q":"Tus guantes te quedan grandes y se te enredan. ¿Qué haces?","o":["Pido otra talla","Trabajo sin guantes","Les corto los dedos","Uso los del compañero"],"w":"El EPP debe quedarte bien; mal ajustado no protege y puede atraparte."},{"q":"“Es solo un minuto, no vale la pena ponerse el casco”. ¿Qué opinas?","o":["Es un error: el riesgo existe ese minuto","Es razonable si es muy rápido","Es correcto si nadie trabaja arriba","Depende del calor que haga"],"w":"Los accidentes ocurren justamente en esos minutos."}]}]},{"id":"orden","sec":"todos","mins":5,"title":"Orden y aseo en obra","thumb":"pz_orden_ok","learn":[{"s":"pz_orden_mal","t":"El desorden causa accidentes","x":"Despuntes de madera, clavos, fierros, cables, sacos vacíos y escombros en el paso provocan <b>tropiezos, caídas, torceduras, cortes y punzadas</b>. En obra, una gran parte de las lesiones vienen del desorden, y un tropiezo cerca de un borde o en un andamio puede terminar en una caída de altura. El orden es parte del trabajo, no una tarea aparte."},{"s":"pz_clavo","t":"Clavos hacia arriba","x":"Una tabla con clavos hacia arriba es una <b>punzada asegurada</b>: el clavo atraviesa la suela de cualquier zapato común y puede infectar la herida. Al desmoldar, <b>saca o dobla los clavos</b> en el momento, no al final del día, y acopia la madera ordenada y con los clavos hacia abajo mientras no los saques. Usa zapatos de seguridad con plantilla antiperforación."},{"s":"pz_acopio","t":"Acopio seguro","x":"Los materiales se apilan <b>sobre tacos, estables, nivelados y a baja altura</b>, y lejos de bordes de losa, vanos, zanjas y vías de tránsito. Los sacos de cemento, cruzados y sin pasar la altura que indique la jefatura. Los fierros, ordenados por tipo y con las <b>puntas protegidas</b> con capuchones. Nunca se acopia sobre andamios ni en el borde de una excavación."},{"s":"pz_orden_ok","t":"Escombros a su lugar","x":"Los escombros y la basura van al <b>contenedor o zona de escombros</b>, durante el turno, no al final. <b>Nunca se lanzan desde altura</b>, aunque abajo no se vea a nadie. Si hay que bajarlos, se hace por un <b>ducto</b> o con la grúa en un recipiente adecuado, con la zona de abajo cercada y señalizada.","k":"Nada se tira desde un piso."},{"s":"orden_spill","t":"Derrames y barro","x":"Aceite, petróleo, lechada de cemento o barro en el paso hacen resbalar. Ante un derrame: <b>avisa, señaliza</b> con un cono o cinta <b>y limpia</b> o cubre con material absorbente. Si es un químico, revisa su hoja de datos de seguridad antes de limpiar. Mantén limpios y despejados los accesos, rampas y escaleras, sobre todo en días de lluvia."},{"s":"pz_elec_ext_ok","t":"Cables y mangueras","x":"Las extensiones eléctricas y mangueras deben ir <b>por el borde o colgadas en altura</b>, nunca cruzando el paso, sobre charcos ni aplastadas por materiales o ruedas. Así nadie tropieza y no se daña el aislamiento. Al terminar, enróllalas y guárdalas. Una extensión pisada o mojada es riesgo de caída y de electrocución."},{"s":"c5or_salOk","t":"Accesos, extintores y tableros libres","x":"Las escaleras, accesos, vías de evacuación, extintores, tableros eléctricos y el botiquín deben estar <b>siempre despejados y a la vista</b>. Nada se apoya frente a ellos, ni siquiera por un rato. En una emergencia, unos segundos perdidos moviendo sacos o tablas pueden costar una vida.","k":"Si tapas una salida, tapas la vía de escape de todos."},{"s":"c5or_5s","t":"Termina ordenando","x":"Al terminar tu tarea y al final de la jornada, <b>deja tu frente de trabajo ordenado</b>: herramientas guardadas y desconectadas, materiales acopiados, escombros retirados y clavos sacados. Aplica las 5S: separar lo que no sirve, ordenar, limpiar, estandarizar y sostener el hábito todos los días. El que llega después, o tú mismo al día siguiente, lo agradece."}],"quiz":[{"s":"pz_orden_mal_q","v":[{"q":"En tu frente de trabajo hay despuntes, clavos y una extensión cruzando el paso. ¿Qué corresponde?","o":["Ordenar de inmediato antes de seguir","Seguir y ordenar al final del día","Avisar al aseo para que lo vea","Trabajar mirando bien dónde piso"],"w":"El desorden en el paso causa tropiezos, cortes y punzadas: se ordena durante el turno."},{"q":"¿Por qué un tropiezo es más peligroso cerca de un borde de losa o en un andamio?","o":["Puede terminar en una caída de altura","Porque ensucia la ropa","Porque se pierde tiempo","No es más peligroso que en el suelo"],"w":"Un tropiezo en altura puede llevar a una caída grave."},{"q":"¿Cuándo se debe ordenar el frente de trabajo?","o":["Durante todo el turno y al terminar","Solo los viernes","Solo cuando viene una visita","Cuando el capataz lo pide"],"w":"El orden es parte del trabajo, no una tarea aparte."}]},{"s":"pz_clavo","v":[{"q":"Al desmoldar, ¿qué haces con los clavos de las tablas?","o":["Los saco o los doblo en el momento","Los dejo para el final del día","Los tapo con tierra","Dejo las tablas con los clavos hacia arriba para verlos"],"w":"Un clavo hacia arriba provoca punzadas en los pies."},{"q":"Mientras no puedas sacar los clavos de las tablas desmoldadas, ¿cómo las dejas?","o":["Acopiadas con los clavos hacia abajo","Paradas contra el muro","Tiradas en el paso para verlas","Encima del andamio"],"w":"Así nadie pisa un clavo mientras se termina la tarea."},{"q":"Al desmoldar, los clavos de las tablas se sacan o se doblan en el momento, no al final del día.","vf":true,"w":"Verdadero. Mientras queden hacia arriba, cualquiera puede pisarlos."}]},{"s":"pz_orden_ok","v":[{"q":"Tienes escombros en el segundo piso. ¿Cómo se bajan?","o":["Por ducto o con grúa, con la zona de abajo cercada","Lanzándolos si abajo no hay nadie","Lanzándolos después de avisar con un grito fuerte","Acumulándolos en el borde de la losa para la grúa"],"w":"Nada se lanza desde altura: puede golpear a alguien que no viste."},{"q":"¿Cuándo se llevan los escombros al contenedor?","o":["Durante el turno, a medida que salen","Una vez por semana","Solo al terminar la obra","Al final de la semana, todos juntos"],"w":"Acumularlos los convierte en obstáculos y riesgo de tropiezo."},{"q":"Se pueden lanzar escombros desde el segundo piso si abajo no hay nadie.","vf":false,"w":"Falso. Se bajan por ducto o con grúa, con la zona de abajo cercada."}]},{"s":"pz_acopio","v":[{"q":"¿Cómo se acopian los materiales en la obra?","o":["Sobre tacos, estables, bajos y lejos de bordes","Lo más alto posible para ahorrar espacio","En el pasillo para tenerlos a mano","En el borde de la losa para izarlos rápido"],"w":"Así no se caen, no bloquean el paso ni sobrecargan bordes."},{"q":"¿Cómo se dejan los fierros acopiados?","o":["Ordenados y con las puntas protegidas","Parados contra el muro","Cruzando el paso para cortarlos","Sobre el andamio para tenerlos más a mano"],"w":"Las puntas descubiertas causan cortes y empalamientos."},{"q":"¿Dónde NO se debe acopiar material?","o":["En el borde de una zanja","Sobre tacos en una zona plana","En la zona de acopio señalizada","Lejos de las vías de tránsito"],"w":"El peso en el borde puede derrumbar la excavación."}]},{"s":"orden_spill","v":[{"q":"Ves aceite derramado en la escalera de acceso. ¿Qué haces?","o":["Aviso, señalizo y limpio o cubro","Paso con cuidado y sigo","Espero que se seque solo","Le echo agua con la manguera para diluirlo"],"w":"Un derrame en el paso es una caída esperando ocurrir."},{"q":"Se derramó un químico en la bodega de obra. ¿Qué revisas antes de limpiar?","o":["Su hoja de datos de seguridad","La fecha de compra","El color del envase","La guía de despacho del producto"],"w":"La HDS indica cómo limpiar y qué EPP usar."},{"q":"¿Cuál es el orden correcto ante un derrame en el paso?","o":["Avisar, señalizar y limpiar","Limpiar, avisar y señalizar","Señalizar y dejarlo","Limpiar sin avisar"],"w":"Primero se protege a los demás avisando y señalizando."}]},{"s":"pz_elec_ext_mal_q","v":[{"q":"Ves una extensión eléctrica cruzando el paso y dentro de un charco. ¿Qué corresponde?","o":["Llevarla por el borde o en altura, fuera del agua","Dejarla así si funciona","Taparla con un tablón para que nadie la pise","Cruzarla saltando y avisar a los demás que salten"],"w":"Una extensión en el paso y mojada es riesgo de caída y electrocución."},{"q":"¿Por dónde deben ir las extensiones y mangueras?","o":["Por el borde o colgadas en altura","Por el centro del pasillo","Bajo los materiales acopiados","Bajo los tablones del acceso para protegerlas"],"w":"Así no hay tropiezos ni se daña el aislamiento."},{"q":"¿Qué haces con la extensión al terminar la jornada?","o":["La enrollo y la guardo","La dejo conectada para mañana","La dejo estirada en el suelo","La cuelgo del tablero"],"w":"Guardarla evita daños y tropiezos."}]},{"s":"orden_exitBad","v":[{"q":"Un compañero deja tablas y cajas frente al extintor “solo por un rato”. ¿Qué haces?","o":["Le pido despejar de inmediato","Lo dejo si es menos de una hora","Muevo el extintor a otro lado","Pongo un cartel encima"],"w":"Extintores y salidas deben estar siempre libres."},{"q":"¿Qué debe estar siempre despejado en la obra?","o":["Accesos, salidas, extintores, tableros y botiquín","Solo la oficina de obra y su entrada principal","Solo la bodega","Solo el estacionamiento"],"w":"En una emergencia, cada segundo cuenta."},{"q":"Está bien dejar sacos frente al extintor si es por poco rato.","vf":false,"w":"Falso. Extintores, tableros y salidas se mantienen siempre libres."}]},{"s":"c5or_5s","v":[{"q":"Al terminar la jornada, ¿cómo debe quedar tu frente de trabajo?","o":["Ordenado y con las herramientas guardadas","Como quedó al terminar","Para que lo ordene el turno siguiente","Con las herramientas conectadas para el día siguiente"],"w":"Cada uno deja ordenado su frente."},{"q":"¿Qué significa “sostener” en las 5S?","o":["Mantener el hábito de orden todos los días","Sostener las herramientas con las dos manos","Apuntalar los moldajes","Sostener la escala al compañero"],"w":"La quinta S es mantener el orden como costumbre."},{"q":"¿Cuál es la primera S de las 5S?","o":["Separar lo que no sirve","Limpiar el piso","Pintar las herramientas","Sostener el hábito"],"w":"Primero se saca lo que no sirve; luego ordenar, limpiar, estandarizar y sostener."}]}]},{"id":"transito","sec":"todos","title":"Tránsito en obra: peatones, camiones y maquinaria","thumb":"pz_retro_ok","learn":[{"s":"pz_retro_radio","t":"Máquinas grandes, puntos ciegos","x":"Retroexcavadoras, camiones tolva, mixer, minicargadores y grúas tienen <b>puntos ciegos</b>: zonas donde el operador no te ve, sobre todo atrás y a los costados. El brazo de la retro y la parte trasera de la máquina <b>giran y alcanzan más de lo que parece</b>. Además, el ruido del motor tapa tus gritos."},{"s":"pz_retro_mal","t":"Nunca en el radio de giro","x":"No te pares, no pases ni trabajes dentro del <b>radio de giro</b> de una máquina en operación, ni detrás de un camión que retrocede. Mantén una distancia segura, señalizada con conos o cinta cuando corresponda. Nunca te subas a una máquina para trasladarte en el balde, las pisaderas o la tolva: solo el operador va en la cabina.","k":"Lejos del radio de giro de cualquier máquina."},{"s":"pz_retro_ok","t":"Contacto visual antes de acercarte","x":"Antes de acercarte o cruzar frente a una máquina:<ul><li><b>Detente</b> a distancia.</li><li>Busca <b>contacto visual</b> con el operador.</li><li>Espera su <b>señal</b> de que te vio y detuvo la máquina o bajó el balde.</li></ul>Si no te ha visto, no avances. Nunca camines por detrás de una máquina confiando en que el operador está atento."},{"s":"pz_senalero","t":"Señalero en retroceso","x":"Los retrocesos de camiones y las maniobras en espacios reducidos se hacen <b>con señalero</b>, ubicado donde el conductor lo vea en sus espejos y fuera de la trayectoria del vehículo. <b>Solo una persona</b> da las señales, para no confundir al conductor. Si el conductor pierde de vista al señalero, debe detenerse de inmediato.","k":"Reversa siempre con señalero."},{"s":"camion_conduccion_obra","t":"Accesos, velocidad y terreno","x":"Los camiones entran por el <b>acceso habilitado</b> y circulan a <b>velocidad baja</b>, la que indique la obra. Cuidado con el <b>terreno blando</b> y los bordes de zanjas, que pueden ceder con el peso, y con los <b>cables eléctricos aéreos</b> al levantar la tolva o la pluma. Los peatones esperan en la zona segura mientras el camión maniobra."},{"s":"transito_chaleco","t":"Que te vean","x":"Usa ropa de trabajo con <b>cintas reflectantes</b> y, en las zonas de maquinaria o cuando te lo indiquen, <b>chaleco reflectante</b>. Es clave al amanecer, al atardecer, con neblina o con lluvia, cuando la visibilidad baja. La ropa oscura sin reflectante hace que el conductor te vea demasiado tarde para frenar."},{"s":"transito_celular","t":"Sin celular al caminar","x":"Caminar mirando el celular en la obra es exponerse a tropezar, caer en una zanja o un vano, o ser atropellado por una máquina que no escuchaste. Tampoco se usan audífonos en terreno: te impiden oír alarmas y bocinas de retroceso. Si necesitas usar el teléfono, <b>detente en un lugar seguro</b>, fuera de las rutas de máquinas."},{"s":"pz_bienvenida","t":"Rutas peatonales","x":"Usa siempre las <b>rutas peatonales</b> y los accesos habilitados de la obra, separados del tránsito de máquinas. No acortes camino por zonas de excavación, de izaje o de maniobra de camiones, aunque parezca que no hay nadie trabajando. Respeta conos, cintas y letreros: si una zona está cerrada, es por algo."}],"quiz":[{"s":"pz_retro_mal_q","v":[{"q":"Un compañero espera parado al lado de la retroexcavadora mientras esta excava. ¿Qué problema hay?","o":["Está dentro del radio de giro","Ninguno si tiene casco","Ninguno si la máquina gira lento","Solo que estorba al operador"],"w":"El brazo y la parte trasera giran y alcanzan más de lo que parece."},{"q":"¿Dónde NO debes pararte nunca cuando trabaja una máquina?","o":["En su radio de giro o detrás si retrocede","A más de diez metros de distancia","En la ruta peatonal señalizada","Frente al operador, con contacto visual previo"],"w":"Esas son las zonas donde la máquina puede golpearte."},{"q":"Para llegar más rápido al otro frente, un compañero quiere ir en el balde de la retro. ¿Qué corresponde?","o":["No: el balde no es para trasladar personas","Sí, si el operador va despacio y lo sabe","Sí, si se afirma bien","Sí, si es una distancia corta"],"w":"Solo el operador va en la cabina; el balde no es para personas."}]},{"s":"pz_retro_radio","v":[{"q":"¿Por qué el operador de una máquina puede no verte aunque estés cerca?","o":["Por los puntos ciegos de la máquina","Porque no usa lentes","Porque siempre mira el suelo","Porque la cabina tiene vidrios oscuros"],"w":"Toda máquina grande tiene zonas que el operador no ve."},{"q":"¿Por qué gritarle al operador no es una forma segura de avisar que vas a pasar?","o":["El ruido del motor tapa los gritos","Porque es de mala educación","Porque el operador se distrae","Porque está prohibido hablar en la obra"],"w":"La señal segura es el contacto visual y esperar su respuesta."},{"q":"Si el operador está concentrado en su trabajo, puedo pasar rápido por detrás de la máquina.","vf":false,"w":"Falso. Siempre contacto visual y esperar la señal del operador."}]},{"s":"camion_conduccion_retro_ok","v":[{"q":"Un camión tolva debe retroceder hasta la zona de descarga. ¿Cómo se hace?","o":["Con un señalero a la vista del conductor","Tocando la bocina continuamente","Rápido para no estorbar a nadie","Con el conductor mirando por la ventana"],"w":"La reversa siempre se hace con señalero."},{"q":"¿Dónde debe ubicarse el señalero durante un retroceso?","o":["A la vista del conductor y fuera de su trayectoria","Justo detrás del camión","Arriba de la tolva","Detrás del camión, al centro, para que lo vea en ambos espejos"],"w":"El señalero se protege y se mantiene visible."},{"q":"Durante un retroceso, el conductor pierde de vista al señalero. ¿Qué debe hacer?","o":["Detenerse de inmediato","Seguir lento","Tocar la bocina y seguir","Acelerar para terminar luego"],"w":"Sin ver al señalero no hay maniobra segura."}]},{"s":"pz_retro_ok_q","v":[{"q":"¿Qué es lo primero antes de cruzar frente a una máquina en operación?","o":["Buscar contacto visual y esperar su señal","Cruzar corriendo","Levantar la mano y cruzar de inmediato por delante","Gritar fuerte y cruzar"],"w":"Primero te ve y te da la señal; después pasas."},{"q":"Cruzas cerca de una retro y el operador no te mira. ¿Qué haces?","o":["Me detengo hasta tener contacto visual","Paso rápido aprovechando que no está girando","Paso por detrás de la máquina","Le hago señas y paso"],"w":"Si no te ha visto, no avances."},{"q":"¿Qué señal indica que puedes acercarte a la máquina?","o":["Que el operador te vio, detuvo la máquina y te hizo la señal","Que la máquina va más lento","Que el motor suena más bajo y la máquina va en ralentí","Que hay otro compañero cerca de la máquina para avisar"],"w":"La máquina detenida y la señal del operador son la condición para acercarse."}]},{"s":"transito_chaleco","v":[{"q":"¿Para qué sirven las cintas reflectantes de la ropa de trabajo?","o":["Para que los conductores te vean","Para identificar a qué empresa perteneces","Para abrigar en invierno","Para reemplazar el casco"],"w":"Te hacen visible con poca luz."},{"q":"¿En qué momentos es más importante usar chaleco reflectante?","o":["Al amanecer, atardecer, con neblina o lluvia","Solo a mediodía","Solo dentro de la caseta","Solo a mediodía, con el sol más fuerte"],"w":"Con poca visibilidad, el conductor te ve más tarde."},{"q":"Las cintas reflectantes son aún más importantes al amanecer, al atardecer, con neblina o con lluvia.","vf":true,"w":"Verdadero. Con poca visibilidad, el reflectante permite que el conductor te vea a tiempo."}]},{"s":"transito_celular","v":[{"q":"¿Cuándo puedes usar el celular en la obra?","o":["Detenido en un lugar seguro, fuera de rutas","Caminando lento por la obra","Caminando por la ruta peatonal señalizada","Mientras esperas cerca de la retro"],"w":"En movimiento, los ojos van en el camino."},{"q":"¿Por qué no se usan audífonos en terreno?","o":["Impiden oír alarmas y bocinas","Porque gastan la batería","Porque molestan al capataz","Porque se pueden perder o dañar con el polvo"],"w":"El oído también te avisa de una máquina que se acerca."},{"q":"En terreno no se usan audífonos, porque impiden oír alarmas y bocinas de retroceso.","vf":true,"w":"Verdadero. El oído también te avisa de una máquina que se acerca."}]},{"s":"pz_zanja_intro","v":[{"q":"Para llegar más rápido, piensas cruzar por la zona de excavación. ¿Qué corresponde?","o":["Usar la ruta peatonal habilitada","Cruzar si no hay nadie trabajando","Cruzar si llevo casco","Cruzar por el borde con cuidado"],"w":"Las zonas de excavación, izaje y maniobra no son paso peatonal."},{"q":"Una zona está cerrada con conos y cinta, pero parece vacía. ¿Qué haces?","o":["La respeto y uso otro camino","Paso por debajo de la cinta","Saco un cono y paso","Paso si es por pocos metros"],"w":"Si una zona está cerrada, es por algo."},{"q":"¿Por dónde deben circular los peatones en la obra?","o":["Por las rutas peatonales habilitadas","Por donde haya menos barro y charcos","Por la ruta de camiones","Por el camino más corto"],"w":"Las rutas peatonales separan a las personas de las máquinas."}]},{"s":"pz_senalero","v":[{"q":"Durante el retroceso de un camión, ¿quién da las señales al conductor?","o":["Un solo señalero","Todos los que estén cerca","El capataz desde la caseta","Nadie si hay cámara de retroceso"],"w":"Una sola persona, para no confundir al conductor."},{"q":"Dos compañeros le hacen señas distintas al conductor que retrocede. ¿Cuál es el riesgo?","o":["Que el conductor se confunda y atropelle","Ninguno: entre más personas ayuden, mejor","Que se demore un poco más","Que se ensucie el camión"],"w":"Señales distintas generan errores en la maniobra."},{"q":"En un retroceso es más seguro que varios compañeros den señales al mismo tiempo.","vf":false,"w":"Falso. Solo una persona da las señales."}]}]},{"id":"cargas","sec":"todos","mins":5,"title":"Manejo manual de cargas en obra","thumb":"c5ca_tecnica","learn":[{"s":"c5ca_intro","t":"¿Qué es el manejo manual de carga?","x":"Es levantar, bajar, empujar, arrastrar o trasladar algo usando la fuerza de tu cuerpo: <b>sacos de cemento, fierros, moldajes, planchas, paneles, bloques, baldosas, tinetas o carretillas</b>. La lesión más común es en la <b>zona lumbar</b>, la espalda baja, seguida de hombros y rodillas. Una lesión de espalda puede durar meses o quedar para siempre."},{"s":"c5ca_limites","t":"Los límites de la ley","x":"La Ley 20.949 fija:<ul><li><b>25 kg</b> máximo para hombres adultos.</li><li><b>20 kg</b> para mujeres y menores de 18 años.</li><li>Las <b>embarazadas</b> no pueden cargar ni descargar manualmente.</li></ul>Un saco de cemento de 25 kg ya está en el límite. Si algo pesa más, se usa ayuda mecánica o se reparte entre varias personas. El límite no significa que 25 kg sean livianos.","k":"25 kg hombres, 20 kg mujeres y menores, embarazadas nada."},{"s":"c5ca_tecnica","t":"Levanta con las piernas","x":"<ul><li>Acércate a la carga, con los pies separados a los lados.</li><li>Flecta las rodillas y mantén la <b>espalda recta</b>.</li><li>Toma la carga firme, con toda la mano.</li><li>Levanta suave con la fuerza de las <b>piernas</b>, sin tirones.</li><li>Lleva la carga <b>pegada al cuerpo</b>, entre hombros y rodillas.</li></ul>Para bajarla, el mismo movimiento al revés."},{"s":"c5ca_giro","t":"No gires la cintura","x":"Si tienes que cambiar de dirección con la carga, <b>gira moviendo los pies</b>, no la cintura. Torcer el tronco con peso es una de las causas más comunes de lumbago. Tampoco levantes cargas por sobre los hombros ni las tomes estirando los brazos lejos del cuerpo: el esfuerzo en la espalda se multiplica."},{"s":"cc6_en_cargar","t":"Usa ayuda mecánica","x":"Para lo pesado o repetitivo usa <b>carretilla, carro, transpaleta, montacarga, huinche o grúa</b>. Mover 40 sacos al hombro, aunque cada uno esté bajo el límite, desgasta la espalda. Los fierros, moldajes, paneles y planchas largas se llevan <b>entre dos o más</b>. Revisa que la carretilla tenga la rueda inflada y no la sobrecargues.","k":"Si hay ayuda mecánica, se usa."},{"s":"c5ca_equipo","t":"Entre dos: uno dirige","x":"Al mover algo largo o pesado entre dos, <b>uno dirige</b> con la voz: “¡arriba!”, “¡vamos!”, “¡abajo!”. Ambos levantan y bajan al mismo tiempo, cada uno del mismo lado, y la carga va al mismo nivel. Antes de partir, revisen que el camino esté libre de escombros, fierros, desniveles y barro, y acuerden dónde la dejarán."},{"s":"c5ca_piensa","t":"Piensa antes de levantar","x":"Antes de tomar una carga, pregúntate: <b>¿cuánto pesa?</b> ¿Tiene filos, clavos o astillas? ¿El camino está libre? <b>¿Dónde la voy a dejar?</b> Si no sabes el peso, levanta un extremo para probar. Usa <b>guantes</b> para fierros, moldajes y bloques, y zapatos de seguridad por si se cae. Si es demasiado, pide ayuda."},{"s":"tmert_pausa","t":"Pausas y señales de alerta","x":"Alterna tareas pesadas con livianas y haz <b>pausas</b> breves para estirar. Si sientes dolor en la espalda, hombros o rodillas, hormigueo o pérdida de fuerza, <b>avisa temprano</b> a tu jefatura: una molestia ignorada se vuelve lesión. Si te lesionas levantando algo en el trabajo, es accidente del trabajo y se atiende en la ACHS."}],"quiz":[{"s":"c5ca_limites","v":[{"q":"¿Cuál es el peso máximo que un hombre adulto puede levantar manualmente según la ley?","o":["25 kg","30 kg","40 kg","50 kg"],"w":"La Ley 20.949 fija 25 kg para hombres adultos."},{"q":"¿Cuál es el máximo para mujeres y menores de 18 años?","o":["20 kg","15 kg","25 kg","30 kg"],"w":"La Ley 20.949 fija 20 kg para mujeres y menores de 18 años."},{"q":"Hay que mover una plancha de 45 kg. ¿Qué corresponde?","o":["Usar ayuda mecánica o moverla entre varios","Que la mueva el más fuerte","Moverla solo, pero en dos viajes cortos","Arrastrarla por el suelo uno solo"],"w":"Sobre el límite se usa ayuda mecánica o se reparte el peso."}]},{"s":"liftBad","v":[{"q":"Un compañero levanta un saco con la espalda doblada y las piernas rectas. ¿Qué debe corregir?","o":["Flectar rodillas, espalda recta, carga pegada","Levantar más rápido para cansarse menos","Tomar el saco con una sola mano por la punta","Girar la cintura al levantar"],"w":"La fuerza debe salir de las piernas, no de la espalda."},{"q":"¿Dónde debe ir la carga mientras la trasladas?","o":["Pegada al cuerpo, entre hombros y rodillas","Con los brazos estirados hacia adelante","Sobre la cabeza","A un costado, colgando de un solo brazo"],"w":"Mientras más lejos del cuerpo, más esfuerzo en la espalda."},{"q":"¿De dónde debe salir la fuerza al levantar un saco del suelo?","o":["De las piernas","De la espalda","De los brazos estirados","Del cuello"],"w":"Las piernas son más fuertes y protegen la columna."}]},{"s":"c5ca_giro","v":[{"q":"Tienes un saco en los brazos y debes dejarlo a tu lado. ¿Cómo giras?","o":["Moviendo los pies","Torciendo la cintura","Lanzándolo hacia el lado","Girando solo los hombros"],"w":"Torcer el tronco con peso causa lumbago."},{"q":"¿Cuál de estos movimientos es más dañino para la espalda?","o":["Girar la cintura con la carga en los brazos","Caminar con la carga pegada al cuerpo","Flectar las rodillas al bajar la carga","Mover los pies para cambiar de dirección"],"w":"La torsión con peso es una causa típica de lesión lumbar."},{"q":"Para dejar la carga a un lado, lo correcto es girar la cintura sin mover los pies.","vf":false,"w":"Falso. Se gira moviendo los pies."}]},{"s":"cc6_en_cargar","v":[{"q":"Tienes que mover 40 sacos de cemento al segundo piso. ¿Qué es lo mejor?","o":["Usar montacarga, huinche o grúa","Subirlos al hombro uno por uno","Subir dos sacos a la vez para terminar antes","Lanzarlos desde abajo a un compañero"],"w":"Para lo pesado y repetitivo se usa ayuda mecánica."},{"q":"Cada saco pesa 25 kg, dentro del límite. ¿Por qué igual conviene usar carretilla para mover muchos?","o":["Porque la repetición también desgasta la espalda","No conviene: está dentro del límite","Porque la carretilla es obligatoria siempre","Solo para terminar más rápido"],"w":"El esfuerzo repetido suma daño aunque cada carga esté bajo el límite."},{"q":"Aunque cada saco pese menos de 25 kg, moverlos muchas veces al hombro también desgasta la espalda.","vf":true,"w":"Verdadero. Para lo repetitivo se usa ayuda mecánica."}]},{"s":"c5ca_equipo","v":[{"q":"Al trasladar un moldaje largo entre dos, ¿qué es lo más importante?","o":["Que uno dirija y coordinen con la voz","Que cada uno camine a su ritmo","Llevarlo al hombro, cada uno a su paso","Que el más alto vaya adelante sin hablar"],"w":"Uno dirige y ambos se mueven al mismo tiempo."},{"q":"Antes de mover un panel entre dos, ¿qué deben revisar?","o":["Que el camino esté libre y dónde dejarlo","Solo el color del panel","Quién es el más fuerte de los dos","Nada, se va viendo en el camino mientras avanzan"],"w":"Un tropiezo con carga compartida lesiona a los dos."},{"q":"Van dos trasladando un fierro largo. ¿Cómo lo levantan?","o":["Al mismo tiempo, a la voz de uno","Primero uno y luego el otro","Cada uno cuando esté listo","El de atrás empuja y el de adelante tira"],"w":"Levantar a destiempo provoca tirones y golpes."}]},{"s":"cargas_q_emb","v":[{"q":"Una trabajadora embarazada te pide ayuda porque le pidieron mover cajas. ¿Qué dice la ley?","o":["No puede cargar ni descargar a mano","Puede cargar hasta 20 kg como las demás","Puede si las cajas son livianas y pocas","Puede si lo hace despacio"],"w":"La Ley 20.949 prohíbe que las embarazadas carguen manualmente."},{"q":"¿Cuánto peso puede cargar manualmente una trabajadora embarazada?","o":["Ninguno","Hasta 10 kg","Hasta 20 kg","Lo mismo que antes del embarazo"],"w":"La ley prohíbe la carga y descarga manual en el embarazo."},{"q":"Las trabajadoras embarazadas pueden cargar sacos si pesan menos de 20 kg.","vf":false,"w":"Falso. La ley prohíbe que carguen y descarguen manualmente."}]},{"s":"c5ca_piensa","v":[{"q":"Antes de levantar un fierro, ¿qué revisas?","o":["Peso, filos, camino y dónde dejarlo","Solo su largo y que no esté oxidado","Solo su largo","Que no esté mojado ni con barro"],"w":"Piensa antes de levantar y usa guantes."},{"q":"No sabes cuánto pesa una caja. ¿Qué haces?","o":["Levanto un extremo para probar antes","La levanto de golpe para ver","La empujo con el pie","La levanto con la espalda doblada"],"w":"Probar el peso evita sorpresas que lesionan."},{"q":"¿Qué EPP es clave al manipular fierros, moldajes y bloques?","o":["Guantes y zapatos de seguridad","Solo protector auditivo","Solo lentes, sin careta ni fonos","Ninguno si es por poco rato"],"w":"Protegen de cortes, astillas y de la caída de la carga."}]},{"s":"tmert_sintomas","v":[{"q":"Desde hace días sientes dolor y hormigueo en la espalda al cargar. ¿Qué haces?","o":["Aviso a mi jefatura de inmediato","Aguanto hasta que se pase solo","Me automedico y sigo","Pido cambio de tarea sin decir por qué"],"w":"Avisar temprano permite atenderte y cambiar la forma de trabajar."},{"q":"Te lesionas la espalda levantando sacos en la obra. ¿Qué es?","o":["Accidente del trabajo: se atiende en la ACHS","Un problema personal: se atiende por Fonasa","Nada, si puedo seguir trabajando","Una enfermedad común"],"w":"Toda lesión a causa del trabajo es accidente del trabajo."},{"q":"¿Cuál de estas es una señal de alerta que debes informar?","o":["Pérdida de fuerza en las manos","Hambre a la hora de almuerzo","Sed en días de calor","Sueño después de la jornada"],"w":"Hormigueo, dolor y pérdida de fuerza son alarmas tempranas de lesión."}]}]},{"id":"accidente","sec":"todos","mins":5,"title":"¿Qué hacer si tengo un accidente del trabajo?","thumb":"pz_avisa","learn":[{"s":"pz_ley","t":"Estás protegido por la Ley 16.744","x":"Todos los trabajadores están cubiertos por el seguro de la Ley 16.744 ante <b>accidentes del trabajo</b>, <b>accidentes de trayecto</b> y <b>enfermedades profesionales</b>. Incluye atención médica, medicamentos, rehabilitación y pago de licencia (subsidio), <b>sin costo</b> para ti. Lo paga la empresa con una cotización. No necesitas ningún trámite previo: basta con ser trabajador."},{"s":"accidente_que","t":"¿Qué es un accidente del trabajo?","x":"Es toda <b>lesión</b> que sufras <b>a causa o con ocasión</b> del trabajo y que te produzca incapacidad o muerte. Ejemplos en obra: un corte con un fierro, una punzada con un clavo, una caída de la escala, una torcedura al bajar del andamio, un lumbago al levantar sacos o una partícula en el ojo. Aunque parezca leve, sigue siendo un accidente del trabajo."},{"s":"pz_avisa","t":"Avisa de inmediato","x":"Aunque parezca leve, <b>avisa de inmediato</b> a tu capataz o jefe de obra, el mismo día y antes de irte. Así recibes atención a tiempo y queda registro de cómo, cuándo y dónde ocurrió. Si no avisas o lo cuentas días después, cuesta probar que fue en el trabajo y podrías perder la cobertura. Un corte pequeño también puede infectarse.","k":"Avisa de inmediato, aunque sea leve."},{"s":"accidente_donde","t":"¿Dónde me atiendo?","x":"En el centro de atención de tu <b>organismo administrador</b>, la mutualidad, no en tu consultorio ni con tu previsión de salud. <b>{EMP} está adherida a la ACHS</b>: el teléfono de emergencias es el <b>1404</b>. Si trabajas para un contratista o subcontratista, pregunta a tu jefatura cuál es tu mutualidad. Si el caso es grave, llama también al 131 (SAMU)."},{"s":"c5ac_diat","t":"La DIAT","x":"La empresa debe hacer la <b>Denuncia Individual de Accidente del Trabajo (DIAT)</b> ante la mutualidad, dentro de las 24 horas de conocido el accidente. Si no la hace, la puedes presentar <b>tú</b>, un familiar, el Comité Paritario o el médico que te atendió. Sin DIAT no hay registro del accidente, así que pide confirmación de que se hizo."},{"s":"pz_grave","t":"Accidente grave o fatal","x":"Es grave, por ejemplo, una caída de más de 1,8 metros, una amputación, un atrapamiento, una pérdida de conocimiento o un caso que requiera rescate o reanimación. Se debe:<ul><li><b>Paralizar</b> la faena afectada.</li><li><b>Delimitar</b> el área y no mover nada, salvo para socorrer.</li><li><b>Avisar de inmediato</b> a la jefatura, que informa a la Inspección del Trabajo y a la SEREMI de Salud.</li></ul>","k":"Grave o fatal: paralizar, delimitar y avisar."},{"s":"pz_botiquin_scene","t":"Si el lesionado es un compañero","x":"Da la alarma y llama al <b>131</b> o a la ACHS al 1404 si es grave. <b>No lo muevas</b>, salvo peligro inminente como fuego o derrumbe: podrías agravar una lesión de columna. Acompáñalo, abrígalo y háblale. Si sangra, presiona la herida con un paño limpio. No le des agua, comida ni medicamentos, y no hagas maniobras que no conoces."},{"s":"pz_trayecto","t":"Accidente de trayecto","x":"Es el que ocurre en el <b>trayecto directo</b>, de ida o regreso, entre tu casa y la obra. También está cubierto por la Ley 16.744. Si te desvías por motivos personales, como ir de compras, deja de ser trayecto directo. Avisa a tu jefatura de inmediato y reúne pruebas: parte o constancia de Carabineros, testigos o el comprobante de atención."},{"s":"accidente_ocultar","t":"No ocultes un accidente","x":"Ocultar un accidente te deja <b>sin cobertura</b> si después se complica, y evita que se corrija la causa: el próximo puede ser peor y afectar a otro compañero. Informar no es acusar. Después de un accidente se hace una <b>investigación</b> para encontrar las causas y corregirlas, no para buscar culpables. Los cuasi accidentes también se informan."}],"quiz":[{"s":"pz_avisa","v":[{"q":"Te cortas la mano con un fierro y parece leve. ¿Qué haces?","o":["Aviso de inmediato a mi capataz","Sigo y aviso al final de la semana","Me pongo una venda y no digo nada","Aviso solo si mañana sigue doliendo la mano"],"w":"Todo accidente se informa de inmediato para recibir atención y quedar cubierto."},{"q":"¿Por qué conviene avisar el mismo día un accidente, aunque sea leve?","o":["Para recibir atención y dejar registro","Para que te den el día libre","Para que sancionen al responsable del accidente","No conviene si fue leve"],"w":"Si avisas días después, cuesta probar que ocurrió en el trabajo."},{"q":"Te clavas un clavo en el pie, pero puedes seguir caminando. ¿Qué corresponde?","o":["Avisar y atenderme en la mutualidad","Seguir trabajando y lavarlo bien en la casa","Esperar a ver si se infecta","Pedir un analgésico a un compañero"],"w":"Una punzada puede infectarse; es accidente del trabajo y se atiende."}]},{"s":"accidente_donde","v":[{"q":"¿A qué mutualidad está adherida {EMP}?","o":["ACHS, teléfono 1404","Mutual de Seguridad","IST","Ninguna: se atiende por Fonasa"],"w":"{EMP} está adherida a la ACHS. Si trabajas para un contratista, pregunta la tuya."},{"q":"Te accidentas en la obra. ¿Dónde debes atenderte?","o":["En el centro de la ACHS, la mutualidad","En tu consultorio con Fonasa","En una clínica particular que tú pagues","En la farmacia más cercana"],"w":"Los accidentes del trabajo se atienden en la mutualidad, sin costo."},{"q":"Trabajas para un subcontratista dentro de la obra. ¿Qué haces para saber dónde atenderte?","o":["Pregunto a mi jefatura cuál es mi mutualidad","Voy siempre a la ACHS de {EMP}","Voy al consultorio","Espero a que me lo digan si me accidento"],"w":"Cada empleador tiene su propio organismo administrador."}]},{"s":"pz_trayecto","v":[{"q":"Te caes de la bicicleta en el camino directo de tu casa a la obra. ¿Qué es?","o":["Un accidente de trayecto, cubierto por la ley","Un accidente común, no cubierto","Un accidente del trabajo solo si estabas en la obra","Nada, porque aún no marcabas asistencia"],"w":"El trayecto directo de ida o regreso está cubierto."},{"q":"Al salir de la obra pasas al supermercado y te accidentas ahí. ¿Es accidente de trayecto?","o":["No, porque te desviaste por algo personal","Sí, siempre que sea el mismo día","Sí, porque ibas a tu casa","Sí, si aún llevabas puesta la ropa de trabajo"],"w":"Solo se cubre el trayecto directo."},{"q":"El accidente en el camino directo de tu casa a la obra está cubierto por la Ley 16.744.","vf":true,"w":"Verdadero: es accidente de trayecto."}]},{"s":"pz_grave","v":[{"q":"Un compañero cae desde una losa a más de 2 metros. Además de socorrerlo, ¿qué se hace?","o":["Paralizar, delimitar y avisar de inmediato","Ordenar el lugar para seguir trabajando","Esperar al otro día para informar","Retirar el andamio para que no estorbe"],"w":"Se paraliza la faena, se delimita sin mover nada y se avisa de inmediato."},{"q":"¿Cuál de estos es un accidente grave según la normativa?","o":["Una caída de más de 1,8 metros","Un corte superficial en un dedo","Una astilla en la mano","Un golpe leve en el casco"],"w":"Caída sobre 1,8 m, amputación, atrapamiento o pérdida de conocimiento son graves."},{"q":"Tras un accidente grave, ¿a quién informa la jefatura?","o":["A la Inspección del Trabajo y SEREMI de Salud","Solo al dueño de la obra","A Carabineros únicamente","A nadie más si el trabajador está consciente"],"w":"Los accidentes graves y fatales se informan de inmediato a esas autoridades."}]},{"s":"c5ac_diat","v":[{"q":"Si la empresa no hace la DIAT, ¿quién puede presentarla?","o":["Tú, un familiar, el Comité Paritario o el médico","Nadie más que el gerente de la empresa","Solo un abogado","Solo la Inspección del Trabajo, de oficio"],"w":"La ley permite que otros la presenten para no dejarte sin registro."},{"q":"¿Qué es la DIAT?","o":["La denuncia del accidente ante la mutualidad","El permiso médico para volver al trabajo","El informe de la investigación","La licencia médica común"],"w":"Es la Denuncia Individual de Accidente del Trabajo."},{"q":"¿En qué plazo debe la empresa presentar la DIAT?","o":["Dentro de 24 horas de conocido el accidente","Dentro de un mes","Al terminar la obra","Solo si el trabajador lo pide por escrito"],"w":"La denuncia se hace dentro de las 24 horas."}]},{"s":"accidente_ocultar","v":[{"q":"Un compañero se torció el tobillo y te pide que no digas nada. ¿Qué es lo correcto?","o":["Convencerlo de avisar, aunque sea leve","Guardar el secreto para no perjudicarlo con la empresa","Contarlo solo si empeora","Decirle que se vaya a su casa"],"w":"Ocultar un accidente lo deja sin cobertura y la causa no se corrige."},{"q":"¿Qué pasa si ocultas un accidente y días después se complica?","o":["Puedes quedar sin cobertura del seguro","Nada, igual te cubre todo","La empresa paga una multa por ti","Te atienden igual en la mutualidad sin preguntas"],"w":"Sin aviso oportuno cuesta probar que fue en el trabajo."},{"q":"Ocultar un accidente leve es lo mejor para no tener problemas.","vf":false,"w":"Falso. Te quedas sin cobertura y la causa no se corrige."}]},{"s":"pz_ley","v":[{"q":"¿Cuánto paga el trabajador por la atención de un accidente del trabajo?","o":["Nada: lo cubre el seguro de la ley","El copago de Fonasa","La mitad de la atención, con bono","Solo los medicamentos"],"w":"La atención, rehabilitación y licencia son sin costo."},{"q":"¿Qué cubre el seguro de la Ley 16.744?","o":["Accidentes del trabajo, de trayecto y enfermedades profesionales","Solo accidentes ocurridos dentro de la obra","Solo enfermedades comunes","Solo accidentes con licencia de más de 30 días"],"w":"Cubre los tres casos."},{"q":"¿Quién financia el seguro de la Ley 16.744?","o":["La empresa, con una cotización","El trabajador, con su sueldo","El Estado, con impuestos","La mutualidad, con sus ganancias"],"w":"El empleador paga la cotización del seguro."}]},{"s":"accidente_investiga","v":[{"q":"¿Para qué se investiga un accidente?","o":["Para encontrar las causas y corregirlas","Para buscar a quién sancionar","Para cumplir un trámite sin efecto","Para decidir si se paga la licencia"],"w":"La investigación busca prevenir, no culpar."},{"q":"¿Por qué se deben informar también los cuasi accidentes?","o":["Porque permiten corregir la causa a tiempo","Porque la mutualidad los exige para pagar licencias","Porque así se evita la investigación","No se informan: nadie se lesionó"],"w":"Cada cuasi accidente es un aviso para corregir."},{"q":"Informar un accidente sirve sobre todo para buscar culpables.","vf":false,"w":"Falso. Sirve para atender al lesionado e investigar las causas para corregirlas."}]}]},{"id":"incendios","sec":"todos","mins":5,"title":"Prevención de incendios y uso del extintor","thumb":"cc6_inc_ext","learn":[{"s":"incendios_tri","t":"¿Qué necesita el fuego?","x":"Tres cosas al mismo tiempo: <b>combustible</b> (madera de moldajes, cartón, aserrín, plumavit, solventes, pintura, gas), <b>calor</b> (chispas de esmeril o soldadura, cigarros, cortocircuitos, estufas) y <b>oxígeno</b> del aire. Si quitas uno de los tres, el fuego no se produce o se apaga. Prevenir es mantener separados el calor y el combustible."},{"s":"pz_cal_mal","t":"En obra: chispas y madera","x":"Soldar, cortar con esmeril angular o usar oxicorte cerca de <b>moldajes, aserrín, cartón, plumavit o solventes</b> es una causa típica de incendio en obra. Las chispas saltan varios metros y pueden quedar ardiendo sin llama. Antes de empezar, <b>retira o protege</b> lo combustible con mantas ignífugas y ten un extintor a mano."},{"s":"pz_cal_vigia","t":"Trabajos en caliente: permiso y vigía","x":"Soldadura, oxicorte y esmerilado se hacen con <b>permiso de trabajo</b> autorizado por la jefatura. Un <b>vigía de fuego</b> con extintor observa mientras se trabaja y se queda revisando el lugar al menos <b>30 minutos después</b> de terminar, porque las brasas pueden encenderse más tarde. El soldador usa careta, guantes y ropa adecuada."},{"s":"cc6_inc_clases","t":"Clases de fuego","x":"<ul><li><b>A:</b> sólidos, como madera, papel, cartón, plumavit.</li><li><b>B:</b> líquidos y gases inflamables, como pintura, solventes, petróleo, gas.</li><li><b>C:</b> equipos eléctricos energizados.</li><li><b>D:</b> metales combustibles.</li></ul>El extintor de polvo químico seco, PQS, sirve para A, B y C. Mira siempre la etiqueta: debe servir para ese fuego."},{"s":"cc6_inc_ext","t":"Uso del extintor","x":"<ul><li><b>1.</b> Saca el seguro.</li><li><b>2.</b> Apunta la boquilla a la <b>base</b> del fuego, no a las llamas.</li><li><b>3.</b> Presiona la manilla.</li><li><b>4.</b> Barre de lado a lado.</li></ul>Acércate a unos 2 o 3 metros, con el <b>viento a tu espalda</b> y la salida detrás de ti. Un extintor portátil dura pocos segundos: no lo desperdicies.","k":"Seguro, base, presiona y barre."},{"s":"c5or_salOk","t":"Extintores visibles y libres","x":"Los extintores deben estar <b>señalizados, a la vista, libres de obstáculos</b> y con su carga vigente: revisa que la aguja del manómetro esté en verde y que tenga su sello. Nunca los tapes con materiales. Si usaste uno, aunque sea un poco, <b>avisa</b> para que lo recarguen. Conoce dónde está el extintor más cercano a tu frente de trabajo."},{"s":"cc6_inc_gas","t":"Gas y cilindros","x":"Los cilindros de gas licuado, oxígeno y acetileno se guardan <b>de pie, amarrados o encadenados</b>, con su tapa, en un lugar <b>ventilado</b> y lejos del calor y del sol directo. Oxígeno y combustibles van separados. Si sientes olor a gas: <b>no enciendas nada</b>, ni el celular, cierra la válvula si es seguro, ventila y avisa. No fumes cerca."},{"s":"pz_elec_tablero_mal","t":"Fuego eléctrico","x":"Tableros dañados, extensiones sobrecargadas o enchufes con muchas zapatillas pueden incendiarse. En un fuego eléctrico <b>nunca uses agua</b>: conduce la electricidad. Corta la energía si es seguro, usa extintor apto, PQS o dióxido de carbono, y avisa. No sobrecargues enchufes ni uses extensiones con el cable dañado.","k":"En fuego eléctrico, nunca agua."},{"s":"cc6_inc_self","t":"Si el fuego crece, evacúa","x":"Si el fuego es grande, hay humo denso o no lo controlas en segundos, <b>no te arriesgues</b>: da la alarma gritando fuego, evacúa por la ruta señalizada hacia la zona de seguridad y llama al <b>132, Bomberos</b>, dando la dirección exacta de la obra. Nunca vuelvas por herramientas ni pertenencias."}],"quiz":[{"s":"incendios_extBien","v":[{"q":"Al usar el extintor, ¿hacia dónde apuntas la boquilla?","o":["A la base del fuego","A la punta de las llamas","Al humo","Al centro de las llamas, arriba"],"w":"A la base, donde está el combustible, barriendo de lado a lado."},{"q":"¿Cuál es el orden correcto para usar un extintor?","o":["Sacar el seguro, apuntar a la base, presionar y barrer","Presionar, sacar el seguro, apuntar y barrer","Apuntar a las llamas, presionar y sacar el seguro","Barrer, apuntar, presionar y sacar el seguro"],"w":"Primero el seguro; luego base, presionar y barrer."},{"q":"¿Dónde te ubicas para apagar un amago de incendio con extintor?","o":["Con el viento y la salida a mi espalda","Con el viento de frente","Entre el fuego y la salida","Lo más cerca posible de las llamas para no fallar"],"w":"Así el agente llega al fuego y tienes por dónde salir."}]},{"s":"pz_cal_mal_q","v":[{"q":"¿Qué haces antes de soldar cerca de moldajes de madera?","o":["Retiro lo combustible y tengo extintor a mano","Sueldo rápido para no dar tiempo","Mojo la madera y empiezo sin permiso","Pido a un compañero que apague las chispas con el pie"],"w":"Las chispas encienden madera y aserrín."},{"q":"¿Qué se necesita para hacer un trabajo en caliente en obra?","o":["Permiso de trabajo y vigía de fuego con extintor","Solo la careta de soldar","Solo avisar al compañero de al lado","Trabajar de noche para que haya menos gente"],"w":"El permiso asegura que se revisó el lugar y hay vigía."},{"q":"¿Cuánto tiempo, como mínimo, se queda el vigía revisando después de terminar la soldadura?","o":["30 minutos","2 minutos","Nada, se va con el soldador","Hasta el día siguiente"],"w":"Las brasas pueden encenderse un rato después."}]},{"s":"cc6_inc_extBien","v":[{"q":"Se encienden cartones y despuntes de moldaje. ¿Qué clase de fuego es?","o":["Clase A","Clase B","Clase C","Clase D"],"w":"Clase A: sólidos como madera y cartón."},{"q":"Un tarro de solvente se enciende en la bodega de obra. ¿Qué clase de fuego es?","o":["Clase B","Clase A","Clase C","Clase D"],"w":"Clase B: líquidos y gases inflamables."},{"q":"¿Para qué clases de fuego sirve el extintor de polvo químico seco, PQS?","o":["A, B y C","Solo A","Solo D","Solo B"],"w":"El PQS sirve para sólidos, líquidos y equipos eléctricos."}]},{"s":"pz_elec_tablero_mal_q","v":[{"q":"Sale fuego de un tablero eléctrico energizado. ¿Qué haces?","o":["Corto la energía si es seguro y uso PQS","Le echo agua con la manguera","Lo tapo con una frazada mojada para ahogarlo","Lo dejo y sigo trabajando"],"w":"El agua conduce la electricidad: nunca en fuego eléctrico."},{"q":"¿Cuál es una causa típica de incendio eléctrico en obra?","o":["Extensiones sobrecargadas o dañadas","Usar casco en la obra","Ordenar las herramientas","Guardar los cilindros de pie y amarrados"],"w":"La sobrecarga calienta los cables y puede encenderlos."},{"q":"En un tablero eléctrico encendido se puede usar agua si se tira desde lejos.","vf":false,"w":"Falso. El agua conduce la electricidad: riesgo de electrocución."}]},{"s":"pz_cal_cilindros","v":[{"q":"¿Cómo se guardan los cilindros de gas en la obra?","o":["De pie, amarrados, con tapa y ventilados","Acostados al sol","En la bodega cerrada junto a la estufa","Sueltos para moverlos rápido"],"w":"De pie, amarrados, ventilados y lejos del calor."},{"q":"Sientes olor a gas cerca de los cilindros. ¿Qué haces?","o":["No enciendo nada, ventilo y aviso","Prendo la luz para ver mejor","Busco la fuga con un encendedor","Llamo por celular a mi jefe junto a los cilindros"],"w":"Cualquier chispa puede provocar una explosión."},{"q":"¿Cómo se almacenan el oxígeno y el acetileno?","o":["Separados, de pie y encadenados","Juntos y acostados","Dentro de la caseta de obra","Al sol para que no se enfríen"],"w":"Oxígeno y combustibles van separados para evitar incendios."}]},{"s":"cc6_inc_self","v":[{"q":"El fuego crece y no lo controlas en segundos. ¿Qué haces?","o":["Doy la alarma, evacúo y llamo al 132","Sigo intentando solo con otro extintor","Voy a buscar mis cosas a la caseta","Busco otro extintor en el fondo de la obra"],"w":"No te arriesgues: evacúa y llama a Bomberos."},{"q":"¿A qué número llamas para pedir Bomberos?","o":["132","131","133","1404"],"w":"132 Bomberos, 131 SAMU, 133 Carabineros."},{"q":"Al llamar a Bomberos, ¿qué es lo primero que debes decir?","o":["La dirección exacta de la obra","El nombre de tu jefe","El nombre de la empresa","Qué herramientas había"],"w":"Sin dirección exacta, la ayuda no llega a tiempo."}]},{"s":"c5or_salMal","v":[{"q":"Hay sacos y cajas apilados delante del extintor. ¿Qué corresponde?","o":["Despejarlo de inmediato","Dejarlo si es por poco rato","Poner un letrero que diga extintor","Moverlo a la bodega"],"w":"Un extintor tapado no se puede usar a tiempo."},{"q":"Usaste un poco el extintor para apagar un amago. ¿Qué haces después?","o":["Aviso para que lo recarguen","Lo dejo en su lugar sin decir nada","Lo guardo en la bodega","Lo sigo usando hasta que se acabe"],"w":"Un extintor usado, aunque sea poco, debe recargarse."},{"q":"Los extintores se pueden tapar con sacos si hay poco espacio en la obra.","vf":false,"w":"Falso. Siempre visibles, señalizados y libres."}]},{"s":"incendios_tri","v":[{"q":"El fuego necesita combustible, calor y...","o":["Oxígeno","Agua","Humedad","Polvo"],"w":"Triángulo del fuego: combustible, calor y oxígeno."},{"q":"¿Cuál es la mejor forma de prevenir un incendio en obra?","o":["Separar el calor del combustible","Tener siempre un balde con arena junto a la caseta","Trabajar solo de día","Usar ropa de algodón"],"w":"Sin unión de calor y combustible, no hay fuego."},{"q":"Si se quita uno de los tres elementos del triángulo del fuego, el fuego se apaga.","vf":true,"w":"Verdadero. El fuego necesita combustible, calor y oxígeno al mismo tiempo."}]}]},{"id":"emergencias","sec":"todos","title":"Emergencias, sismos y evacuación en obra","thumb":"emergencias_sismo","learn":[{"s":"emergencias_tipos","t":"¿Qué emergencias pueden ocurrir en obra?","x":"En una obra pueden ocurrir: <b>sismo, incendio, fuga de gas, corte de luz</b>, un <b>accidente grave</b> (caída de altura, atrapamiento, golpe por carga) o el <b>derrumbe de una excavación</b>. Cada emergencia tiene una respuesta distinta, y la debes conocer <b>antes</b> de que ocurra: en el momento no hay tiempo para aprender. Piensa hoy qué harías en cada caso desde tu puesto de trabajo."},{"s":"emergencias_plan","t":"El plan de emergencia de la obra","x":"{EMP} tiene un <b>plan de emergencia</b> en cada obra. Desde tu primer día debes saber:<ul><li>cómo suena la <b>alarma</b> (sirena, pito o megáfono);</li><li>cuáles son las <b>vías de evacuación</b>;</li><li>dónde está la <b>zona de seguridad</b> o punto de encuentro;</li><li>quién es el <b>líder de la emergencia</b> y dónde están extintores y botiquín.</li></ul>Si no lo sabes, pregúntale hoy a tu capataz."},{"s":"emergencias_sismo","t":"Durante un sismo","x":"Detén la tarea y <b>apaga</b> máquinas y herramientas. Aléjate de bordes de losa, cargas suspendidas, muros recién levantados y acopios altos. <b>Agáchate, cúbrete y afírmate</b> donde no te caiga nada encima. Si estás en un andamio o en altura, <b>afírmate y quédate</b> hasta que pase: no bajes por escalas ni andamios mientras tiembla. El operador de grúa baja la carga si puede y detiene el giro.","k":"Mientras tiembla, nadie baja por escalas ni andamios."},{"s":"emergencias_evac","t":"Evacuar con orden","x":"Evacúa cuando suene la alarma o lo ordene el líder. <b>Camina, no corras</b>, por la vía señalizada, y no uses el montacargas ni el ascensor de obra. <b>No vuelvas</b> por herramientas, mochila ni celular. Ayuda a quien lo necesite y avanza a la zona de seguridad. Después de un sismo fuerte, escaleras, losas y andamios pueden haber quedado dañados: no los uses hasta que se revisen."},{"s":"emergencias_conteo","t":"En la zona de seguridad","x":"Ahí el líder <b>cuenta a todos</b> con la lista de asistencia del día. Quédate en el grupo hasta que te autoricen a salir: si te vas sin avisar, te darán por perdido y alguien podría arriesgarse a buscarte. Si falta un compañero, <b>avisa de inmediato</b> al líder o a Bomberos y di dónde lo viste por última vez. <b>Nadie vuelve a entrar</b> hasta que se autorice."},{"s":"emergencias_incendio","t":"Incendio: amago o evacuación","x":"Da la alarma gritando <b>fuego</b> y avisa a tu jefatura. Solo si el fuego es pequeño, sabes usar el extintor y tienes la <b>salida a tu espalda</b>, intenta apagarlo: <b>saca el seguro, apunta a la base</b> de las llamas, <b>presiona</b> la manilla y <b>barre</b> de lado a lado. Si el fuego crece, hay humo denso o se acaba el extintor, <b>evacúa</b> y llama al 132."},{"s":"pz_zanja_mal","t":"Derrumbe de excavación","x":"Si una zanja se derrumba con alguien dentro, <b>no te metas</b>: el terreno puede volver a ceder y serían dos víctimas. Da la alarma, <b>detén la maquinaria</b> y aléjala del borde, llama al <b>131 y al 132</b> y aleja a los curiosos. Es un <b>accidente grave</b>: se paraliza la faena, se delimita la zona y la jefatura informa a la Inspección del Trabajo y a la SEREMI de Salud.","k":"No te conviertas en la segunda víctima: nunca entres a una zanja derrumbada."},{"s":"emergencias_llamar","t":"Números de emergencia","x":"<ul><li><b>131</b> Ambulancia, SAMU</li><li><b>132</b> Bomberos</li><li><b>133</b> Carabineros</li><li><b>1404</b> ACHS</li></ul>Al llamar, di primero la <b>dirección exacta de la obra</b> con una referencia, luego qué pasó, cuántos lesionados hay y cómo están (si respiran, si responden). No cortes hasta que te lo indiquen y deja a alguien en el acceso para guiar a la ambulancia."},{"s":"pz_botiquin_scene","t":"Primeros auxilios mientras llega la ayuda","x":"Ubica el <b>botiquín</b> de la obra y a los compañeros capacitados en primeros auxilios. Con un lesionado: <b>no lo muevas</b>, salvo peligro inminente como fuego o un nuevo derrumbe; <b>acompáñalo, abrígalo</b> y háblale. No le des agua, comida ni medicamentos. Si sangra, presiona la herida con un paño limpio. No hagas maniobras que no conoces."}],"quiz":[{"s":"pz_andamio_ok","v":[{"q":"Estás armando moldaje sobre un andamio y empieza a temblar fuerte. ¿Qué haces?","o":["Me afirmo al andamio y espero que pase para bajar","Bajo por la escalera del andamio con 3 apoyos","Paso a la losa para quedar en terreno firme","Camino por la plataforma hasta el acceso"],"w":"Bajar por escalas o andamios mientras tiembla es más peligroso que quedarse afirmado."},{"q":"Te pilla un sismo en la plataforma de un andamio a 4 metros. Lo correcto es:","o":["Quedarme afirmado hasta que deje de temblar","Bajar rápido antes de que el sismo aumente","Saltar a la losa más cercana","Soltar el arnés para poder moverme"],"w":"Mientras tiembla nadie baja: te afirmas y bajas con calma cuando pasa."},{"q":"Si tiembla mientras estás en un andamio, debes bajar de inmediato por la escalera para llegar a la zona de seguridad.","vf":false,"w":"Falso. Mientras tiembla te afirmas y esperas; bajas cuando el sismo termina."}]},{"s":"emergencias_auto","v":[{"q":"Suena la alarma de evacuación y tu mochila con el celular quedó en el segundo piso. ¿Qué haces?","o":["Evacúo caminando sin volver por ella","Subo rápido, porque está cerca de la escalera","Le pido a un compañero que la traiga al bajar","Espero en mi puesto a que termine la alarma"],"w":"Ningún objeto vale volver: se evacúa de inmediato y sin regresar."},{"q":"Al evacuar la obra, lo correcto es:","o":["Caminar por la vía señalizada a la zona de seguridad","Correr para salir lo antes posible","Bajar en el montacargas para llegar más rápido","Salir por la ruta más corta aunque no esté señalizada"],"w":"Caminar evita caídas y atropellos; la vía señalizada es la que se revisó como segura."},{"q":"Ya estás en la zona de seguridad y recuerdas que dejaste tu taladro enchufado. ¿Qué haces?","o":["Aviso al líder y me quedo en la zona de seguridad","Vuelvo corriendo a desenchufarlo","Pido permiso a un compañero y voy rápido","Voy a buscarlo apenas pare la alarma"],"w":"Nadie vuelve a entrar hasta que se autorice; avisar es suficiente."}]},{"s":"emergencias_conteo","v":[{"q":"En la zona de seguridad notas que falta un compañero de tu cuadrilla. ¿Qué haces?","o":["Aviso al líder y digo dónde lo vi por última vez","Vuelvo solo a buscarlo a su puesto","Espero a que aparezca sin decir nada","Lo llamo al celular y vuelvo si no contesta"],"w":"Avisar permite que el rescate entre sabiendo dónde buscar; tú no vuelves a entrar."},{"q":"Terminó la evacuación y quieres irte a tu casa. ¿Qué haces?","o":["Espero el conteo y que me autoricen a salir","Me voy, porque ya estoy fuera de la obra","Le aviso por mensaje a un compañero y me voy","Me voy si ya pasó el peligro"],"w":"Si te vas sin avisar te darán por perdido y alguien podría arriesgarse a buscarte."},{"q":"Si en el conteo falta un compañero, avisas al líder o a Bomberos y no vuelves tú a buscarlo.","vf":true,"w":"Verdadero. El rescate lo hacen equipos preparados."}]},{"s":"pz_zanja_mal","v":[{"q":"Una zanja sin entibar se derrumba y un compañero queda tapado hasta la cintura. ¿Qué haces primero?","o":["Doy la alarma, detengo la maquinaria y llamo al 131 y 132","Bajo de inmediato con una pala a desenterrarlo","Acerco la retroexcavadora para sacar la tierra","Lo tiramos de los brazos entre dos"],"w":"Entrar o acercar máquinas puede provocar otro derrumbe y más víctimas."},{"q":"¿Por qué no debes meterte a una zanja recién derrumbada para rescatar a alguien?","o":["Porque el terreno puede volver a ceder","Porque primero hay que terminar el conteo","Porque solo Carabineros puede autorizarlo","Porque hay que esperar a la ACHS"],"w":"Un segundo derrumbe dejaría dos víctimas en vez de una."},{"q":"Si una zanja se derrumba con alguien dentro, lo correcto es meterse de inmediato a sacarlo con las manos antes de que llegue la ayuda.","vf":false,"w":"Falso. Se da la alarma, se detiene la maquinaria y se llama al 131 y 132."}]},{"s":"emergencias_llamar","v":[{"q":"¿Cuál es el número de Bomberos?","o":["132","131","133","1404"],"w":"131 SAMU, 132 Bomberos, 133 Carabineros, 1404 ACHS."},{"q":"Un compañero cae de una escala y no responde. ¿A qué número llamas para pedir una ambulancia?","o":["131","132","133","1404"],"w":"El 131 es el SAMU, la ambulancia de urgencia."},{"q":"¿Cuál es el número de emergencia de la ACHS?","o":["1404","131","133","1414"],"w":"La ACHS atiende en el 1404; para riesgo vital, también el 131."}]},{"s":"emergencias_llamar","v":[{"q":"Al llamar a emergencias, lo primero que debes dar es:","o":["La dirección exacta de la obra y una referencia","Tu nombre completo y tu RUT","El nombre de la empresa y de tu jefe","El número de tu credencial de la ACHS"],"w":"Sin dirección exacta la ayuda no llega, aunque sepan todo lo demás."},{"q":"Llamas al 131 por un trabajador herido. ¿Qué información das?","o":["Dirección, qué pasó, cuántos heridos y cómo están","Solo que hay un herido grave en una obra","El nombre del herido y su previsión","Qué máquina causó el accidente"],"w":"Con esos datos el SAMU decide qué recursos enviar y llega más rápido."},{"q":"Ya pediste la ambulancia. ¿Qué más ayuda a que llegue rápido?","o":["Dejar a alguien en el acceso para guiarla","Cortar la llamada para dejar la línea libre","Llevar al herido caminando a la calle","Llamar de nuevo cada dos minutos"],"w":"En una obra grande el acceso no siempre es claro; alguien debe guiar a la ambulancia."}]},{"s":"emergencias_plan","v":[{"q":"Es tu primer día en la obra. ¿Qué debes saber sobre emergencias?","o":["La alarma, la vía de evacuación y la zona segura","Solo el número de la ACHS y el del SAMU","Dónde se firma el libro de asistencia diario","Nada todavía: se explica en el simulacro"],"w":"El plan de emergencia se conoce antes de que ocurra algo."},{"q":"No sabes dónde queda la zona de seguridad de esta obra. ¿Qué haces?","o":["Le pregunto hoy a mi capataz","Espero al próximo simulacro para saber","Sigo al resto si hay una emergencia","Elijo un lugar abierto cerca de mi puesto"],"w":"Hay que saberlo desde el primer día: en la emergencia no hay tiempo."},{"q":"Debes conocer desde tu primer día cómo suena la alarma y dónde está la zona de seguridad de la obra.","vf":true,"w":"Verdadero. Es parte del plan de emergencia."}]},{"s":"pz_botiquin_scene","v":[{"q":"Un compañero se cayó y está consciente en el suelo, quejándose de la espalda. ¿Qué haces?","o":["No lo muevo, lo abrigo, lo acompaño y pido ayuda","Lo siento con cuidado para que respire mejor","Le doy agua y un analgésico del botiquín","Lo llevamos entre dos a la caseta"],"w":"Mover a un lesionado puede agravar una lesión de columna."},{"q":"¿En qué caso se puede mover a un lesionado sin esperar a la ambulancia?","o":["Si hay peligro inminente, como fuego o derrumbe","Si el lesionado dice que puede caminar","Si la ambulancia tarda más de 10 minutos","Si lo autoriza un compañero de cuadrilla"],"w":"Solo un peligro mayor justifica moverlo antes de que llegue la ayuda."},{"q":"Un compañero se hizo un corte que sangra bastante en el brazo. ¿Qué haces mientras llega ayuda?","o":["Presiono la herida con un paño limpio","Le lavo la herida con diluyente","Le doy agua con azúcar","Le pongo un torniquete con alambre"],"w":"La presión directa con un paño limpio es lo primero para frenar el sangrado."}]}]},{"id":"senaletica","sec":"todos","title":"Señalización de seguridad en obra","thumb":"signsAll","learn":[{"s":"signsAll","t":"¿Para qué sirven las señales?","x":"Las señales te avisan de un <b>peligro</b>, te <b>prohíben</b> algo, te <b>obligan</b> a usar un EPP o te muestran la <b>salida</b> y los equipos de emergencia. El DS 594 obliga a señalizar los riesgos del lugar de trabajo. Se reconocen por <b>forma y color</b>, para entenderlas de lejos y sin leer. No son decoración: <b>cumplirlas es obligatorio</b> y está en el Reglamento Interno."},{"s":"senaletica_prohib","t":"Prohibición: círculo rojo con barra","x":"Círculo rojo con una barra cruzada: <b>eso no se hace</b>. Ejemplos en obra: <b>prohibido fumar</b> junto a acopios de madera, OSB, aislapol o combustibles, porque arden con facilidad; <b>prohibido el paso</b> a la zona de izaje o excavación; <b>prohibido el ingreso</b> de personas no autorizadas. La prohibición rige aunque nadie te esté mirando."},{"s":"senaletica_oblig","t":"Obligación: círculo azul","x":"Círculo azul con un dibujo blanco: <b>uso obligatorio</b> desde ese punto. En obra: <b>casco, protector auditivo, lentes, respirador</b>, arnés o calzado de seguridad. Si la señal de la zona de corte pide fonos y lentes, se usan aunque sea un solo corte. Si te falta el EPP, pídelo antes de entrar: la empresa lo entrega gratis."},{"s":"senaletica_adv","t":"Advertencia: triángulo amarillo","x":"Triángulo amarillo con borde negro: <b>atención, hay un peligro</b> cerca. En obra: caída a distinto nivel, riesgo eléctrico, cargas suspendidas, tránsito de grúa horquilla o maquinaria, excavación abierta. La advertencia no te prohíbe pasar, pero te exige ir <b>atento</b>, por la ruta peatonal y con el EPP que corresponda."},{"s":"senaletica_evac","t":"Evacuación y emergencia: verde y rojo","x":"<b>Verde</b>, en cuadrado o rectángulo: vías de evacuación, salidas, zona de seguridad y primeros auxilios. <b>Rojo</b>, en cuadrado o rectángulo: ubicación de <b>extintores</b>, red húmeda y equipos contra incendio. Ojo: el rojo en un <b>círculo con barra</b> prohíbe, pero el rojo en un <b>cuadrado</b> te muestra un equipo contra incendio."},{"s":"pz_izaje_ok","t":"Cintas, conos y barreras","x":"La obra se delimita con <b>cinta de peligro, conos, mallas y barreras</b>: zonas de izaje, excavaciones, bordes de losa, vanos y áreas bajo trabajos en altura. Una zona cercada <b>no se cruza</b>, ni siquiera para acortar camino o porque la grúa está detenida. Solo la mueve quien la instaló o alguien autorizado, y se repone al terminar.","k":"Una zona cercada no se cruza ni se mueve sin autorización."},{"s":"senaletica_sga","t":"Etiquetas de productos químicos","x":"Los envases de productos peligrosos llevan pictogramas en un <b>rombo de borde rojo, fondo blanco y símbolo negro</b> (DS 57). Indican si el producto es inflamable, corrosivo, tóxico o irritante. En obra: diluyente, desmoldante, aditivos, adhesivos y espuma de poliuretano. Lee la etiqueta y la <b>hoja de datos de seguridad</b> antes de usarlo, y nunca traspases un producto a una botella sin etiqueta."},{"s":"senaletica_tapada","t":"Señales visibles y en buen estado","x":"Una señal tapada, rota, caída o descolorida no avisa nada. <b>Nunca acopies</b> material, moldajes ni escombros delante de una señal, un extintor o una salida. Si ves una señal en mal estado, o una que ya no corresponde porque la obra avanzó, <b>avisa</b> a tu capataz o al prevencionista para reponerla.","k":"Nunca tapes una señal, un extintor ni una salida."},{"s":"pz_andamio_tarjetas","t":"Tarjetas de andamios","x":"Los andamios se identifican con tarjetas: <b>verde</b>, apto para usar; <b>amarilla</b>, uso con restricción, por ejemplo con arnés anclado; <b>roja</b>, no usar, porque está en armado o tiene una falla. Mira la tarjeta <b>antes de subir</b>. Si el andamio no tiene tarjeta, no subas hasta que un responsable lo revise."}],"quiz":[{"s":"senaletica_oblig","v":[{"q":"Al entrar a la zona de corte ves un círculo azul con unos fonos dibujados. ¿Qué significa?","o":["Que usar protector auditivo ahí es obligatorio","Que hay ruido y se recomienda usar fonos","Que está prohibido usar audífonos de música","Que ahí se entregan protectores auditivos"],"w":"El círculo azul indica obligación, no una recomendación."},{"q":"Las señales circulares de color azul indican:","o":["Una obligación, como usar un EPP","Una advertencia de peligro cercano","Una prohibición para el personal","Un equipo de emergencia cercano"],"w":"Azul circular = uso obligatorio."},{"q":"Si una señal azul indica uso obligatorio de lentes, puedes no usarlos si vas a hacer un solo corte rápido.","vf":false,"w":"Falso. La obligación rige desde la señal, sin importar cuánto dure la tarea."}]},{"s":"senaletica_adv","v":[{"q":"Un triángulo amarillo con borde negro indica:","o":["Advertencia de un peligro cercano","Prohibición de pasar por ese lugar","Uso obligatorio de un EPP","Ubicación de una salida de emergencia"],"w":"El triángulo amarillo advierte un peligro."},{"q":"En tu camino hay un triángulo amarillo de tránsito de grúa horquilla. ¿Qué significa?","o":["Puedo pasar, pero atento y por la ruta peatonal","Está prohibido pasar por ese sector","Solo pueden pasar los operadores","Debo esperar a que alguien me autorice"],"w":"La advertencia no prohíbe: exige atención al peligro que indica."},{"q":"Una señal de advertencia no prohíbe pasar, pero exige ir atento al peligro que indica.","vf":true,"w":"Verdadero. Para prohibir se usa el círculo rojo con barra."}]},{"s":"pz_izaje_ok","v":[{"q":"Vas atrasado y la ruta más corta a la bodega cruza una zona de izaje cercada con cinta. ¿Qué haces?","o":["Doy la vuelta por fuera de la zona cercada","Cruzo rápido mirando siempre hacia arriba","Cruzo solo si el gruero me hace una seña","Levanto la cinta y paso agachado sin tocarla"],"w":"Una zona cercada no se cruza, aunque vayas apurado."},{"q":"¿Quién puede mover o retirar la barrera que delimita una excavación?","o":["Quien la instaló o alguien autorizado","Cualquier trabajador que necesite pasar","El operador de la máquina que va a pasar","Quien la necesite, si después la repone"],"w":"Mover una barrera sin autorización deja el peligro sin control."},{"q":"Puedes cruzar la cinta de una zona de izaje si la grúa está detenida en ese momento.","vf":false,"w":"Falso. La grúa puede moverse en cualquier momento; la zona cercada no se cruza."}]},{"s":"senaletica_evac","v":[{"q":"Las señales verdes indican:","o":["Vías de evacuación, salidas y primeros auxilios","Peligros que exigen ir con atención","Extintores y equipos contra incendio","Zonas donde hay que usar un EPP"],"w":"Verde = evacuación y auxilio; rojo cuadrado = equipo contra incendio."},{"q":"Necesitas un extintor. ¿Qué señal te indica dónde está?","o":["Un cuadrado rojo con el dibujo del extintor","Un rectángulo verde con una flecha","Un círculo rojo con una barra","Un triángulo amarillo con borde negro"],"w":"Los equipos contra incendio se señalan con rojo en cuadrado o rectángulo."},{"q":"Hay un accidente y necesitas el botiquín. ¿Qué señal buscas?","o":["Una señal verde con una cruz blanca","Una señal roja con una cruz blanca","Un círculo azul con una cruz","Un triángulo amarillo con una cruz"],"w":"Primeros auxilios se señalan en verde."}]},{"s":"pz_andamio_tarjetas","v":[{"q":"Un andamio con tarjeta roja:","o":["No se usa: está en armado o con falla","Se usa con arnés anclado","Se usa solo con experiencia","Se usa si está el capataz presente"],"w":"Roja = no usar."},{"q":"Vas a subir a un andamio con tarjeta amarilla. ¿Qué significa?","o":["Uso con restricción, por ejemplo con arnés anclado","Apto para usar, sin ninguna condición extra","No usar, porque está en armado o con falla","Uso solo para guardar materiales arriba"],"w":"Amarilla = se usa cumpliendo la restricción indicada."},{"q":"Llegas a un andamio que no tiene ninguna tarjeta. ¿Qué haces?","o":["No subo hasta que un responsable lo revise","Subo si se ve completo y con barandas","Subo con arnés para mayor seguridad","Subo si un compañero ya lo está usando"],"w":"Sin tarjeta no se sabe si fue revisado."}]},{"s":"senaletica_tapada","v":[{"q":"Una cuadrilla acopió moldajes delante del extintor y de una señal. ¿Qué haces?","o":["Aviso para despejarlos: deben quedar a la vista","Lo dejo así, todos saben dónde está","Pongo una cinta encima para marcarlo","Lo dejo si es solo por esta semana"],"w":"Un extintor o una señal tapados no sirven en una emergencia."},{"q":"Una señal de riesgo eléctrico está caída en el suelo junto al tablero. ¿Qué haces?","o":["Aviso al capataz o al prevencionista para reponerla","La dejo apoyada en el tablero","La guardo en la bodega para que no se pierda","Sigo trabajando, ya sé que hay riesgo"],"w":"Una señal caída no avisa a quien llega después."},{"q":"Una señal tapada por materiales es tan peligrosa como no tener señal, porque no avisa el peligro.","vf":true,"w":"Verdadero. Si no se ve, no cumple su función."}]},{"s":"senaletica_prohib","v":[{"q":"Un círculo rojo con una barra cruzada significa:","o":["Prohibición: eso no se hace","Advertencia: peligro cercano","Obligación: uso de EPP","Emergencia: equipo contra incendio"],"w":"Rojo con barra = prohibido."},{"q":"Junto a un acopio de OSB y aislapol hay un círculo rojo con un cigarro tachado. ¿Por qué?","o":["Porque esos materiales arden con facilidad","Porque el humo mancha las planchas nuevas","Porque solo se fuma en la colación","Porque es una recomendación de salud"],"w":"La prohibición de fumar protege contra incendios en acopios combustibles."},{"q":"Ves un círculo rojo con barra en la entrada de la zona de excavación. ¿Qué indica?","o":["Que no puedes entrar sin autorización","Que puedes entrar si vas con casco","Que hay que entrar con cuidado","Que ahí está la zona de seguridad"],"w":"La prohibición se cumple: no se entra sin autorización."}]},{"s":"senaletica_sga","v":[{"q":"En el envase de un desmoldante ves un rombo de borde rojo con una llama. ¿Qué indica?","o":["Que el producto es inflamable","Que el producto es corrosivo","Que el producto es tóxico al tragarlo","Que daña el medio ambiente"],"w":"La llama dentro del rombo indica producto inflamable."},{"q":"Antes de usar un producto químico nuevo, como un aditivo, debes:","o":["Leer la etiqueta y la hoja de datos de seguridad","Olerlo para saber si es fuerte","Preguntarle a un compañero cómo lo usa","Usarlo igual que el producto anterior"],"w":"La etiqueta y la hoja de datos dicen sus peligros y qué EPP usar."},{"q":"Un compañero traspasa diluyente a una botella de bebida sin etiqueta. ¿Qué está mal?","o":["Sin etiqueta, alguien podría confundirlo y tomarlo","Nada, si la botella está limpia y cerrada","Solo que la botella es muy pequeña","Que debería usar una botella de vidrio"],"w":"Un producto sin etiqueta pierde su advertencia y puede causar una intoxicación."}]}]},{"id":"uv","sec":"todos","title":"Radiación UV de origen solar en obra","thumb":"uv_ropa","learn":[{"s":"uv_intro","t":"El sol también es un riesgo laboral","x":"En obra se trabaja <b>al aire libre</b> gran parte del día: en losas, techumbres, enfierraduras y excavaciones. La radiación ultravioleta (UV) del sol daña la piel y los ojos <b>aunque no sientas calor</b>, incluso en primavera y otoño. Por eso la exposición a radiación UV de origen solar es un <b>riesgo laboral</b> que la empresa debe informar y controlar."},{"s":"uv_efectos","t":"Efectos en la salud","x":"A corto plazo: <b>quemaduras</b> de piel y ojos irritados. A largo plazo: manchas, envejecimiento de la piel, <b>cataratas</b> y <b>cáncer de piel</b>. El daño <b>se acumula</b> con los años, aunque las quemaduras se pasen. Revisa tu piel y consulta si un lunar cambia de forma, color o tamaño, o si aparece una herida que no cicatriza."},{"s":"uv_escala","t":"El índice UV","x":"El índice UV mide la intensidad de la radiación: <b>1 a 2 bajo, 3 a 5 moderado, 6 a 7 alto, 8 a 10 muy alto, 11 o más extremo</b>. Desde <b>3, moderado</b>, hay que protegerse. En primavera y verano, en el centro sur del país suele llegar a muy alto o extremo cerca del mediodía. Lo informan la Dirección Meteorológica y las aplicaciones del clima."},{"s":"uv_horario","t":"Las horas de mayor radiación","x":"La radiación es más intensa entre las <b>10:00 y las 17:00</b>, y llega a su máximo cerca del <b>mediodía</b>. Cuando se pueda, en ese horario conviene programar tareas a la sombra o bajo techo, y dejar las faenas a pleno sol para temprano o para el final de la tarde. Regla práctica: si tu sombra es más corta que tú, el sol está fuerte."},{"s":"uv_ropa","t":"Cómo protegerte","x":"<ul><li><b>Bloqueador FPS 30 o más</b> en cara, orejas, cuello y manos, 30 minutos antes de salir al sol y <b>reaplicado cada 2 a 3 horas</b>, o antes si sudas mucho.</li><li><b>Legionario</b> bajo el casco, cubriendo nuca y orejas.</li><li><b>Manga larga</b> y pantalón largo.</li><li><b>Lentes con filtro UV</b>.</li></ul>","k":"Bloqueador, legionario, manga larga y lentes UV, todos los días."},{"s":"uv_sombra","t":"Sombra, agua y pausas","x":"Haz pausas a la <b>sombra</b> en el lugar habilitado y toma <b>agua seguido, aunque no tengas sed</b>: con calor, un vaso cada 15 a 20 minutos. Evita las bebidas azucaradas, las energéticas y el alcohol, que deshidratan. Lleva tu botella de agua y mantenla a la sombra."},{"s":"ind_calor","t":"Golpe de calor","x":"El calor puede causar <b>golpe de calor</b>, una emergencia grave. Señales: dolor de cabeza, mareo, náuseas, calambres, piel muy caliente, confusión o desmayo. Si las tienes tú o un compañero: <b>detén el trabajo</b>, ve a la sombra, afloja la ropa, refréscate y toma agua si estás consciente. Si hay confusión o desmayo, llama al <b>131</b> y avisa a la jefatura.","k":"Mareo o confusión con calor: a la sombra y pide ayuda de inmediato."},{"s":"uv_nublado","t":"Nublado no es sin UV","x":"La mayor parte de la radiación UV <b>atraviesa las nubes</b>, por eso puedes quemarte en un día nublado o fresco sin darte cuenta. Además, la arena, el agua, las superficies claras y las planchas metálicas <b>reflejan</b> la radiación y aumentan la exposición. Protégete todos los días, con sol o con nubes."},{"s":"uv_ley","t":"La empresa protege, tú usas la protección","x":"Según la Ley 20.096 y el DS 594, la empresa debe <b>informar</b> el riesgo y el índice UV, <b>entregar gratis</b> los elementos de protección (bloqueador, legionario, lentes, ropa) y organizar sombra y pausas. Tú debes <b>usarlos</b> y avisar cuando se acaben o se dañen."}],"quiz":[{"s":"uv_horario","v":[{"q":"¿En qué horario la radiación UV es más intensa?","o":["Entre las 10:00 y las 17:00","Entre las 07:00 y las 10:00","Entre las 17:00 y las 20:00","Es igual durante todo el día"],"w":"La radiación es mayor de 10 a 17 horas, con su máximo al mediodía."},{"q":"La cuadrilla puede elegir cuándo hacer un trabajo largo a pleno sol en la losa. ¿Cuál es el mejor horario?","o":["Temprano, antes de las 10:00","Cerca del mediodía, para terminar antes","Después de colación, de 13:00 a 15:00","Da lo mismo si se usa bloqueador"],"w":"Antes de las 10:00 la radiación es menor."},{"q":"¿Cuándo llega la radiación UV a su punto máximo?","o":["Cerca del mediodía","Al amanecer","Al atardecer","A las 16:00, cuando hace más calor"],"w":"La radiación UV no depende del calor: su máximo es al mediodía."}]},{"s":"uv_mal","v":[{"q":"Un compañero trabaja al sol con polera manga corta, sin legionario y sin lentes. ¿Qué le falta?","o":["Manga larga, legionario, lentes UV y bloqueador","Solo bloqueador: el casco ya cubre la cabeza","Solo lentes: la piel se recupera sola","Solo agua: así no se quema"],"w":"La protección es completa: piel, cuello, orejas y ojos."},{"q":"¿Cuál de estas combinaciones protege mejor del sol en obra?","o":["FPS 30, legionario, manga larga y lentes UV","Casco, manga corta y bloqueador FPS 15","Gorro de lana bajo el casco y lentes comunes","FPS 50 aplicado solo al inicio del turno"],"w":"Se combina bloqueador reaplicado, legionario, manga larga y lentes con filtro UV."},{"q":"Un compañero se sacó la camisa por el calor mientras amarra fierro a pleno sol. ¿Qué le recomiendas?","o":["Ponérsela de nuevo y usar legionario y bloqueador","Seguir así, pero tomar agua cada hora","Mojarse la espalda para no quemarse","Ponerse bloqueador solo en la cara"],"w":"La ropa que cubre es una de las mejores barreras contra la radiación."}]},{"s":"uv_nublado","v":[{"q":"En un día nublado no es necesario usar bloqueador porque las nubes detienen la radiación UV.","vf":false,"w":"Falso. La mayor parte de la radiación atraviesa las nubes."},{"q":"Hoy está nublado y fresco. ¿Qué haces con la protección solar?","o":["La uso igual: la radiación pasa las nubes","No la uso: sin sol directo no hay radiación","Uso solo legionario, porque no hace calor","La uso solo si sale el sol después"],"w":"Nublado también quema."},{"q":"¿Por qué te puedes quemar en un día nublado?","o":["Porque gran parte de la radiación UV atraviesa las nubes","Porque el frío reseca y debilita la piel","Porque las nubes aumentan el calor del día","Porque el viento arrastra la radiación al suelo"],"w":"Las nubes detienen poco la radiación UV."}]},{"s":"uv_bloq","v":[{"q":"¿Cada cuánto se reaplica el bloqueador?","o":["Cada 2 a 3 horas, o antes si sudas mucho","Una vez al inicio del turno es suficiente","Solo una vez más, después de la colación","Cada 6 horas si el bloqueador es FPS 50"],"w":"El sudor y el tiempo le quitan efecto."},{"q":"Te pusiste bloqueador a las 8:00 y trabajas sudando al sol. ¿Cuándo vuelves a ponerte?","o":["Alrededor de las 10:00 u 11:00","Después de colación, a las 14:00","Al final del turno","No hace falta si es resistente al agua"],"w":"Se reaplica cada 2 a 3 horas, antes si sudas."},{"q":"¿Cuándo conviene aplicarse el bloqueador al empezar el turno?","o":["Unos 30 minutos antes de salir al sol","Cuando ya sientes la piel caliente","Solo si el cielo está despejado","Después de la primera pausa"],"w":"Así alcanza a hacer efecto antes de la exposición."}]},{"s":"uv_escala","v":[{"q":"¿Desde qué índice UV hay que protegerse?","o":["Desde 3, nivel moderado","Desde 6, nivel alto","Desde 8, nivel muy alto","Desde 11, nivel extremo"],"w":"Desde 3 la radiación ya daña la piel y los ojos."},{"q":"El pronóstico dice índice UV 4. ¿Qué haces?","o":["Me protejo: desde 3 es necesario","No me protejo: es un nivel bajo","Me protejo solo si hace calor","Uso solo lentes, la piel aguanta"],"w":"Un índice 4 es moderado y exige protección."},{"q":"Con índice UV 5 no es necesario protegerse, porque el riesgo empieza recién en 8.","vf":false,"w":"Falso. La protección es necesaria desde índice 3."}]},{"s":"uv_efectos","v":[{"q":"¿Qué enfermedad grave puede causar el sol después de años sin protección?","o":["Cáncer de piel","Silicosis","Dermatitis por cemento","Lumbago"],"w":"La radiación UV acumulada puede causar cáncer de piel."},{"q":"¿Qué daño puede causar el sol en los ojos tras años sin lentes con filtro UV?","o":["Cataratas","Daltonismo","Miopía","Conjuntivitis contagiosa"],"w":"La radiación UV acumulada daña el cristalino y causa cataratas."},{"q":"El daño del sol en la piel se acumula con los años, aunque las quemaduras se pasen.","vf":true,"w":"Verdadero. Por eso hay que protegerse siempre."}]},{"s":"ind_calor","v":[{"q":"Un compañero que trabaja al sol está confundido, con mareo y la piel muy caliente. ¿Qué haces?","o":["Lo llevo a la sombra, lo refresco y llamo al 131","Le digo que se siente un rato y luego siga","Le doy una bebida energética para que reaccione","Le echo agua y lo dejo solo descansando"],"w":"La confusión con calor puede ser golpe de calor: es una emergencia."},{"q":"¿Cuál de estas es una señal de golpe de calor?","o":["Mareo, náuseas y confusión","Hambre antes de la colación","Piel fría y ganas de abrigarse","Sueño después de almorzar"],"w":"Mareo, náuseas, calambres, piel caliente y confusión son señales de alerta."},{"q":"Si un compañero se desmaya por el calor, hay que llevarlo a la sombra, llamar al 131 y avisar a la jefatura.","vf":true,"w":"Verdadero. El desmayo por calor es una emergencia."}]},{"s":"uv_sombra","v":[{"q":"Para prevenir la deshidratación y el golpe de calor, lo correcto es:","o":["Tomar agua seguido aunque no tengas sed","Tomar harta agua solo en la colación","Tomar agua solo cuando tengas sed","Tomar energéticas durante el turno"],"w":"La sed aparece cuando ya estás deshidratándote."},{"q":"Hace 30 grados y estás moldajeando en la losa. ¿Cada cuánto deberías tomar agua?","o":["Un vaso cada 15 a 20 minutos","Una botella al final del turno","Solo cuando tengas la boca seca","Cada 2 horas, en las pausas"],"w":"Con calor se toma agua poco y seguido."},{"q":"¿Qué bebidas conviene evitar en un día de mucho calor en obra?","o":["Las azucaradas, energéticas y alcohol","El agua fría","El agua a temperatura ambiente","Las infusiones sin azúcar"],"w":"Esas bebidas deshidratan más."}]}]},{"id":"enfermedades","sec":"todos","title":"Efectos en la salud y enfermedades profesionales en obra","thumb":"bodyMap","learn":[{"s":"enfermedades_vs","t":"Accidente y enfermedad profesional","x":"El <b>accidente</b> ocurre de golpe: un corte, una caída. La <b>enfermedad profesional</b> aparece de a poco, por exponerte meses o años a un agente del trabajo: polvo de sílice, ruido, posturas forzadas, cemento, solventes o sol. La Ley 16.744 la cubre igual que a un accidente. Que no duela hoy no significa que no te esté dañando."},{"s":"pz_polvo_corte","t":"Polvo de sílice: silicosis","x":"Cortar, picar, perforar o pulir <b>hormigón, ladrillo, cerámica, mortero o piedra</b> en seco libera <b>polvo de sílice</b> muy fino, que no se ve y queda en el aire. Respirarlo por años causa <b>silicosis</b>: los pulmones se endurecen y falta el aire. <b>No tiene cura</b> y puede seguir avanzando aunque dejes de exponerte. El protocolo PLANESI del MINSAL vigila este riesgo.","k":"La silicosis no tiene cura: corta siempre con agua o aspiración y respirador."},{"s":"pz_polvo_agua","t":"Cómo se controla el polvo","x":"<ul><li>Corta con <b>agua</b> o con <b>aspiración</b> conectada a la herramienta.</li><li>Usa el <b>respirador con filtros para partículas</b> que entrega {EMP}, bien ajustado y con la cara afeitada para que selle.</li><li>Limpia con aspiradora o barriendo húmedo, <b>nunca soplando</b> con aire comprimido.</li><li>Ponte a favor del viento y aleja a los demás del corte.</li></ul>"},{"s":"enfermedades_ruido","t":"Ruido: sordera permanente","x":"Sierras circulares, esmeriles, martillos demoledores, vibradores de hormigón y compresores superan fácilmente los <b>85 decibeles</b>, el límite para 8 horas según el DS 594. Por cada 3 decibeles más, el tiempo permitido se reduce a la mitad. La pérdida auditiva por ruido es <b>permanente</b>: no la corrigen gotas ni operaciones. Usa fonos o tapones <b>todo el tiempo</b> que estés en el ruido.","k":"Lo que se pierde por ruido no vuelve: protección auditiva todo el tiempo."},{"s":"cc6_en_lumbago","t":"Espalda, hombros y rodillas","x":"Cargar sacos de cemento de 25 kilos, trabajar agachado o de rodillas y con los brazos sobre los hombros daña <b>espalda, hombros, codos, muñecas y rodillas</b>. Le pasa a enfierradores, albañiles, ceramistas, carpinteros y yeseros. La Ley 20.949 fija un máximo de <b>25 kilos</b> para hombres y 20 para mujeres y menores de 18. Usa carro, pide ayuda, flecta las rodillas y alterna tareas."},{"s":"cc6_en_cemento","t":"Cemento y piel","x":"El cemento y el mortero húmedos son <b>alcalinos</b>: irritan, causan <b>dermatitis</b> y pueden provocar quemaduras químicas si quedan contra la piel, por ejemplo dentro de la bota o bajo un guante mojado. Usa <b>guantes</b> resistentes, manga larga y botas de goma al hormigonar. Si te salpica, lávate de inmediato con abundante agua. Si llega a los ojos, lava 15 minutos y consulta."},{"s":"enfermedades_senales","t":"Señales de alerta","x":"Avisa si tienes: <b>tos</b> o flema que no se va, <b>falta de aire</b> al subir escaleras, <b>zumbido</b> en los oídos o te cuesta entender conversaciones, <b>dolor</b> que no se pasa con el descanso, hormigueo en las manos, o <b>ronchas y picazón</b> en la piel. Pueden ser el inicio de una enfermedad profesional, y detectarla temprano cambia el resultado."},{"s":"enfermedades_vigilancia","t":"Vigilancia de la salud","x":"Si estás expuesto a sílice o ruido, la <b>ACHS</b> te cita a <b>exámenes periódicos</b>: radiografía de tórax por el protocolo PLANESI o audiometría por el protocolo PREXOR. Son <b>gratuitos</b> para ti. Asiste siempre y no mandes a otro en tu lugar: si se detecta un daño a tiempo, se te protege, por ejemplo cambiándote a un puesto sin exposición."},{"s":"enfermedades_diep","t":"La DIEP y la atención","x":"Si crees que tienes una enfermedad por el trabajo, avisa a tu jefatura: se hace la <b>Denuncia Individual de Enfermedad Profesional, DIEP</b>, y la ACHS te evalúa. Si la empresa no la hace, puedes ir directamente a la ACHS. Por la Ley 16.744, la atención, los exámenes y los medicamentos son <b>gratuitos</b>, y si quedas con reposo recibes subsidio."}],"quiz":[{"s":"pz_polvo_agua","v":[{"q":"Debes cortar bloques de hormigón con esmeril angular. ¿Cuál es la forma correcta?","o":["Con agua o aspiración y respirador para partículas","En seco, pero a favor del viento y rápido","En seco, con una mascarilla de tela","En seco y después soplar el polvo con aire"],"w":"El agua o la aspiración atrapan el polvo; el respirador protege lo que queda."},{"q":"¿Cómo se limpia el polvo de corte de hormigón acumulado en la losa?","o":["Con aspiradora o barriendo húmedo","Soplándolo con aire comprimido","Barriendo en seco con escobillón","Dejando que el viento lo despeje"],"w":"Soplar o barrer en seco levanta de nuevo la sílice."},{"q":"Un compañero usa respirador, pero tiene barba de varios días. ¿Qué problema hay?","o":["El respirador no sella y entra polvo","Ninguno, si el filtro es nuevo","Solo que le da más calor","Que debe cambiar el filtro más seguido"],"w":"Sin sello contra la piel, el aire entra por los bordes sin filtrar."}]},{"s":"pz_polvo_corte","v":[{"q":"Cortar ladrillo o hormigón en seco libera polvo que con los años puede causar:","o":["Silicosis","Asma por polen","Dermatitis","Hipoacusia"],"w":"El polvo de sílice causa silicosis."},{"q":"¿Qué pasa con la silicosis si el trabajador deja de exponerse al polvo?","o":["Puede seguir avanzando: no tiene cura","Se cura sola en algunos meses","Desaparece con antibióticos","Se detiene y el pulmón se recupera"],"w":"Por eso la única forma de enfrentarla es prevenirla."},{"q":"La silicosis tiene cura si se detecta a tiempo.","vf":false,"w":"Falso. No tiene cura: se previene."}]},{"s":"enfermedades_ruido","v":[{"q":"La pérdida de audición causada por ruido:","o":["Es permanente: no se recupera","Se recupera tras semanas sin ruido","Se cura con gotas o lavado de oídos","Se corrige con una operación simple"],"w":"El daño al oído interno no se repara."},{"q":"Un compañero dice que se acostumbró al ruido del vibrador y ya no usa tapones. ¿Qué pasa?","o":["Puede estar perdiendo audición sin notarlo","Su oído se adaptó y ya no se daña","Solo se daña si siente dolor","El daño se recupera el fin de semana"],"w":"Acostumbrarse al ruido suele ser señal de que ya hay pérdida auditiva."},{"q":"La sordera producida por ruido en el trabajo es permanente.","vf":true,"w":"Verdadero. Lo que se pierde por ruido no vuelve."}]},{"s":"cc6_en_cemento","v":[{"q":"El cemento húmedo en contacto con la piel puede causar:","o":["Dermatitis y quemaduras químicas","Solo manchas que salen con agua","Solo sequedad leve","Ningún daño si es poco rato"],"w":"Es alcalino y daña la piel."},{"q":"Mientras hormigonas, entra mezcla a tu bota. ¿Qué haces?","o":["Me detengo, me lavo con agua y cambio calcetín","Sigo hasta terminar y me lavo en la casa","Me limpio con un trapo seco y sigo trabajando","Espero que se seque para sacarla más fácil"],"w":"El cemento atrapado contra la piel puede causar quemaduras químicas."},{"q":"¿Por qué el cemento húmedo daña la piel?","o":["Porque es alcalino","Porque es ácido","Porque tiene bacterias","Porque está caliente"],"w":"Su alcalinidad irrita y quema la piel."}]},{"s":"enfermedades_vigilancia","v":[{"q":"La ACHS te cita a una audiometría. ¿Qué haces?","o":["Asisto: detectar a tiempo protege mi salud","No voy si escucho bien","Mando a un compañero en mi lugar","Lo dejo para cuando tenga molestias"],"w":"La pérdida auditiva avanza sin síntomas al principio."},{"q":"¿Para qué sirve la radiografía de tórax periódica a quienes cortan hormigón?","o":["Para detectar a tiempo daño por sílice","Para saber si puede seguir fumando","Para revisar si hay huesos rotos","Para ver si está apto para altura"],"w":"Es parte de la vigilancia del protocolo PLANESI."},{"q":"Los exámenes de vigilancia de la salud por sílice o ruido los paga el trabajador.","vf":false,"w":"Falso. Son gratuitos para el trabajador."}]},{"s":"enfermedades_vs","v":[{"q":"Una enfermedad profesional aparece:","o":["De a poco, por exposición prolongada","De golpe, en un solo evento","Solo en trabajos de oficina","Solo después de jubilar"],"w":"A diferencia del accidente, se desarrolla con el tiempo."},{"q":"¿Cuál de estos casos es una enfermedad profesional?","o":["Sordera de un carpintero tras años de sierra","Un corte en la mano con un fierro","Una caída desde una escala","Un golpe con una carga suspendida"],"w":"Los otros son accidentes: ocurren de golpe."},{"q":"Un albañil con años cortando ladrillo en seco empieza con falta de aire. Eso podría ser:","o":["Una enfermedad profesional","Un accidente del trabajo","Un accidente de trayecto","Un resfrío común sin importancia"],"w":"La exposición prolongada a sílice puede causar silicosis."}]},{"s":"enfermedades_senales","v":[{"q":"Tienes tos que no se va desde hace meses y cortas ladrillo. ¿Qué haces?","o":["Aviso y consulto en la ACHS","Espero a que se pase sola","Tomo jarabe y sigo sin decir nada","Fumo menos y sigo igual"],"w":"Puede ser una señal temprana de daño por sílice."},{"q":"¿Cuál de estas puede ser una señal temprana de daño auditivo?","o":["Zumbido en los oídos después del turno","Dolor de cabeza al despertar","Ojos rojos al final del día","Picazón en las manos"],"w":"El zumbido indica que el oído está siendo dañado."},{"q":"Tienes ronchas y picazón en las manos desde que trabajas con mortero. ¿Qué haces?","o":["Aviso y consulto en la ACHS","Uso crema y sigo sin decir nada","Espero a que se pase solo","Cambio de guantes y lo olvido"],"w":"Puede ser una dermatitis laboral: se evalúa y se trata."}]},{"s":"enfermedades_diep","v":[{"q":"Crees que tu dolor de hombro es por el trabajo. ¿Qué corresponde?","o":["Avisar para que se haga la DIEP y la ACHS evalúe","Ir a un médico particular y pagar la consulta","Aguantar hasta ver si se vuelve más grave","Pedir vacaciones para descansar el hombro"],"w":"La DIEP activa la evaluación y la cobertura de la Ley 16.744."},{"q":"La atención de una enfermedad profesional, para el trabajador, es:","o":["Gratuita, por la Ley 16.744","Con copago según su sueldo","Pagada por Fonasa o la isapre","Gratuita solo el primer mes"],"w":"La ley cubre atención, exámenes, medicamentos y subsidio."},{"q":"Si la empresa no hace la DIEP, puedes ir directamente a la ACHS para que te evalúe.","vf":true,"w":"Verdadero. No necesitas esperar a la empresa."}]}]},{"id":"psicosocial","sec":"todos","title":"Riesgos psicosociales y bienestar en el trabajo","thumb":"support","learn":[{"s":"psico_intro","t":"¿Qué son los riesgos psicosociales?","x":"Son condiciones de cómo se <b>organiza</b> el trabajo que pueden dañar tu salud mental y física: presión por plazos, exceso de tareas, jornadas largas, órdenes poco claras, malos tratos, poco apoyo o inseguridad laboral. No son un problema personal ni de aguante: son un <b>riesgo laboral</b> más, como el ruido o la altura, y el DS 44 obliga a la empresa a evaluarlos y controlarlos."},{"s":"psico_estres","t":"El estrés y la obra","x":"Un poco de presión es normal, pero el <b>estrés sostenido</b> provoca cansancio, mal dormir, irritabilidad, dolor de cabeza o espalda y falta de concentración. En obra eso significa <b>más errores</b>: olvidar anclar el arnés, acercar la mano a la sierra, no ver una carga. El estrés no se combate con alcohol, energéticas ni trabajando más horas.","k":"Estrés y cansancio aumentan los accidentes: no lo calles."},{"s":"psico_factores","t":"Factores en obra","x":"Ejemplos frecuentes:<ul><li>Plazos de entrega apretados y trabajo a trato.</li><li>Jornadas extendidas y viajes largos a la obra.</li><li>Órdenes contradictorias de distintos jefes.</li><li>Conflictos entre cuadrillas o subcontratos.</li><li>Poco reconocimiento o incertidumbre por el término de la obra.</li></ul>Si se identifican, <b>se pueden mejorar</b>."},{"s":"psico_ceal","t":"El cuestionario CEAL-SM","x":"La empresa evalúa estos riesgos con el cuestionario oficial <b>CEAL-SM de la SUSESO</b>, según el Protocolo de Vigilancia de Riesgos Psicosociales del MINSAL. Es <b>anónimo, voluntario y confidencial</b>: evalúa el trabajo, no a las personas, y nadie sabe qué respondió cada uno. Con los resultados se definen medidas concretas. Respóndelo con sinceridad."},{"s":"psico_respeto","t":"Trato respetuoso","x":"El trato entre compañeros, capataces, jefes de obra y subcontratos debe ser <b>respetuoso</b>. Un error se corrige con claridad y sin humillar: mejor decir revisemos juntos que gritar frente a la cuadrilla. Gritos, insultos, apodos ofensivos y burlas <b>no son parte de la pega</b>, y pueden ser acoso según la Ley Karin."},{"s":"psico_auto","t":"Si no estás bien, dilo","x":"Si un día no estás en condiciones, porque no dormiste, un problema familiar te tiene mal o estás muy angustiado, <b>avísale a tu capataz</b> antes de operar una sierra, subir a altura o manejar. Pedir otra tarea ese día es <b>responsable</b>, no una debilidad. Ninguna tarea vale un accidente."},{"s":"psico_senales","t":"Señales en ti y en otros","x":"Pon atención a: cambios de ánimo, irritabilidad, aislarse del grupo, cansancio permanente, no dormir, faltar o llegar tarde más seguido, o tomar alcohol para aguantar. Si lo ves en un compañero, <b>acércate en privado, pregúntale cómo está y escucha</b> sin juzgar. Si te cuenta algo grave, ayúdalo a buscar apoyo.","k":"Preguntar a un compañero cómo está puede ayudar mucho."},{"s":"psico_ayuda","t":"Dónde pedir ayuda","x":"Puedes hablar con tu <b>jefatura</b>, el <b>Comité Paritario</b> o el <b>delegado de seguridad y salud</b>, o con el <b>asesor en prevención</b>. La <b>ACHS</b> atiende gratis los problemas de salud mental causados por el trabajo, por la Ley 16.744. Si alguien está en riesgo de hacerse daño, no lo dejes solo y llama al 131 o a la línea de prevención del suicidio, asterisco 4141."},{"s":"psico_apoyo","t":"Cuidarnos entre todos","x":"Respeta las <b>pausas</b> y la hora de colación, descansa lo necesario entre jornadas, ayuda a quien está sobrecargado y resuelve los conflictos conversando, no a gritos. Si un plazo no se puede cumplir con seguridad, dilo a tiempo a tu jefatura. Un buen ambiente <b>también previene accidentes</b>."}],"quiz":[{"s":"psico_estres","v":[{"q":"El estrés sostenido en la obra puede:","o":["Aumentar los errores y los accidentes","Mejorar la concentración en tareas peligrosas","Afectar solo la vida familiar","Bajar con energéticas y horas extra"],"w":"El cansancio y la distracción aumentan el riesgo."},{"q":"Un enfierrador lleva semanas durmiendo mal por los plazos y hoy olvidó anclar su arnés. ¿Qué muestra esto?","o":["Que el estrés y el cansancio aumentan los errores","Que es descuidado, sin relación con el estrés","Que debe trabajar más rápido para descansar","Que el arnés es incómodo y hay que cambiarlo"],"w":"El estrés sostenido lleva a olvidos que en obra pueden ser graves."},{"q":"¿Cuál es una forma equivocada de enfrentar el estrés?","o":["Tomar alcohol para aguantar","Conversarlo con la jefatura","Respetar las pausas y el descanso","Pedir apoyo a la ACHS"],"w":"El alcohol empeora el problema y aumenta el riesgo de accidente."}]},{"s":"psico_ceal","v":[{"q":"El cuestionario CEAL-SM es:","o":["Anónimo, voluntario y confidencial","Con nombre y RUT para seguimiento","Una prueba con nota para cada uno","Obligatorio y revisado por el capataz"],"w":"Es anónimo para que se responda con sinceridad."},{"q":"Un compañero no quiere responder el CEAL-SM porque teme que su jefe vea sus respuestas. ¿Qué le dices?","o":["Que es anónimo: nadie sabe qué respondió cada uno","Que responda todo bien para no tener problemas","Que lo responda su capataz por él","Que es mejor no contestar"],"w":"El cuestionario no identifica a las personas."},{"q":"El cuestionario CEAL-SM evalúa cómo está organizado el trabajo, no a las personas.","vf":true,"w":"Verdadero. Sus resultados sirven para mejorar las condiciones de trabajo."}]},{"s":"psico_grito","v":[{"q":"Los gritos e insultos del capataz son parte normal del trabajo en obra.","vf":false,"w":"Falso. El trato debe ser respetuoso y los malos tratos pueden ser acoso."},{"q":"Un capataz quiere corregir un error de un trabajador. ¿Cuál es la forma correcta?","o":["Explicarle con claridad y sin humillar","Gritarle frente a la cuadrilla para que aprendan","Ponerle un apodo para que no se le olvide","Reclamarle por el grupo de WhatsApp"],"w":"Corregir no requiere humillar."},{"q":"Un jefe insulta a un trabajador frente a la cuadrilla. ¿Qué puede ser eso?","o":["Acoso laboral según la Ley Karin","Parte normal del trabajo en obra","Una falta solo si se repite mucho","Una falta solo si hay testigos externos"],"w":"Los malos tratos pueden ser acoso, aunque ocurran una vez."}]},{"s":"psico_senales","v":[{"q":"Ves a un compañero aislado, irritable y muy cansado hace semanas. ¿Qué haces?","o":["Me acerco en privado, le pregunto y escucho","Lo comento en el grupo para averiguar","Lo dejo tranquilo, son temas personales","Le digo que se anime y no sea flojo"],"w":"Preguntar en privado y escuchar sin juzgar ayuda."},{"q":"¿Cuál puede ser una señal de que alguien está sobrepasado?","o":["Aislarse y tomar alcohol para aguantar","Pedir ayuda para levantar una carga","Hacer preguntas sobre su tarea","Tomar su hora de colación completa"],"w":"El aislamiento y el alcohol para aguantar son señales de alerta."},{"q":"Un compañero te cuenta en privado que ya no da más con la presión. ¿Qué haces?","o":["Lo escucho y lo ayudo a buscar apoyo","Le digo que todos estamos igual","Lo cuento en la cuadrilla para apoyarlo","Le recomiendo unos tragos para relajarse"],"w":"Escuchar sin juzgar y orientar hacia ayuda es lo que más sirve."}]},{"s":"psico_ayuda","v":[{"q":"¿Dónde puedes pedir ayuda por un problema de salud mental causado por el trabajo?","o":["Jefatura, Comité Paritario, prevención o la ACHS","Solo con un psicólogo particular pagado por ti","Solo en el consultorio, porque no es laboral","Solo con Recursos Humanos y por escrito"],"w":"Hay varias vías de apoyo dentro y fuera de la obra."},{"q":"La atención de la ACHS por un problema de salud mental causado por el trabajo:","o":["Es gratuita, por la Ley 16.744","Tiene copago según el sueldo","Solo cubre contratos indefinidos","Solo cubre accidentes, no salud mental"],"w":"La Ley 16.744 cubre también enfermedades de salud mental de origen laboral."},{"q":"Los problemas de salud mental nunca son de origen laboral, por eso la ACHS no los atiende.","vf":false,"w":"Falso. La ACHS atiende la salud mental de origen laboral."}]},{"s":"psico_apoyo","v":[{"q":"Hay que terminar una losa y alguien propone saltarse la colación. ¿Qué es lo más seguro?","o":["Respetar la pausa: el cansancio aumenta errores","Saltarla y tomar energéticas para rendir","Trabajar sin parar y descansar el domingo","Comer mientras se sigue trabajando"],"w":"El descanso es una medida de seguridad."},{"q":"Notas que un compañero está sobrecargado con su tarea. ¿Qué ayuda más?","o":["Ofrecerle ayuda o avisar para repartir la carga","Dejarlo, cada uno responde por lo suyo","Apurarlo para que no atrase a la cuadrilla","Contarle al capataz que es lento"],"w":"Apoyarse en el equipo baja la presión y el riesgo."},{"q":"Respetar la colación y los descansos ayuda a prevenir accidentes.","vf":true,"w":"Verdadero. El cansancio aumenta los errores."}]},{"s":"psico_intro","v":[{"q":"Los riesgos psicosociales tienen que ver con:","o":["Cómo se organiza el trabajo","Solo con la vida personal","Solo con el clima y el calor","Solo con la personalidad de cada uno"],"w":"Plazos, carga, trato, claridad y jornada son factores psicosociales."},{"q":"¿Cuál de estos es un riesgo psicosocial en obra?","o":["Plazos imposibles y órdenes contradictorias","Una escala con un peldaño roto","Polvo de sílice al cortar hormigón","Un cable eléctrico pelado"],"w":"Los demás son riesgos físicos, químicos o eléctricos."},{"q":"¿Qué norma obliga a la empresa a evaluar y controlar los riesgos psicosociales?","o":["El DS 44","El DS 57","La Ley 20.949","La Ley 18.290"],"w":"El DS 44 regula la gestión preventiva de todos los riesgos laborales."}]},{"s":"psico_auto","v":[{"q":"Hoy no dormiste por un problema familiar y te toca usar la sierra circular. ¿Qué haces?","o":["Aviso al capataz y pido otra tarea por hoy","Uso la sierra igual, pero más lento","Tomo una energética y sigo normal","No digo nada para no parecer débil"],"w":"Avisar a tiempo previene un accidente."},{"q":"Pedir un cambio de tarea un día en que no estás en condiciones es:","o":["Responsable, porque previene accidentes","Una falta que se sanciona","Una muestra de flojera","Algo que solo pueden pedir los jefes"],"w":"Reconocer que no estás bien es parte del autocuidado."},{"q":"Un compañero que va a subir a la losa te dice que está muy angustiado y no se concentra. ¿Qué haces?","o":["Le sugiero avisar al capataz y lo acompaño","Le digo que suba igual, que se le pasará","Le presto mi arnés para que suba seguro","Le digo que tome un café y siga"],"w":"Sin concentración, el trabajo en altura es muy riesgoso."}]}]},{"id":"karin","sec":"todos","title":"Ley Karin: trabajo libre de acoso y violencia","thumb":"karin3","learn":[{"s":"karin_intro","t":"Ley 21.643, Ley Karin","x":"Desde el <b>1 de agosto de 2024</b>, la Ley Karin modificó el Código del Trabajo para <b>prevenir, investigar y sancionar</b> el acoso laboral, el acoso sexual y la violencia en el trabajo. Protege a todas las personas que trabajan en la obra, sin importar su cargo, contrato o nacionalidad."},{"s":"karin_protocolo","t":"Protocolo y Reglamento Interno","x":"{EMP} debe tener un <b>protocolo de prevención</b> del acoso y la violencia, y un <b>procedimiento de investigación</b> en su Reglamento Interno. Ahí se indica cómo y ante quién denunciar, los plazos y las medidas de protección. Te lo deben informar y debe estar disponible para todos. Si no lo conoces, pídelo."},{"s":"karin_laboral","t":"Acoso laboral","x":"Es toda agresión, humillación o maltrato que te menoscaba o perjudica, <b>aunque ocurra una sola vez</b>. Puede venir de un jefe, de un compañero o de un subordinado. Ejemplos: insultar o ridiculizar a alguien frente a la cuadrilla, amenazarlo con el despido, aislarlo o darle siempre las peores tareas para castigarlo.","k":"Basta una vez para que sea acoso."},{"s":"karin_sexual","t":"Acoso sexual","x":"Son requerimientos de carácter sexual <b>no consentidos</b>, por cualquier medio: comentarios o piropos sobre el cuerpo, gestos, mensajes, fotos o videos por WhatsApp, insistir con invitaciones, tocaciones. No importa que quien lo hace diga que era broma: lo que cuenta es que la otra persona <b>no lo consintió</b>. Reenviar una foto íntima también es una falta grave."},{"s":"karin_terceros","t":"Violencia de terceros","x":"También están cubiertas las agresiones de personas <b>externas</b> a la empresa: proveedores, transportistas, vecinos de la obra o clientes que la visitan. Si alguien externo te insulta o amenaza, no respondas con violencia: aléjate, avisa a tu jefatura y, si hay amenaza a tu integridad, llama al <b>133</b>."},{"s":"karin_burla","t":"Las bromas también","x":"Burlas por el origen, la nacionalidad, el color de piel, el físico, la forma de hablar, el género o la orientación sexual pueden ser acoso o discriminación. En obras con compañeros de distintos países y mujeres en cuadrillas y oficinas técnicas, <b>el respeto es para todos</b>. Si a la otra persona le duele, <b>no es broma</b>, aunque otros se rían."},{"s":"karin_denuncia","t":"¿Cómo denuncio?","x":"Puedes denunciar <b>por escrito o verbalmente</b> ante el <b>empleador</b>, según el procedimiento del Reglamento Interno, o directamente ante la <b>Inspección del Trabajo</b>. La denuncia es <b>reservada</b>. Si la investiga la empresa, tiene un plazo máximo de <b>30 días</b> para terminarla. Guarda mensajes, fotos y nombres de testigos: ayudan a la investigación."},{"s":"karin_resguardo","t":"Medidas de resguardo","x":"Al recibir la denuncia, la empresa debe adoptar <b>de inmediato</b> medidas para proteger a quien denuncia: <b>separar los espacios</b> de trabajo, <b>cambiar la jornada</b> o la cuadrilla, y derivar a <b>atención psicológica</b> temprana en la ACHS, sin costo. Estas medidas no pueden perjudicar a la víctima."},{"s":"karin_represalia","t":"Sin represalias: apoya a la víctima","x":"Está prohibido tomar <b>represalias</b> contra quien denuncia o declara como testigo: despido, cambio a peores tareas, quitar horas extra, burlas o exclusión. Si ves un caso: no te rías ni reenvíes nada, <b>acompaña</b> a la persona afectada, ofrécete como testigo y anímala a denunciar.","k":"Nadie puede ser castigado por denunciar o declarar como testigo."}],"quiz":[{"s":"karin_laboral","v":[{"q":"Para que exista acoso laboral, la agresión tiene que repetirse varias veces.","vf":false,"w":"Falso. Con la Ley Karin basta una sola vez."},{"q":"Un jefe de obra humilla una sola vez a un carpintero frente a toda la cuadrilla. Según la Ley Karin:","o":["Puede ser acoso laboral aunque ocurra una vez","No es acoso porque ocurrió solo una vez","Solo es acoso si hay golpes","Solo es acoso si lo hace un compañero"],"w":"La ley no exige que se repita."},{"q":"¿Quién puede cometer acoso laboral?","o":["Un jefe, un compañero o un subordinado","Solo un jefe directo","Solo el dueño de la empresa","Solo alguien de otra empresa"],"w":"El acoso puede venir de cualquier dirección."}]},{"s":"karin_terceros","v":[{"q":"Un transportista insulta y amenaza a un trabajador al descargar en la obra. ¿La Ley Karin lo cubre?","o":["Sí, es violencia ejercida por terceros","No, porque no es de la empresa","Solo si hay golpes o lesiones","Solo si ocurre en la oficina de obra"],"w":"La violencia de externos también está cubierta."},{"q":"Un vecino de la obra te grita y te amenaza por el ruido. ¿Qué haces?","o":["Me alejo, aviso y si hay amenaza llamo al 133","Le respondo de la misma forma para que no vuelva","Lo saco de la obra empujándolo hacia la calle","Lo ignoro y no le cuento a nadie lo que pasó"],"w":"No se responde con violencia; se informa para tomar medidas."},{"q":"¿Cuál de estas personas puede ejercer violencia de terceros?","o":["Un proveedor que viene a dejar materiales","Un compañero de otra cuadrilla de la obra","Tu capataz directo en la obra","El jefe de obra o el administrador"],"w":"Terceros son personas externas a la empresa."}]},{"s":"karin_denuncia","v":[{"q":"¿Dónde puedes denunciar un caso de acoso?","o":["Ante el empleador o la Inspección del Trabajo","Solo ante Carabineros o la PDI","Solo ante el Comité Paritario de la obra","Solo ante un abogado o un juzgado"],"w":"Puedes elegir entre la empresa y la Inspección del Trabajo."},{"q":"¿Cómo se puede hacer una denuncia por Ley Karin?","o":["Por escrito o verbalmente","Solo por escrito ante notario","Solo por correo al gerente","Solo en persona en la Inspección"],"w":"La ley acepta ambas formas; la verbal queda registrada."},{"q":"Si la empresa investiga una denuncia por Ley Karin, tiene un plazo máximo de 30 días para terminarla.","vf":true,"w":"Verdadero. Ese es el plazo de la investigación."}]},{"s":"karin_burla","v":[{"q":"En la cuadrilla se burlan de un compañero extranjero por su forma de hablar. ¿Qué es?","o":["Puede ser acoso o discriminación","Una broma normal de obra","Solo un problema de idioma","Algo que se resuelve solo"],"w":"Las burlas por el origen pueden ser acoso."},{"q":"Un compañero dice que las bromas sobre su físico le molestan. ¿Qué corresponde?","o":["Dejar de hacerlas: si duele, no es broma","Seguir, porque son para alegrar el día","Explicarle que son sin mala intención","Hacerlas solo cuando él no está"],"w":"Lo que cuenta es cómo lo vive la persona afectada."},{"q":"Burlarse de un compañero por su nacionalidad puede ser acoso, aunque se diga que es broma.","vf":true,"w":"Verdadero. El respeto es para todos."}]},{"s":"karin_sexual","v":[{"q":"Mensajes por WhatsApp de contenido sexual no consentidos son:","o":["Acoso sexual","Una broma entre adultos","Un tema privado, fuera del trabajo","Falta solo si son en horario laboral"],"w":"Sin consentimiento es acoso, por cualquier medio."},{"q":"Un trabajador comenta el cuerpo de una compañera cada vez que pasa y dice que son piropos. ¿Qué es?","o":["Acoso sexual, porque no son consentidos","Un piropo sin importancia, si no la toca","Solo mala educación, no es acoso","Acoso solo si ella reclama por escrito"],"w":"Los comentarios sexuales no consentidos son acoso."},{"q":"Te llega por el grupo de la obra una foto íntima de una compañera. ¿Qué haces?","o":["No la reenvío, apoyo a la compañera y aviso","La reenvío solo a un amigo de confianza","La borro y no le digo nada a nadie","La comento en el grupo para que paren"],"w":"Reenviarla agrava el daño; avisar permite detenerlo."}]},{"s":"karin_represalia","v":[{"q":"Quien denuncia acoso puede ser cambiado a peores tareas mientras se investiga.","vf":false,"w":"Falso. Las represalias están prohibidas."},{"q":"Un trabajador declaró como testigo y ahora lo dejan fuera de las horas extra. ¿Qué es?","o":["Una represalia, y está prohibida","Una decisión normal de la jefatura","Una medida de resguardo","Algo permitido si no se comprobó"],"w":"Castigar a un testigo es una represalia."},{"q":"Ves que acosan a un compañero. ¿Qué haces?","o":["Lo acompaño, me ofrezco de testigo y lo animo","No me meto, para no tener problemas yo","Le digo que lo ignore y siga trabajando","Le digo que pida traslado a otra obra"],"w":"El apoyo de los compañeros ayuda a detener el acoso."}]},{"s":"karin_resguardo","v":[{"q":"Mientras se investiga una denuncia, la empresa puede:","o":["Separar espacios o cambiar la jornada para proteger","Suspender sin sueldo a quien hizo la denuncia","Esperar el resultado de la investigación sin cambios","Despedir a ambos para evitar más problemas"],"w":"Son medidas de resguardo para la víctima."},{"q":"¿Cuándo debe la empresa adoptar medidas de resguardo?","o":["De inmediato, al recibir la denuncia","Cuando termine la investigación","Solo si la Inspección lo ordena","Solo si hay lesiones físicas"],"w":"La protección no espera el resultado."},{"q":"¿Dónde puede recibir atención psicológica quien denuncia acoso?","o":["En la ACHS, sin costo","Solo en una consulta particular pagada","En la Inspección del Trabajo","En Carabineros"],"w":"La ACHS entrega atención psicológica temprana."}]},{"s":"karin_intro","v":[{"q":"La Ley Karin rige desde:","o":["El 1 de agosto de 2024","El 1 de enero de 2023","El 1 de febrero de 2025","El 1 de agosto de 2025"],"w":"Rige desde el 1 de agosto de 2024."},{"q":"¿Qué hace la Ley Karin?","o":["Previene, investiga y sanciona el acoso y la violencia","Regula las horas extra en la construcción","Fija las condiciones sanitarias de la obra","Regula la entrega de EPP"],"w":"Su objetivo es un trabajo libre de acoso y violencia."},{"q":"¿Qué número tiene la Ley Karin?","o":["21.643","16.744","20.949","20.096"],"w":"Es la Ley 21.643."}]}]},{"id":"altura","sec":"obra","title":"Trabajo en altura: losas, vanos y escalas","thumb":"pz_alt_arnes","learn":[{"s":"pz_alt_intro","t":"La primera causa de muerte en obra","x":"Las <b>caídas de altura</b> son la principal causa de accidentes graves y fatales en la construcción. Es trabajo en altura toda tarea sobre <b>1,8 metros</b> de un nivel inferior: bordes de losa, techumbres, andamios, escalas y vanos. Pero también hay lesiones graves por caídas menores, desde una escala baja o a una zanja: toda caída de altura puede ser grave."},{"s":"pz_alt_borde_ok","t":"Primero la protección colectiva","x":"Bordes de losa, escaleras sin terminar, techumbres y aberturas deben tener <b>baranda completa</b>: pasamanos a cerca de 1 metro, baranda intermedia y <b>rodapié</b>, o redes de seguridad. Protegen a todos, sin depender de que alguien se acuerde. Si una baranda está suelta, falta o la sacaron para subir material, <b>no trabajes ahí</b> y avisa."},{"s":"pz_alt_vano_ok","t":"Vanos y shafts","x":"Todo vano en losa o muro (shaft, escotilla, caja de escala, hueco de ascensor) debe estar <b>tapado con tapa fija, resistente y señalizada</b>, o con baranda. Un cartón o una plancha delgada suelta <b>no sirven</b>: se mueven o se rompen al pisarlos. Si sacas una tapa para trabajar, protege el vano mientras trabajas y <b>repónla fija</b> al terminar."},{"s":"pz_alt_arnes","t":"Arnés y cola de vida","x":"Donde no se puede instalar baranda se usa <b>arnés de cuerpo completo</b> con cola de vida con absorbedor de impacto, <b>anclado</b> a un punto de anclaje resistente o a una línea de vida, idealmente <b>sobre la cabeza</b>. Antes de usarlo, revisa cintas, costuras, argollas y ganchos: si tiene cortes, quemaduras o ya detuvo una caída, se retira. Un arnés sin anclar no detiene nada.","k":"Sobre 1,8 metros sin baranda: arnés anclado, siempre."},{"s":"pz_escala_ok","t":"Escalas de mano","x":"<ul><li>Apoyada en suelo firme, con inclinación <b>4 a 1</b>: un metro de separación por cada 4 de altura.</li><li>Sobresale <b>1 metro</b> sobre el punto de llegada y va <b>amarrada</b> arriba.</li><li>Sube y baja <b>de frente</b>, con <b>3 puntos de apoyo</b>: dos manos y un pie, o dos pies y una mano.</li><li>Sin herramientas en las manos: usa bolso o cuerda. Una persona a la vez.</li></ul>"},{"s":"pz_escala_mal","t":"Lo que no se hace con una escala","x":"<ul><li>Subir a los últimos peldaños o estirarse hacia el lado.</li><li>Usar escalas improvisadas, empalmadas o con peldaños rotos.</li><li>Pararse sobre tarros, bloques, sacos o carretillas para alcanzar.</li><li>Usar escalas metálicas cerca de líneas o tableros eléctricos.</li></ul>Si no alcanzas, <b>cambia de escala o usa un andamio</b>."},{"s":"pz_izaje_mal","t":"Caída de objetos","x":"Lo que cae desde arriba también mata: una herramienta pequeña que cae desde varios pisos puede causar una lesión grave, incluso con casco. Amarra las herramientas, usa <b>rodapiés</b>, no acopies material en los bordes y <b>cerca la zona de abajo</b>. Usa siempre casco con <b>barbiquejo</b>.","k":"Nunca pases bajo una carga suspendida ni bajo un trabajo en altura."},{"s":"pz_derechos","t":"Requisitos para trabajar en altura","x":"Solo trabaja en altura quien está <b>capacitado y autorizado</b>, con <b>examen de altura física vigente</b> cuando corresponda, y en buenas condiciones: descansado, sin mareos, sin alcohol ni drogas y sin medicamentos que den sueño. Si te sientes mal, dilo antes de subir. Ante un riesgo grave e inminente tienes derecho a <b>detenerte y avisar</b> (Código del Trabajo, artículo 184 bis)."},{"s":"pz_grave","t":"Si alguien cae","x":"Una caída de más de 1,8 metros es un <b>accidente grave</b>. Da la alarma y llama al <b>131</b>; no muevas al lesionado salvo peligro inminente. Se <b>paraliza</b> la faena, se <b>delimita</b> el lugar sin alterar nada y se <b>avisa</b> a la jefatura, que informa a la Inspección del Trabajo y a la SEREMI de Salud. Si alguien queda colgando del arnés, avisa de inmediato: debe ser rescatado lo antes posible."}],"quiz":[{"s":"pz_alt_intro","v":[{"q":"¿Desde qué altura se considera trabajo en altura?","o":["Sobre 1,8 metros","Sobre 3 metros","Sobre 2,5 metros","Sobre 1,2 metros"],"w":"Desde 1,8 metros, aunque una caída menor también puede ser grave."},{"q":"Vas a trabajar en el borde de una losa a 2 metros del nivel de abajo. ¿Es trabajo en altura?","o":["Sí, porque supera 1,8 metros","No, recién desde 3 metros","No, porque es dentro de la obra","Solo si es en techumbre"],"w":"Sobre 1,8 metros ya es trabajo en altura."},{"q":"Una caída desde menos de 1,8 metros nunca puede ser grave.","vf":false,"w":"Falso. Una caída desde una escala baja o a una zanja también puede ser grave."}]},{"s":"pz_alt_borde_mal","v":[{"q":"Un borde de losa está bien protegido cuando tiene:","o":["Pasamanos, baranda intermedia y rodapié","Solo una cinta de peligro","Solo un pasamanos a la cintura","Conos y un letrero de advertencia"],"w":"La baranda completa evita caídas de personas y de objetos."},{"q":"Llegas a trabajar a un borde de losa y ves que le falta la baranda. ¿Qué haces?","o":["No trabajo ahí y aviso para que la instalen","Trabajo con cuidado, lejos del borde","Pongo una cinta de peligro y sigo","Trabajo rápido para estar poco rato"],"w":"Sin protección colectiva no se trabaja en el borde."},{"q":"¿Para qué sirve el rodapié de una baranda?","o":["Para que no caigan objetos ni resbale un pie","Para afirmar la mano al caminar por el borde","Para apoyar ahí las herramientas de trabajo","Para marcar el borde con un color visible"],"w":"El rodapié cierra la parte baja de la baranda."}]},{"s":"pz_alt_vano_ok","v":[{"q":"Retiras la tapa de un shaft para pasar una cañería. Al terminar:","o":["La repongo fija y señalizada","La dejo apoyada al lado del vano","La cambio por un cartón visible","La dejo para que la ponga el siguiente"],"w":"Un vano abierto es una trampa para el que viene después."},{"q":"¿Cuál es una protección correcta para un vano en la losa?","o":["Una tapa fija, resistente y señalizada","Un cartón o una plancha delgada encima","Una cinta de peligro alrededor","Un saco de cemento sobre el hueco"],"w":"La tapa debe resistir el peso de una persona y no moverse."},{"q":"Mientras trabajas en un shaft destapado, el vano debe:","o":["Quedar protegido mientras trabajas","Quedar abierto, porque estás ahí","Quedar marcado solo con tiza","Quedar tapado con tu chaqueta"],"w":"Aunque estés ahí, otro puede caer si el vano queda sin protección."}]},{"s":"pz_alt_vano_mal","v":[{"q":"Ves un vano de shaft abierto, sin tapa ni baranda, en la losa. ¿Qué haces?","o":["Lo protejo o aviso de inmediato","Lo rodeo con cuidado y sigo","Le pongo un cartón encima","Espero la ronda del capataz"],"w":"Un vano abierto no se deja así ni un minuto."},{"q":"¿Por qué una plancha delgada suelta sobre un vano es peligrosa?","o":["Se puede mover o romper al pisarla","Porque ensucia la losa","Porque no tiene un color llamativo","Porque tapa la vista al gruero"],"w":"Parece protección, pero no resiste ni queda fija."},{"q":"Un vano tapado con un cartón está protegido si el cartón se ve bien.","vf":false,"w":"Falso. Debe ser una tapa fija, resistente y señalizada."}]},{"s":"pz_alt_arnes","v":[{"q":"El arnés protege aunque la cola de vida no esté anclada.","vf":false,"w":"Falso. Sin anclaje no detiene la caída."},{"q":"¿Dónde conviene anclar la cola de vida del arnés?","o":["A un punto resistente, idealmente sobre la cabeza","A la baranda o pasamanos más cercano","A un fierro de enfierradura que sobresale","A la escala de mano por la que subiste"],"w":"El anclaje debe resistir la caída; sobre la cabeza reduce la distancia de caída."},{"q":"Al revisar tu arnés ves una cinta cortada y una costura quemada. ¿Qué haces?","o":["Lo retiro y pido uno nuevo","Lo uso si el corte es pequeño","Lo reparo con cinta adhesiva","Lo uso solo en tareas cortas"],"w":"Un arnés dañado puede romperse justo en la caída."}]},{"s":"pz_escala_ok","v":[{"q":"Al subir por una escala de mano, ¿cuántos puntos de apoyo mantienes?","o":["3: dos manos y un pie, o dos pies y una mano","2: una mano y un pie","4: manos y pies siempre a la vez","1 mano, si llevas algo en la otra"],"w":"Tres puntos de apoyo evitan perder el equilibrio."},{"q":"Tienes que subir a la losa con un taladro. ¿Cómo lo haces?","o":["Con 3 apoyos y el taladro en bolso o con cuerda","Con el taladro en una mano y afirmado con la otra","Le lanzo el taladro a un compañero arriba","Con el taladro colgado del cable al hombro"],"w":"Las manos van libres para afirmarse."},{"q":"¿Cuánto debe sobresalir la escala sobre el punto de llegada?","o":["1 metro","Nada, a ras del borde","10 centímetros","3 metros"],"w":"Así tienes dónde afirmarte al subir y bajar."}]},{"s":"pz_escala_mal","v":[{"q":"Estás en una escala y te falta poco para alcanzar. ¿Qué haces?","o":["Bajo y uso una escala más larga o un andamio","Subo al último peldaño con cuidado","Me estiro hacia el lado afirmado con una mano","Pongo un bloque bajo la escala"],"w":"Estirarse o subir al final de la escala provoca caídas."},{"q":"¿Cuál de estas escalas está prohibido usar?","o":["Una escala empalmada con alambre","Una escala amarrada arriba","Una escala que sobresale 1 metro","Una escala con inclinación 4 a 1"],"w":"Las escalas improvisadas o empalmadas pueden ceder."},{"q":"Una escala metálica no debe usarse cerca de líneas o tableros eléctricos.","vf":true,"w":"Verdadero. El metal conduce la electricidad."}]},{"s":"pz_derechos","v":[{"q":"¿Quién puede trabajar en altura?","o":["Quien está capacitado, autorizado y apto","Cualquiera con varios años de experiencia","Quien tenga su propio arnés certificado","Quien sea joven, ágil y no tenga vértigo"],"w":"Se requiere capacitación, autorización y aptitud."},{"q":"Hoy amaneciste con mareos y te toca trabajar en el borde de la losa. ¿Qué haces?","o":["Aviso antes de subir y pido otra tarea","Subo igual y trabajo más despacio","Tomo un remedio y subo","Subo, pero me anclo dos veces"],"w":"Un mareo en altura puede terminar en caída."},{"q":"Ante un riesgo grave e inminente en altura, tienes derecho a detener tu trabajo y avisar.","vf":true,"w":"Verdadero. Lo establece el artículo 184 bis del Código del Trabajo."}]},{"s":"pz_izaje_mal","v":[{"q":"Debajo de un trabajo en altura, lo correcto es:","o":["Cercar la zona y que nadie pase","Pasar rápido mirando hacia arriba","Pasar con casco y barbiquejo","Avisar con un grito antes de pasar"],"w":"Los objetos que caen pueden matar, incluso con casco."},{"q":"La grúa levanta un paquete de moldajes y tu camino pasa por debajo. ¿Qué haces?","o":["Espero o doy la vuelta por fuera","Paso rápido antes de que suba más","Paso si el gruero me ve","Paso con el casco bien puesto"],"w":"Nunca se pasa bajo una carga suspendida."},{"q":"Trabajas en el tercer piso con herramientas. ¿Cómo evitas que caigan?","o":["Las amarro y no las dejo en el borde","Las dejo en el borde para tenerlas a mano","Grito si se me cae alguna","Uso solo herramientas pequeñas"],"w":"Amarrar herramientas y despejar bordes evita la caída de objetos."}]},{"s":"pz_grave","v":[{"q":"Un compañero cae desde 3 metros de una losa. ¿Qué se hace con el lugar?","o":["Se paraliza, se delimita sin alterar y se avisa","Se limpia para que nadie más tropiece","Se sigue trabajando lejos del punto","Se retira lo que causó la caída"],"w":"Es un accidente grave: paralizar, delimitar y avisar."},{"q":"Una caída de más de 1,8 metros se considera:","o":["Accidente grave","Accidente leve si no hay sangre","Incidente sin lesión","Accidente de trayecto"],"w":"La SUSESO la clasifica como accidente grave."},{"q":"Si un compañero queda colgando del arnés después de una caída, hay que avisar de inmediato porque debe ser rescatado lo antes posible.","vf":true,"w":"Verdadero. Quedar suspendido mucho tiempo es peligroso."}]}]},{"id":"andamios","sec":"obra","mins":5,"title":"Andamios seguros","thumb":"pz_andamio_ok","learn":[{"s":"pz_andamio_ok","t":"Un andamio es una estructura","x":"El andamio lo <b>arma personal capacitado</b>, según las instrucciones del fabricante, y lo revisa un responsable antes de usarlo: <b>cada día</b> y después de lluvia, viento fuerte o un sismo. No es un mueble que cualquiera arma, presta o modifica. Se usan solo piezas del mismo sistema, sin mezclar marcas ni reemplazar pasadores por alambre o clavos."},{"s":"pz_andamio_base","t":"La base","x":"Va apoyado en <b>suelo firme y nivelado</b>, con <b>placas base</b> sobre durmientes de madera que repartan el peso. Nunca sobre bloques, ladrillos, tarros, tierra suelta o relleno. Revisa que no haya zanjas ni agua que socave el terreno cerca de las patas. Los andamios altos se <b>arriostran o anclan</b> a la estructura según el fabricante."},{"s":"pz_andamio_mal","t":"Plataforma completa y con baranda","x":"La plataforma debe estar <b>completa</b>, sin huecos, con tablones o plataformas metálicas trabadas que no se deslicen. Lleva <b>baranda superior</b> a cerca de 1 metro, <b>baranda intermedia</b> y <b>rodapié</b> en todos los lados abiertos. Un andamio sin baranda es trabajo en altura sin protección.","k":"Sin baranda completa, no se trabaja en el andamio."},{"s":"pz_andamio_tarjetas","t":"Tarjeta antes de subir","x":"Revisa la tarjeta: <b>verde</b>, apto para usar; <b>amarilla</b>, uso con restricción, normalmente con <b>arnés anclado</b>; <b>roja</b>, no usar, porque está en armado, en desarme o con falla. Si no tiene tarjeta, no subas hasta que un responsable lo revise. La tarjeta la cambia solo quien inspecciona, nunca el usuario."},{"s":"pz_escala_ok","t":"Subir por el acceso","x":"Se sube por la <b>escalera del andamio</b> o su acceso interior, de frente y con <b>3 puntos de apoyo</b>. <b>No trepes por las crucetas</b>, los marcos ni por fuera: no están hechos para eso, puedes caer o desarmar piezas. Las herramientas y materiales se suben con cuerda o se pasan de mano en mano, no en las manos mientras subes."},{"s":"pz_andamio_mover","t":"Andamios móviles","x":"Las ruedas llevan <b>freno puesto</b> mientras se trabaja. <b>Nunca muevas el andamio con personas, herramientas o materiales arriba</b>. Antes de moverlo, revisa el camino: sin desniveles, zanjas, cables ni vanos, y lejos de líneas eléctricas. Se mueve empujando desde la base, nunca subido tirando de un muro.","k":"Nunca muevas un andamio con alguien arriba."},{"s":"pz_acopio","t":"Material: lo justo arriba","x":"Sobre la plataforma sube solo el material del momento: no acumules sacos, bloques, ladrillos ni moldajes. Respeta la <b>carga máxima</b> del fabricante y reparte el peso. Nada apoyado en las barandas. El resto queda abajo, <b>acopiado sobre tacos, estable y a baja altura</b>, fuera de los pasillos."},{"s":"pz_derechos","t":"Si algo cambió, no lo uses","x":"Si falta una baranda, un tablón está suelto, una placa base se hundió o alguien sacó una pieza, <b>no lo uses y avisa</b>. Nadie puede modificar un andamio sin autorización: si hay que retirar una baranda para pasar material, lo hace el responsable y se trabaja con arnés anclado. Ante un riesgo grave e inminente tienes derecho a <b>detenerte y avisar</b>."}],"quiz":[{"s":"pz_andamio_mal","v":[{"q":"Un andamio está en condición segura cuando:","o":["Está completo, nivelado, con baranda y tarjeta verde","Tiene tarjeta verde, aunque le falte el rodapié","Está nivelado sobre bloques firmes y con baranda","Tiene baranda superior y el resto es opcional"],"w":"Se exigen todas las condiciones a la vez."},{"q":"Llegas a un andamio sin baranda y con la base sobre bloques. ¿Qué haces?","o":["No lo uso y aviso al responsable","Lo uso con arnés anclado, sin más","Lo uso si es por poco rato","Le pongo una cinta de peligro y subo"],"w":"Un andamio mal armado no se usa hasta que se corrija."},{"q":"¿Qué debe tener la plataforma de trabajo de un andamio?","o":["Superficie completa, baranda, intermedia y rodapié","Tablones, aunque queden huecos pequeños entre ellos","Solo una baranda superior a la altura del pecho","Tablones sueltos para moverlos según el trabajo"],"w":"Plataforma completa y trabada, con baranda y rodapié."}]},{"s":"pz_andamio_tarjetas","v":[{"q":"Un andamio con tarjeta roja:","o":["No se usa: está en armado, desarme o con falla","Se usa, pero solo con arnés anclado","Se usa con cuidado y sin cargar material","Se usa con permiso verbal del capataz"],"w":"Roja = no usar."},{"q":"¿Qué significa la tarjeta amarilla en un andamio?","o":["Uso con restricción, normalmente con arnés anclado","Uso libre, sin ninguna condición especial","No usar, porque está en armado o con falla","Uso solo para guardar material arriba"],"w":"Amarilla = se usa cumpliendo la restricción."},{"q":"Si ves que el andamio ya está reparado, puedes cambiar tú mismo la tarjeta roja por una verde.","vf":false,"w":"Falso. La tarjeta la cambia solo quien inspecciona."}]},{"s":"pz_andamio_base","v":[{"q":"Se puede apoyar la base del andamio sobre ladrillos para nivelarlo.","vf":false,"w":"Falso. Se usan placas base y durmientes en suelo firme."},{"q":"¿Sobre qué se apoya la base de un andamio?","o":["Placas base sobre durmientes, en suelo firme","Ladrillos o bloques para nivelar","Directo sobre la tierra si está seca","Tarros rellenos con hormigón"],"w":"Los durmientes reparten el peso y las placas base lo estabilizan."},{"q":"El terreno bajo un andamio quedó blando por la lluvia. ¿Qué haces?","o":["No lo uso y aviso para que lo revisen","Lo uso si las ruedas tienen freno","Calzo las patas con trozos de ladrillo","Subo con menos material"],"w":"Después de lluvia el andamio se revisa antes de usarse."}]},{"s":"pz_escala_ok","v":[{"q":"Para subir al andamio, se usa:","o":["La escalera o acceso propio del andamio","Las crucetas, si están firmes","Los marcos por el lado de afuera","Un tambor como escalón"],"w":"Las crucetas y marcos no son escalera."},{"q":"Un compañero trepa por las crucetas porque la escalera está al otro lado. ¿Qué le dices?","o":["Que use la escalera: las crucetas no son para subir","Que está bien si se afirma con las dos manos","Que suba con arnés y no habrá problema","Que lo haga rápido para no cansarse"],"w":"Trepar por las crucetas puede soltarlas o provocar una caída."},{"q":"¿Cómo subes una caja de herramientas a un andamio?","o":["Con cuerda o pasándola, no en la mano al subir","En una mano mientras subo con la otra","Colgada del cuello mientras subo","Lanzándola a un compañero de arriba"],"w":"Subes con 3 puntos de apoyo y las manos libres."}]},{"s":"pz_andamio_mover","v":[{"q":"Antes de mover un andamio móvil, debes:","o":["Bajar personas y material y revisar el camino","Avisar al de arriba que se afirme bien","Soltar los frenos solo de un lado","Moverlo despacio sin bajar herramientas"],"w":"Nadie ni nada arriba al moverlo."},{"q":"Las ruedas de un andamio móvil, mientras se trabaja, deben estar:","o":["Con freno puesto","Sin freno, para moverlo fácil","Con freno solo en dos ruedas","Calzadas con trozos de madera"],"w":"El freno evita que el andamio se desplace."},{"q":"Antes de mover un andamio móvil hay que bajar a las personas, las herramientas y los materiales.","vf":true,"w":"Verdadero. Nunca se mueve con algo o alguien arriba."}]},{"s":"pz_derechos","v":[{"q":"Ves que alguien sacó la baranda del andamio para subir material. ¿Qué haces?","o":["No lo uso y aviso al responsable","Subo igual y me alejo del borde","La vuelvo a poner yo como pueda","Termino mi tarea y aviso después"],"w":"Un andamio modificado debe revisarse antes de usarse."},{"q":"¿Quién puede retirar una pieza de un andamio?","o":["Solo el responsable, con autorización","Cualquiera que la necesite y la reponga","El que esté trabajando arriba","El capataz de otra cuadrilla"],"w":"Nadie modifica un andamio sin autorización."},{"q":"Un andamio al que le falta una baranda no se debe usar hasta que lo revise un responsable.","vf":true,"w":"Verdadero. Falta protección contra caídas."}]},{"s":"pz_andamio_ok","v":[{"q":"¿Quién puede armar un andamio?","o":["Personal capacitado, según el fabricante","Cualquier trabajador con experiencia","El que lo va a usar, a su manera","El capataz, aunque no esté capacitado"],"w":"Es una estructura: la arma quien sabe."},{"q":"Faltan pasadores para unir dos marcos y un compañero propone usar alambre. ¿Qué haces?","o":["No lo acepto: solo piezas del sistema","Lo acepto si el alambre es grueso","Uso clavos, que son más firmes","Lo amarro con cinta y aviso después"],"w":"Las piezas improvisadas pueden ceder con la carga."},{"q":"¿Cuándo se debe revisar un andamio?","o":["Cada día y tras lluvia, viento o sismo","Solo cuando se termina de armar","Una vez al mes","Solo cuando alguien reclama"],"w":"Las condiciones cambian: se revisa antes de cada uso."}]},{"s":"pz_acopio","v":[{"q":"¿Cuánto material puedes tener sobre la plataforma del andamio?","o":["Solo el necesario, sin pasar la carga máxima","Todo el de la jornada, para no bajar","Lo que quepa, si el andamio es firme","El que se pueda apoyar en las barandas"],"w":"El exceso de peso puede colapsar la plataforma."},{"q":"Un compañero quiere subir 20 sacos de mortero de una vez a la plataforma. ¿Qué le dices?","o":["Que suba solo lo necesario, sin pasar la carga máxima","Que está bien si reparte los sacos en la plataforma","Que los apoye contra la baranda para que no estorben","Que puede hacerlo si el andamio tiene tarjeta verde"],"w":"La tarjeta verde no autoriza a sobrecargar."},{"q":"¿Dónde se deja el material que no se está usando?","o":["Abajo, sobre tacos, estable y bajo","Sobre la plataforma, junto a la baranda","Colgado de las barandas","En la escalera de acceso"],"w":"Arriba solo lo del momento; el resto, acopiado abajo."}]}]},{"id":"excavaciones","sec":"obra","title":"Excavaciones y zanjas","thumb":"pz_zanja_ok","mins":5,"learn":[{"s":"pz_zanja_intro","t":"La tierra pesa","x":"Un metro cúbico de tierra pesa <b>entre 1,5 y 2 toneladas</b>. Un derrumbe puede atrapar a una persona hasta el pecho y asfixiarla en minutos, aunque la zanja no se vea profunda: muchos accidentes ocurren en zanjas de menos de 2 metros. La pared puede caer <b>sin aviso</b>, incluso cuando el suelo parece firme."},{"s":"pz_servicios","t":"Antes de excavar","x":"Se revisan los <b>planos</b> y se ubican y marcan en terreno los servicios enterrados: <b>electricidad, gas, agua potable, alcantarillado y telecomunicaciones</b>. Cerca de ellos se excava con cuidado, a mano si el procedimiento lo indica. Si aparece una <b>cinta de advertencia</b> o un servicio que no estaba en los planos, <b>se detiene la excavación y se avisa</b>. Cortar un cable o una cañería de gas puede ser fatal."},{"s":"pz_zanja_ok","t":"Paredes protegidas","x":"Las paredes se protegen con <b>entibación</b> (tablones o paneles con puntales) o con <b>talud</b> (paredes inclinadas), según el tipo de suelo, la profundidad y el procedimiento de {EMP}. La protección se instala <b>antes de entrar</b> y no se retira mientras haya personas adentro. El borde de la zanja se <b>cerca y señaliza</b> para que nadie caiga.","k":"Nadie entra a una zanja sin sus paredes protegidas."},{"s":"pz_zanja_talud","t":"El talud","x":"Cuando hay espacio, las paredes se inclinan para que la tierra no se venga encima. La inclinación depende del <b>tipo de suelo</b> y la define el procedimiento, no se decide al ojo ni la decide el operador. Un suelo <b>arenoso, suelto, húmedo o de relleno</b> es más inestable y necesita paredes <b>más tendidas</b> que un suelo natural firme."},{"s":"pz_zanja_borde","t":"Bordes libres","x":"La tierra excavada, los materiales y las máquinas van <b>lejos del borde</b>, a la distancia que indique el procedimiento: su peso carga la pared y la puede derrumbar sobre quien está adentro, aunque la zanja esté entibada. Los camiones no descargan ni se estacionan junto a la zanja, y la vibración de las máquinas cercanas también debilita las paredes."},{"s":"pz_zanja_ok","t":"Entrar y salir","x":"Debe haber una <b>escala</b> cerca de donde trabajas, amarrada y <b>sobresaliendo cerca de 1 metro</b> sobre el borde. Sube y baja de frente a la escala, con <b>tres puntos de apoyo</b> y las manos libres: las herramientas se bajan con cuerda o balde. Nunca saltes a la zanja ni salgas trepando por las paredes o los puntales."},{"s":"pz_retro_radio","t":"Máquina trabajando","x":"Nadie trabaja dentro de la zanja <b>mientras la retro excava en ese tramo</b>, ni se ubica dentro de su <b>radio de giro</b>. Antes de acercarte, haz <b>contacto visual</b> con el operador y espera su señal. Las maniobras cerca de personas las guía un señalero, y el balde nunca pasa por encima de nadie."},{"s":"pz_zanja_mal","t":"Señales de peligro","x":"Grietas en el borde, tierra que se desprende, <b>agua que aflora</b>, paredes que se abomban o una entibación que cruje o se mueve: <b>sal de inmediato por la escala y avisa</b> a tu jefatura, aunque te falte poco para terminar. Después de lluvias, heladas o vibraciones fuertes, la excavación la revisa el responsable <b>antes de entrar</b>, aunque ayer estuviera bien.","k":"Si ves grietas o tierra que cae, sal de inmediato y avisa."},{"s":"pz_grave","t":"Si hay un derrumbe","x":"Un atrapamiento por derrumbe es un <b>accidente grave</b> según SUSESO: se <b>paraliza</b> la faena, se <b>delimita</b> el área y se <b>avisa</b> de inmediato a la jefatura. Llama al <b>131</b> (SAMU) y al <b>132</b> (Bomberos, rescate). No bajen todos a sacar tierra con pala: otra pared puede caer y atrapar a más personas. La atención del accidentado la entrega la ACHS (1404)."}],"quiz":[{"s":"pz_zanja_ok","v":[{"q":"Antes de bajar a una zanja de 2 metros, ¿qué condiciones deben estar listas?","o":["Paredes entibadas o en talud, escala cercana y borde cercado","Escala cercana y un compañero mirando desde el borde","Paredes entibadas, aunque la escala esté en el otro extremo","Borde cercado y casco con barbiquejo bien puesto"],"w":"Se necesitan las tres cosas: paredes protegidas, salida a mano y borde cercado."},{"q":"Vas a entrar a una zanja. ¿Cuál de estas zanjas está en condición segura?","o":["Entibada, con escala de salida cerca y cercada arriba","Sin entibar, pero con escala y un vigía en el borde","Entibada, pero con la tierra acopiada junto al borde","Cercada arriba, con suelo duro y sin entibación"],"w":"Paredes protegidas, salida cercana y borde cercado y despejado."},{"q":"Si el suelo se ve duro y seco, se puede entrar a una zanja sin entibación ni talud aunque el procedimiento los exija.","vf":false,"w":"Falso. La pared puede caer sin aviso aunque el suelo parezca firme."}]},{"s":"pz_servicios","v":[{"q":"Antes de excavar con la retro en un sector nuevo, ¿qué debe hacerse primero?","o":["Revisar planos y ubicar los servicios enterrados","Marcar el ancho de la zanja con cal y partir","Excavar despacio el primer metro con la máquina","Preguntar al operador si conoce bien el terreno"],"w":"Cortar un cable o una cañería de gas puede ser fatal."},{"q":"La retro deja a la vista una cinta de advertencia que no estaba en los planos. ¿Qué corresponde?","o":["Detener la excavación y avisar a la jefatura","Seguir, pero excavando más despacio","Cortar la cinta y seguir si no se ve cable","Excavar a mano hasta encontrar qué hay y seguir"],"w":"Un servicio no informado puede ser gas o electricidad: se detiene y se avisa."},{"q":"¿Qué servicios enterrados se deben ubicar antes de excavar?","o":["Electricidad, gas, agua y alcantarillado","Solo las cañerías de agua potable","Solo el alcantarillado, lo demás va aéreo","Solo los cables, el gas va siempre por fuera"],"w":"Todos pueden estar bajo tierra y cualquiera puede causar un accidente."}]},{"s":"pz_zanja_borde","v":[{"q":"¿Dónde se deja la tierra que sale de la zanja?","o":["Lejos del borde, a la distancia que fija el procedimiento","Junto al borde, para tenerla a mano al rellenar","Sobre el borde, apisonada para que haga de baranda","En el extremo de la zanja donde no se trabaja"],"w":"Su peso carga la pared y puede derrumbarla."},{"q":"Un camión tolva necesita descargar áridos cerca de una zanja con gente adentro. ¿Qué corresponde?","o":["Que descargue lejos del borde, donde no cargue la pared","Que descargue rápido junto al borde y se retire","Que descargue junto al borde si la zanja está entibada","Que descargue junto al borde con un señalero guiando"],"w":"El peso y la vibración junto al borde pueden derrumbar la pared, incluso entibada."},{"q":"La pila de tierra junto a la zanja ya llega hasta el borde. ¿Qué riesgo genera?","o":["Su peso puede derrumbar la pared sobre quien está adentro","Solo ensucia el fondo de la zanja cuando llueve","Solo dificulta el relleno al final de la obra","Solo es un riesgo si la tierra está mojada"],"w":"El peso cerca del borde es una causa típica de derrumbe."}]},{"s":"pz_zanja_mal","v":[{"q":"Trabajando en la zanja ves que se abre una grieta en el borde. ¿Qué haces?","o":["Salgo de inmediato por la escala y aviso","Termino lo que estoy haciendo y luego aviso","Pongo un tablón contra la pared y sigo","Sigo, pero pido a un compañero que vigile"],"w":"La grieta anuncia un derrumbe: primero salir, después avisar."},{"q":"La entibación cruje y empieza a salir agua por una pared. ¿Qué corresponde?","o":["Salir de inmediato y avisar a la jefatura","Achicar el agua con un balde y seguir","Apretar los puntales y seguir trabajando","Esperar adentro a que llegue el supervisor"],"w":"Agua y entibación que se mueve son señales de derrumbe."},{"q":"Después de una lluvia intensa, si la zanja estaba bien el día anterior, se puede entrar sin revisarla.","vf":false,"w":"Falso. El agua debilita las paredes: el responsable la revisa antes de entrar."}]},{"s":"pz_zanja_ok","v":[{"q":"¿Cómo se sale correctamente de una zanja?","o":["Por la escala, con tres puntos de apoyo y manos libres","Trepando por los puntales de la entibación","Apoyando un pie en la pared y empujándote al borde","Por la escala, cargando las herramientas en una mano"],"w":"Con las manos libres mantienes tres puntos de apoyo."},{"q":"Necesitas tener herramientas abajo en la zanja. ¿Cómo lo haces?","o":["Bajo con manos libres y las bajo con cuerda o balde","Bajo por la escala con las herramientas en una mano","Las lanzo al fondo y luego bajo por la escala","Salto con cuidado y que me las pasen desde arriba"],"w":"Subir o bajar cargando quita apoyo y provoca caídas."},{"q":"La escala para salir de la zanja debe:","o":["Estar cerca de donde trabajas y sobresalir del borde","Estar en un extremo, aunque trabajes en el otro","Quedar a ras del borde para no tropezar arriba","Usarse solo para bajar; se sale por el talud"],"w":"Debe estar a mano y sobresalir cerca de 1 metro para subir con seguridad."}]},{"s":"pz_retro_mal","v":[{"q":"La retro está excavando el tramo donde debes instalar tubería. ¿Qué haces?","o":["Espero fuera de su radio de giro hasta que termine","Bajo por el otro extremo y avanzo con cuidado","Trabajo dentro de la zanja, lejos del balde","Me ubico detrás de la máquina, donde no excava"],"w":"Máquina excavando en el tramo: nadie abajo ni dentro del radio de giro."},{"q":"Necesitas acercarte a una retro que está trabajando. ¿Qué corresponde?","o":["Hacer contacto visual con el operador y esperar su señal","Acercarte por detrás, donde no llega el balde","Gritarle al operador y acercarte de inmediato","Acercarte por un costado cuando el brazo está quieto"],"w":"Si el operador no te ve, no sabe que estás ahí."},{"q":"¿Dónde debes estar mientras la retro gira con el balde cargado?","o":["Fuera de su radio de giro, a la vista del operador","Detrás de la máquina, donde el operador no mira","Junto a la rueda o la oruga, que no se mueve","Dentro de la zanja, bajo el nivel del balde"],"w":"El giro puede golpearte y el balde puede soltar material."}]},{"s":"pz_zanja_talud","v":[{"q":"¿Qué define la inclinación del talud?","o":["El tipo de suelo, según el procedimiento de la obra","La experiencia del operador de la retro","Solo la profundidad, el tipo de suelo da lo mismo","El ancho del balde que va a excavar"],"w":"Cada suelo resiste distinto: no se decide al ojo."},{"q":"En un suelo arenoso y suelto, el talud debe ser:","o":["Más tendido que en un suelo firme","Igual que en suelo firme si la zanja es corta","Más vertical, para que la arena no se esparza","Innecesario, porque la arena se sostiene sola"],"w":"Un suelo suelto se desmorona más: necesita paredes más inclinadas."},{"q":"Comparado con un suelo natural firme, un suelo de relleno o removido es:","o":["Más inestable y necesita más protección","Más estable, porque ya fue compactado","Igual de estable si está seco","Más estable si tiene piedras grandes"],"w":"El suelo removido pierde cohesión y se derrumba con más facilidad."}]},{"s":"pz_grave","v":[{"q":"Una pared se derrumba y deja a un compañero atrapado. ¿Qué corresponde?","o":["Avisar, llamar al 131 y al 132, y no bajar todos a la zanja","Bajar todos de inmediato a sacar la tierra con pala","Sacarlo tirándolo de los brazos lo antes posible","Usar la retro para retirar la tierra de encima"],"w":"Otra pared puede caer: se pide rescate y se avisa de inmediato."},{"q":"Según SUSESO, un atrapamiento por derrumbe en una zanja es:","o":["Un accidente grave: se paraliza, se delimita y se avisa","Un accidente leve si el trabajador sale caminando","Un incidente que se informa al final del turno","Grave solo si hay más de un trabajador herido"],"w":"El atrapamiento está en la lista de accidentes graves."},{"q":"Un atrapamiento por derrumbe es un accidente grave: la faena se paraliza, se delimita el área y se avisa de inmediato.","vf":true,"w":"Verdadero. Es lo que exige SUSESO ante un accidente grave."}]}]},{"id":"herramientas","sec":"obra","title":"Herramientas manuales y eléctricas en obra","thumb":"herr_esmeril","mins":5,"learn":[{"s":"herr_cc_intro","t":"Las herramientas de la obra","x":"Martillo, combo, chuzo, napoleón, cuchillo cartonero, esmeril angular, taladro, rotomartillo, sierra circular y atornillador. Mal usadas o en mal estado causan <b>cortes, golpes, partículas en los ojos y descargas eléctricas</b>. Usa solo herramientas para las que fuiste instruido y que {EMP} te entregó; si no sabes usar una, pregunta antes de partir."},{"s":"herr_revisar","t":"Revísala antes de usar","x":"Mangos firmes, sin astillas ni cabezas sueltas. En las eléctricas revisa <b>cable, enchufe y carcasa</b> sin daños, que el interruptor funcione y que la protección esté puesta. Si está mala, <b>no se usa</b>: se etiqueta fuera de servicio y se reporta. Nunca la repares tú ni le pongas cinta a un cable pelado."},{"s":"herr_cc_mano","t":"La herramienta adecuada","x":"Cada herramienta para lo suyo: no uses un destornillador como cincel, ni la uña del martillo de carpintero para golpear cinceles o fierros; para eso está el <b>combo</b> o martillo de golpe. Una herramienta improvisada <b>se resbala, se quiebra o salta</b> a la cara. Lleva las herramientas en el cinturón portaherramientas, no en los bolsillos."},{"s":"herr_esmeril","t":"Esmeril angular","x":"<ul><li><b>Protección</b> del disco y <b>mango lateral</b> puestos; se toma con las dos manos.</li><li>Disco del tamaño correcto y con <b>RPM igual o mayor</b> a la de la máquina. Nunca saques la protección para meter un disco más grande.</li><li>Lentes y careta facial, fonos, guantes y respirador si cortas hormigón.</li><li>Chispas hacia el suelo, lejos de personas, pinturas, gas y combustibles.</li></ul>","k":"Protección, mango y careta: siempre."},{"s":"herr_circular","t":"Sierra circular manual","x":"La <b>protección inferior</b> del disco debe volver sola a su lugar: nunca la amarres ni la trabes abierta. Apoya y afirma la pieza, con las manos fuera de la línea de corte. Al terminar, espera que el disco <b>se detenga</b> antes de dejar la sierra. Si el disco se aprieta, la sierra puede <b>rebotar</b> hacia ti: no te ubiques detrás de la línea de corte."},{"s":"herr_desenchufar","t":"Desenchufa para cambiar","x":"Para cambiar el disco, la broca o la hoja, <b>desenchufa</b> la herramienta o saca la batería: apagarla no basta, porque el gatillo puede activarse por accidente. Nunca bloquees el interruptor con cinta. Usa la llave de la herramienta y revisa que el disco nuevo no tenga trizaduras antes de montarlo.","k":"Cambio de accesorio: herramienta desenchufada o sin batería."},{"s":"herr_taladro","t":"Taladro y rotomartillo","x":"Afirma la pieza con prensa, no la sostengas con la mano. Usa el mango lateral: si la broca se traba, la máquina gira con fuerza y te puede torcer la muñeca; suelta el gatillo. Al perforar hormigón o ladrillo usa <b>lentes, fonos y respirador con filtro para partículas</b> por el polvo de sílice. Antes de perforar un muro, revisa que no pasen cañerías ni cables."},{"s":"herr_cables","t":"Cables, extensiones y agua","x":"Las herramientas se conectan a un <b>tablero de faena con diferencial</b>, nunca a cualquier enchufe. Nunca uses una herramienta o extensión mojada, pelada o parchada con cinta. Desenrolla <b>por completo</b> el carrete, porque enrollado se calienta. No tires del cable para desenchufar ni levantes la herramienta colgando del cable."},{"s":"herr_cc_cartBien","t":"Cortes con cuchillo","x":"Al cortar yeso cartón o membranas con cuchillo cartonero, <b>corta hacia afuera</b> del cuerpo, con la otra mano <b>fuera de la línea de corte</b> y sobre una superficie firme. Usa guantes anticorte si la tarea lo exige. Al terminar, <b>retrae o guarda la hoja</b>: nunca dejes el cuchillo abierto en el bolsillo, el suelo o sobre las planchas."}],"quiz":[{"s":"herr_esmerilMal","v":[{"q":"Un compañero va a usar el esmeril así. ¿Qué está mal?","o":["Le falta la protección del disco","Le falta el mango, pero la protección está bien","El disco debería ser de mayor diámetro","Nada, si usa careta facial"],"w":"Sin protección, un disco que revienta lanza trozos hacia la persona."},{"q":"Se rompió el disco y solo queda uno más grande, que no cabe con la protección puesta. ¿Qué hace?","o":["No lo usa y busca un disco del tamaño correcto","Saca la protección para que el disco quepa","Lo usa sin protección, pero con careta facial","Lo usa sin protección solo para cortes cortos"],"w":"La protección nunca se saca: el disco debe ser del tamaño de la máquina."},{"q":"Se puede sacar la protección del esmeril para usar un disco más grande si se usa careta facial.","vf":false,"w":"Falso. La careta no detiene los trozos de un disco que revienta."}]},{"s":"herr_q_cambio","v":[{"q":"Vas a cambiar el disco del esmeril. ¿Qué haces primero?","o":["Lo desenchufo de la extensión","Lo apago del interruptor y lo cambio","Bloqueo el gatillo con cinta y lo cambio","Espero que se enfríe y lo cambio enchufado"],"w":"Sin energía no puede arrancar por accidente."},{"q":"¿Por qué se desenchufa el esmeril antes de cambiar el disco, en vez de solo apagarlo?","o":["Porque el gatillo puede activarse por accidente","Porque así el disco se enfría más rápido","Porque lo exige la garantía de la máquina","Porque apagado igual se calienta el motor"],"w":"Un toque involuntario del gatillo pone el disco a girar en tu mano."},{"q":"Para cambiar el disco, un compañero bloquea el gatillo con cinta y deja el esmeril enchufado. ¿Qué le dices?","o":["Que lo desenchufe: la cinta no evita un arranque","Que está bien si el esmeril quedó apagado","Que está bien si lo hace con guantes","Que está bien si el cambio es rápido"],"w":"Solo sin energía la herramienta no puede arrancar."}]},{"s":"herr_revisar","v":[{"q":"Revisas el taladro y el cable tiene un corte con el cobre a la vista. ¿Qué haces?","o":["Lo dejo fuera de uso, lo etiqueto y aviso","Le pongo cinta aislante y lo uso con cuidado","Lo uso solo en sectores secos de la obra","Corto el cable y le pongo otro enchufe"],"w":"Una herramienta dañada no se usa ni la repara el trabajador."},{"q":"¿Qué revisas en una herramienta eléctrica antes de usarla?","o":["Cable, enchufe, carcasa, interruptor y protección","Solo que encienda al apretar el gatillo","Solo el disco o la broca que trae puesta","Solo el enchufe, que es lo que más se daña"],"w":"Cualquiera de esas partes dañada puede causar una descarga o un corte."},{"q":"Un cable pelado se puede reparar con cinta aislante y seguir usando la herramienta.","vf":false,"w":"Falso. Se saca de uso, se etiqueta y se reporta."}]},{"s":"herr_q_disco","v":[{"q":"Tu esmeril gira a 11.000 RPM. ¿Qué disco puedes usar?","o":["Uno marcado con 11.000 RPM o más","Uno marcado con 8.500 RPM","Cualquiera del mismo diámetro","Uno de 10.000 RPM si el corte es corto"],"w":"El disco debe resistir igual o más RPM que la máquina."},{"q":"¿Por qué el disco debe soportar igual o más RPM que la máquina?","o":["Porque si gira más de lo que resiste, revienta","Porque así corta más rápido el material","Porque así dura más y se gasta parejo","Porque así la máquina se calienta menos"],"w":"Un disco sobrepasado se rompe en trozos que salen disparados."},{"q":"Un disco dice 8.000 RPM y tu esmeril gira a 12.000 RPM. ¿Qué haces?","o":["No lo uso y busco un disco adecuado","Lo uso apretando menos el gatillo","Lo uso solo para desbastar suave","Lo uso con careta facial y guantes"],"w":"El esmeril gira a su velocidad completa: ese disco puede reventar."}]},{"s":"herr_taladro","v":[{"q":"Vas a perforar una losa con rotomartillo. ¿Qué EPP agregas al casco y los zapatos?","o":["Lentes, fonos y respirador para partículas","Guantes y lentes, sin respirador","Fonos y mascarilla de tela","Solo careta facial"],"w":"Hay partículas, ruido y polvo de sílice."},{"q":"Perforas ladrillo con rotomartillo en un recinto cerrado. ¿Qué protección respiratoria usas?","o":["Respirador con filtro para partículas","Mascarilla quirúrgica bien puesta","Un pañuelo húmedo sobre nariz y boca","Ninguna, si dejo una ventana abierta"],"w":"Solo un respirador con filtro retiene el polvo fino de sílice."},{"q":"¿Por qué se usa respirador al perforar hormigón?","o":["Porque el polvo tiene sílice que daña los pulmones","Porque el olor del hormigón irrita la nariz","Porque la broca suelta humo al calentarse","Porque evita que el polvo ensucie la cara"],"w":"La sílice respirada causa silicosis."}]},{"s":"herr_cc_mano","v":[{"q":"Necesitas abrir una ranura en un muro y no tienes cincel a mano. ¿Qué haces?","o":["Busco el cincel o la herramienta correcta","Uso un destornillador grande y el martillo","Uso la punta del napoleón como cincel","Uso un trozo de fierro afilado"],"w":"Una herramienta improvisada se quiebra, se resbala o salta."},{"q":"¿Qué puede pasar si usas un destornillador como cincel?","o":["Se puede quebrar, resbalar o saltar a la cara","Nada, si el destornillador es de buena marca","Solo se gasta la punta más rápido","Nada, si se golpea con un combo pequeño"],"w":"No está hecho para recibir golpes."},{"q":"Para golpear un cincel o un fierro, ¿qué herramienta corresponde?","o":["Un combo o martillo de golpe","Un martillo de carpintero de uña","La parte trasera del napoleón","El costado de una llave de punta"],"w":"Cada herramienta para lo suyo."}]},{"s":"herr_cables","v":[{"q":"¿Dónde se conecta una herramienta eléctrica en la obra?","o":["A un tablero de faena con diferencial","Al enchufe más cercano que funcione","Directo a los cables del tablero, sin enchufe","A una zapatilla doméstica en buen estado"],"w":"El diferencial corta la corriente si hay una fuga."},{"q":"Usas una extensión en carrete. ¿Cómo debe estar?","o":["Desenrollada por completo y fuera del agua","Enrollada, para que no estorbe en el paso","Desenrollada solo lo necesario, aunque pase por agua","Enrollada, pero lejos de los charcos"],"w":"Enrollada se calienta, y con agua hay riesgo de descarga."},{"q":"Las herramientas eléctricas deben conectarse a un tablero con protector diferencial.","vf":true,"w":"Verdadero. Es la protección contra descargas por fuga de corriente."}]},{"s":"herr_cc_cartMal","v":[{"q":"Cortas una plancha de yeso cartón con cuchillo cartonero. ¿Cómo lo haces?","o":["Hacia afuera del cuerpo, con la otra mano fuera de la línea","Hacia ti, para tener más control del corte","Hacia ti, con la otra mano sujetando delante","Hacia el lado, sujetando la plancha con la rodilla"],"w":"Si la hoja se resbala, no debe ir hacia tu cuerpo ni tu mano."},{"q":"Terminaste de cortar membrana con el cuchillo cartonero. ¿Qué haces con la hoja?","o":["La retraigo o la guardo","Lo guardo abierto en el bolsillo","Lo dejo abierto sobre la plancha","Lo dejo abierto en el suelo junto a mí"],"w":"Una hoja expuesta corta a quien la encuentra."},{"q":"Al usar cuchillo cartonero, la mano que sujeta el material va:","o":["Fuera de la línea de corte","Delante de la hoja, para guiarla","Bajo el material, donde pasa la hoja","Pegada a la hoja, para que no se desvíe"],"w":"Si la hoja se desvía, no debe encontrar tu mano."}]}]},{"id":"maquinas","sec":"obra","title":"Sierra circular de banco y máquinas de corte","thumb":"pz_sierra_ok","mins":5,"learn":[{"s":"pz_sierra_ok","t":"La sierra de banco","x":"En obra se usa para dimensionar tablas, moldajes y placas. La opera solo quien está <b>instruido y autorizado</b>. Un disco a miles de vueltas por minuto causa cortes graves y amputaciones. Además puede <b>rebotar</b>: la pieza sale disparada hacia el operador, en la línea del disco. Por eso te ubicas a un costado y <b>nadie se para en la línea de corte</b>."},{"s":"pz_sierra_mal","t":"Protección siempre puesta","x":"El <b>resguardo</b> del disco y el <b>cuchillo divisor</b> deben estar puestos. El cuchillo divisor evita que la madera apriete el disco y salga disparada. Nunca se sacan porque molestan, ni para un corte especial. Si faltan o están dañados, la sierra <b>no se usa</b> y se avisa a la jefatura.","k":"Sin resguardo ni cuchillo divisor, no se corta."},{"s":"push","t":"Empujador y guía","x":"Usa siempre la <b>guía paralela</b> y un <b>empujador</b> cuando tu mano quedaría a menos de 15 centímetros del disco: piezas chicas, listones angostos y el final de cada corte. Termina de empujar con el empujador hasta que la pieza pase el disco. El disco se regula para que sobresalga solo unos milímetros sobre la pieza.","k":"Tus manos nunca pasan cerca de la línea del disco."},{"s":"pz_epp_respirador","t":"EPP en la sierra","x":"<ul><li><b>Lentes</b> o careta facial, por las astillas.</li><li><b>Fonos</b>: la sierra supera los 85 dB(A).</li><li><b>Respirador</b> con filtro para partículas: el polvo de madera, MDF y terciado daña el pulmón y es cancerígeno.</li><li>Casco y zapatos de seguridad.</li></ul>Nada de guantes holgados cerca del disco."},{"s":"maq_suelto","t":"Nada suelto","x":"Mangas sueltas, guantes holgados, bufandas, cadenas, anillos o pelo largo suelto pueden <b>engancharse</b> en el disco y arrastrar tu mano en una fracción de segundo. Ropa ajustada, mangas recogidas, pelo amarrado y sin joyas. Trabajar despacio no evita el enganche. Los guantes se usan para manipular tablas con la sierra detenida, no al cortar."},{"s":"maq_q_atasco","t":"Si se traba","x":"Si la pieza se traba en el disco, <b>apaga</b> la sierra y <b>espera que el disco se detenga por completo</b>. Recién entonces retira la pieza. Nunca la tires hacia atrás ni la empujes con la máquina andando: puede salir disparada o arrastrar tu mano. Si se traba seguido, revisa el disco y avisa."},{"s":"maq_loto","t":"Mantención y cambio de disco","x":"Para cambiar el disco, regularlo o repararlo, la sierra debe estar <b>desconectada</b>; apagarla del interruptor no basta. Si la interviene otra persona, se <b>bloquea con candado y tarjeta</b> de NO OPERAR. El disco nuevo debe ser el indicado para la máquina, sin dientes rotos ni trizaduras."},{"s":"maq_limpiar","t":"Limpieza de la mesa","x":"Nunca retires despuntes ni aserrín junto al disco <b>con la mano</b>, con un listón ni soplando, con la sierra andando. Detén la sierra, <b>espera que el disco pare</b> y usa una escobilla o aspiradora. Si vas a meter las manos cerca del disco, la sierra debe estar desconectada."},{"s":"pz_orden_ok","t":"Entorno ordenado","x":"Alrededor de la sierra: piso limpio de despuntes y aserrín para no resbalar, buena luz, la sierra estable y nivelada, y la extensión colgada o fuera del paso. Las piezas largas se apoyan en caballetes o con ayuda de un compañero ubicado a un costado, nunca en la línea de corte."}],"quiz":[{"s":"pz_sierra_mal","v":[{"q":"Un carpintero corta así un listón. ¿Qué condición insegura ves?","o":["Disco sin resguardo y la mano cerca del disco","Solo le faltan los fonos, el resto está bien","La pieza es muy larga para esta sierra","Debería cortar con guantes gruesos de cuero"],"w":"Sin resguardo y con la mano cerca, cualquier desliz es una amputación."},{"q":"¿Para qué sirve el cuchillo divisor de la sierra de banco?","o":["Evita que la madera apriete el disco y salga disparada","Sirve para medir el ancho de la tabla","Permite cortar más rápido piezas gruesas","Reemplaza al resguardo cuando este molesta"],"w":"Es una protección contra el rebote."},{"q":"Si el resguardo molesta para un corte especial, se puede sacar mientras se corta con cuidado.","vf":false,"w":"Falso. Sin protección no se corta."}]},{"s":"push","v":[{"q":"Debes cortar un taco de 10 centímetros. ¿Cómo lo empujas?","o":["Con un empujador, con las manos lejos del disco","Con los dedos, despacio y con cuidado","Con guantes gruesos para proteger los dedos","Con la palma abierta sobre la pieza"],"w":"Con piezas chicas la mano quedaría junto al disco."},{"q":"¿Cuándo debes usar el empujador?","o":["Cuando tu mano quedaría a menos de 15 cm del disco","Solo cuando la madera está húmeda o resbalosa","Solo al cortar planchas grandes de terciado","Solo si el disco no tiene el resguardo puesto"],"w":"El empujador mantiene la mano fuera de la zona de peligro."},{"q":"Al final de un corte largo, cuando la pieza ya casi pasa el disco:","o":["Termino de empujar con el empujador","Empujo con el pulgar por sobre el disco","Tiro la pieza desde el otro lado del disco","Suelto la pieza y dejo que salga sola"],"w":"El final del corte es cuando la mano queda más cerca del disco."}]},{"s":"maq_q_atasco","v":[{"q":"La tabla se trabó en el disco. ¿Qué haces?","o":["Apago, espero que el disco pare y la retiro","La tiro hacia atrás con fuerza","La empujo con el empujador para que pase","La golpeo suave con un taco de madera"],"w":"Nunca se retira con la máquina andando."},{"q":"¿Por qué no se retira una pieza trabada con el disco girando?","o":["Puede salir disparada o arrastrar la mano","Se gasta el disco más rápido","Se marca la madera y queda mal cortada","Se calienta el motor de la sierra"],"w":"El disco en movimiento lanza la pieza o atrapa la mano."},{"q":"Si una pieza se traba, hay que apagar la sierra y esperar que el disco se detenga por completo antes de retirarla.","vf":true,"w":"Verdadero. Así no hay rebote ni atrapamiento."}]},{"s":"maq_loto","v":[{"q":"Para cambiar el disco de la sierra de banco, debe estar:","o":["Desconectada de la energía","Apagada del interruptor solamente","Con el disco girando lento","Encendida, con el resguardo levantado"],"w":"Desconectada no puede arrancar por accidente."},{"q":"Un mecánico va a reparar la sierra. ¿Qué corresponde?","o":["Desconectar, bloquear con candado y poner tarjeta","Apagarla y avisar de palabra a los demás","Dejarla enchufada para probarla después","Poner un cartón sobre el interruptor"],"w":"El candado y la tarjeta impiden que otro la encienda."},{"q":"Antes de montar un disco nuevo, se revisa que:","o":["No tenga dientes rotos ni trizaduras","Sea del color de la marca de la sierra","Sea nuevo, aunque sea de otro diámetro","Tenga más dientes que el anterior"],"w":"Un disco dañado puede romperse a alta velocidad."}]},{"s":"maq_suelto","v":[{"q":"Vas a operar la sierra. ¿Qué debes sacarte o ajustar?","o":["Mangas, cadenas, anillos y pelo largo amarrado","Solo el reloj, lo demás no se engancha","Solo los guantes, la ropa da lo mismo","Nada, si mantengo distancia del disco"],"w":"Todo lo que cuelga se puede enganchar."},{"q":"¿Por qué no se usan guantes holgados cerca del disco?","o":["El disco puede engancharlos y arrastrar la mano","Se ensucian y se llenan de aserrín","Hacen perder precisión al medir y marcar","Se gastan muy rápido con la madera áspera"],"w":"El guante enganchado lleva la mano al disco."},{"q":"Las mangas sueltas no son un riesgo en la sierra si trabajas despacio.","vf":false,"w":"Falso. El enganche ocurre en una fracción de segundo."}]},{"s":"pz_epp_respirador","v":[{"q":"¿Qué EPP usas en la sierra de banco, además de casco y zapatos?","o":["Lentes o careta, fonos y respirador","Fonos y guantes de cuero holgados","Lentes y mascarilla de tela","Solo fonos, el ruido es el mayor riesgo"],"w":"Hay astillas, ruido y polvo de madera."},{"q":"¿Por qué se usa respirador al cortar madera, MDF o terciado?","o":["El polvo de madera daña el pulmón y es cancerígeno","El aserrín tiene un olor que irrita la nariz","La madera suelta gases tóxicos al cortarla","Así no se ensucia la cara con aserrín"],"w":"El polvo fino de madera llega al pulmón y causa cáncer nasal."},{"q":"¿Por qué se usan fonos en la sierra de banco?","o":["Porque su ruido supera los 85 dB(A)","Para que no distraigan los compañeros","Porque el aserrín entra por los oídos","Solo si se trabaja más de 8 horas"],"w":"Sobre 85 dB(A) el ruido daña el oído."}]},{"s":"maq_limpiar","v":[{"q":"Se acumulan despuntes junto al disco. ¿Cómo los retiras?","o":["Detengo la sierra, espero que pare y uso escobilla","Los saco con la mano con cuidado, con la sierra andando","Los soplo mientras el disco gira","Los empujo con un listón con la sierra andando"],"w":"Con el disco girando, cualquier contacto es un corte grave."},{"q":"¿Cuándo se puede limpiar el aserrín de la mesa de la sierra?","o":["Con la sierra detenida y el disco quieto","Con el disco girando lento al final del corte","Mientras otro compañero corta","Con el disco bajado, aunque esté andando"],"w":"Solo con el disco detenido."},{"q":"El aserrín y los despuntes junto al disco se retiran solo con la sierra detenida, nunca con la mano.","vf":true,"w":"Verdadero. Se usa escobilla o aspiradora con el disco quieto."}]},{"s":"pz_sierra_ok","v":[{"q":"¿Dónde se ubica el operador al cortar en la sierra de banco?","o":["A un costado de la línea del disco","Justo detrás de la pieza, alineado con el disco","Frente al disco, al otro lado de la mesa","Donde quede cómodo, el resguardo lo protege"],"w":"Si la pieza rebota, sale por la línea del disco."},{"q":"Cuando la sierra rebota, ¿hacia dónde sale disparada la pieza?","o":["Hacia el operador, por la línea del disco","Hacia el suelo, bajo la mesa","Hacia arriba, sobre el resguardo","Hacia el lado de la guía paralela"],"w":"Por eso nadie se para en la línea de corte."},{"q":"Nadie debe pararse en la línea de corte de la sierra porque:","o":["Las piezas pueden salir disparadas en esa dirección","Le tapa la luz al operador","Puede pisar la extensión de la sierra","Distrae al operador con la conversación"],"w":"Es la trayectoria del rebote."}]}]},{"id":"polvo","sec":"obra","title":"Polvo en obra: sílice, cemento y madera","thumb":"pz_polvo_agua","learn":[{"s":"pz_polvo_corte","t":"El polvo que no se ve","x":"Al cortar, picar, perforar o pulir <b>hormigón, ladrillo, cerámica, piedra o fibrocemento</b> se libera <b>sílice cristalina</b>. Las partículas más peligrosas son tan finas que <b>no se ven</b> y quedan horas en el aire. Que no veas polvo no significa que no lo estés respirando. Las galleteras y el esmeril en seco son las fuentes más fuertes."},{"s":"polvo_que","t":"Silicosis","x":"Respirar sílice por años causa <b>silicosis</b>: el pulmón se llena de cicatrices, se endurece y cuesta cada vez más respirar. <b>No tiene cura</b> y sigue avanzando aunque dejes de exponerte. La sílice también aumenta el riesgo de <b>cáncer pulmonar</b> y tuberculosis. Por eso se previene desde el primer día.","k":"La silicosis no tiene cura: protégete desde el primer corte."},{"s":"polvo_cancer","t":"Polvo de madera","x":"Cortar, lijar o rebajar madera, <b>terciado, MDF u OSB</b> levanta polvo fino que irrita ojos y nariz, causa asma y es <b>cancerígeno</b>: puede producir cáncer de nariz y senos paranasales. Que sea natural no lo hace inofensivo. Corta con aspiración cuando la herramienta la tenga y usa respirador con filtro para partículas."},{"s":"pz_polvo_agua","t":"Controla en la fuente","x":"Lo más eficaz es que el polvo no salga: cortar <b>con agua</b> (vía húmeda) o con <b>aspiración</b> conectada a la herramienta, y mantenerla encendida mientras cortas. Trabajar al aire libre o con ventilación ayuda. El respirador va <b>además</b> de estas medidas, no en reemplazo. Ubícate de modo que el polvo no vaya hacia ti ni hacia tus compañeros."},{"s":"polvo_resp","t":"Respirador correcto","x":"Usa <b>respirador con filtro para partículas P2 o P100</b>, certificado. La mascarilla de tela o la quirúrgica <b>no filtran</b> el polvo fino, aunque uses dos. El filtro de partículas no sirve para vapores de solventes. Si cuesta respirar, o el filtro está sucio, mojado o dañado, <b>cámbialo</b>. Guárdalo limpio y seco, en una bolsa o caja cerrada."},{"s":"polvo_sello","t":"Ajuste y sello","x":"El respirador debe <b>sellar</b> contra la cara: ajusta los elásticos y moldea la pieza nasal. Para probarlo, tapa el filtro con la mano e inspira: el respirador debe <b>hundirse levemente</b> sin que entre aire por los bordes. La <b>barba</b> impide un buen sello: el polvo entra por los pelos, aunque el filtro sea P100.","k":"Sin sello, el polvo entra."},{"s":"polvo_limpia","t":"Limpieza sin levantar polvo","x":"<b>Nunca soples</b> el polvo con aire comprimido ni barras en seco: pones el polvo fino de vuelta en el aire. <b>Humedece</b> antes de barrer o usa <b>aspiradora</b>. Lo mismo con la ropa: no la limpies con aire comprimido; aspírala o sacúdela lejos de los demás."},{"s":"polvo_higiene","t":"Higiene","x":"Lávate <b>manos y cara</b> antes de comer, beber o fumar. No comas ni fumes en el área de corte: come en el lugar habilitado o donde indique la jefatura. Sacude la ropa de trabajo lejos de los demás y no la lleves con polvo a tu casa, para no exponer a tu familia."},{"s":"polvo_sintomas","t":"Vigilancia: PLANESI","x":"Si estás expuesto a sílice, el protocolo <b>PLANESI</b> del MINSAL exige evaluar el ambiente y hacer <b>vigilancia de salud</b>: la ACHS te puede citar a exámenes, como radiografía de tórax. <b>Asiste</b>: detectar a tiempo permite cambiarte de tarea antes de que el daño avance. Tos persistente o falta de aire: avisa y consulta."}],"quiz":[{"s":"pz_polvo_corte","v":[{"q":"¿Qué trabajo libera polvo de sílice cristalina?","o":["Cortar cerámica o ladrillo en seco con galletera","Pintar un muro con rodillo y látex","Cortar yeso cartón con cuchillo cartonero","Amarrar fierros con alambre"],"w":"Hormigón, ladrillo, cerámica y piedra contienen sílice."},{"q":"¿Cuál de estos materiales contiene sílice?","o":["Hormigón, ladrillo, cerámica y piedra","Madera de pino y terciado","Yeso cartón y pintura látex","Fierro de construcción y alambre"],"w":"Al cortarlos o picarlos se libera sílice cristalina."},{"q":"Si no se ve polvo en el aire, no hay sílice que respirar.","vf":false,"w":"Falso. Las partículas más peligrosas son invisibles."}]},{"s":"polvo_resp","v":[{"q":"¿Qué protección respiratoria sirve para el polvo fino de sílice?","o":["Respirador con filtro P2 o P100 bien ajustado","Mascarilla quirúrgica nueva cada día","Doble mascarilla de tela lavable","Un pañuelo húmedo bien amarrado"],"w":"Solo un filtro para partículas retiene el polvo fino."},{"q":"Un compañero corta ladrillo con mascarilla quirúrgica. ¿Qué le dices?","o":["Que no filtra el polvo fino: debe usar respirador con filtro","Que está bien si la cambia a mitad de jornada","Que está bien si corta al aire libre","Que está bien si además usa lentes"],"w":"La mascarilla quirúrgica no retiene el polvo fino."},{"q":"Un respirador con filtro para partículas P2 o P100 sirve para:","o":["Retener el polvo fino antes de que llegue al pulmón","Proteger de los vapores de solventes","Proteger de la falta de oxígeno en recintos cerrados","Reemplazar el corte con agua o aspiración"],"w":"Es para partículas; no sirve para vapores y no reemplaza el control en la fuente."}]},{"s":"pz_polvo_agua","v":[{"q":"¿Cuál es la forma más eficaz de reducir el polvo al cortar hormigón?","o":["Cortar con agua o con aspiración en la herramienta","Cortar más rápido para terminar antes","Usar un disco de mayor diámetro","Cortar en un recinto cerrado para que no se esparza"],"w":"Lo mejor es que el polvo no salga."},{"q":"Hay que picar un muro. ¿Qué medida va primero, antes del respirador?","o":["Humedecer o usar aspiración en la fuente","Usar doble mascarilla de tela","Pedir a los demás que se tapen la cara","Cerrar puertas y ventanas del recinto"],"w":"El control en la fuente va primero; el respirador se suma."},{"q":"Cortar con agua o con aspiración conectada a la herramienta reduce el polvo más que usar solo respirador.","vf":true,"w":"Verdadero. El control en la fuente es lo más eficaz."}]},{"s":"polvo_limpia","v":[{"q":"Terminas de cortar cerámica y el piso queda con polvo. ¿Cómo limpias?","o":["Humedezco y barro, o aspiro","Barro en seco con escoba","Lo soplo con aire comprimido","Lo sacudo con un trapo seco"],"w":"Humedecer o aspirar no levanta el polvo."},{"q":"Tu ropa quedó llena de polvo de hormigón. ¿Cómo la limpias?","o":["La aspiro o la sacudo lejos de los demás","Con aire comprimido, que es lo más rápido","Sacudiéndola en el lugar de colación","Golpeándola con las manos junto a los compañeros"],"w":"El aire comprimido y sacudir cerca de otros ponen el polvo en el aire."},{"q":"¿Por qué no se usa aire comprimido para limpiar el polvo?","o":["Porque devuelve el polvo fino al aire que respiras","Porque gasta mucho el compresor de la obra","Porque moja la superficie con aceite","Porque deja el piso resbaladizo y suelto"],"w":"Soplar convierte el polvo del suelo en polvo respirable."}]},{"s":"polvo_que","v":[{"q":"¿Qué es la silicosis?","o":["Endurecimiento del pulmón por respirar sílice, sin cura","Una alergia de la piel al cemento, que se cura","Una infección pulmonar que se trata con antibióticos","Una irritación de ojos que pasa en días"],"w":"Es una enfermedad profesional irreversible."},{"q":"La silicosis aparece por lo general:","o":["Después de años de exposición, y no tiene cura","El mismo día de la exposición, y se cura sola","Solo en mineros, nunca en la construcción","Solo en personas que fuman"],"w":"Avanza en silencio por años; por eso se previene."},{"q":"Además de silicosis, respirar sílice aumenta el riesgo de:","o":["Cáncer pulmonar","Pérdida de audición","Dermatitis en las manos","Lumbago"],"w":"La sílice cristalina es cancerígena para el pulmón."}]},{"s":"polvo_cancer","v":[{"q":"¿Qué daño puede causar el polvo de MDF o terciado?","o":["Es cancerígeno: puede causar cáncer de nariz","Solo ensucia la ropa, no es dañino","Solo irrita la piel, no afecta la respiración","Solo es peligroso el de maderas tratadas"],"w":"El polvo de madera es cancerígeno para nariz y senos paranasales."},{"q":"Cortas placas OSB y MDF toda la mañana. ¿Cómo te proteges del polvo?","o":["Con aspiración y respirador con filtro bien ajustado","Con mascarilla de tela, porque el aserrín es grueso","Solo con lentes, porque el aserrín no se respira","Solo abriendo una ventana cercana"],"w":"El polvo fino de madera llega al pulmón y es cancerígeno."},{"q":"El polvo de madera no es peligroso porque es un material natural.","vf":false,"w":"Falso. Causa asma y es cancerígeno."}]},{"s":"polvo_sello","v":[{"q":"Te pones el respirador. ¿Cómo compruebas que sella?","o":["Tapo el filtro, inspiro y debe hundirse sin fugas","Me miro y si se ve centrado, está listo","Si no siento olor a cemento, está sellando","Aprieto los elásticos al máximo y listo"],"w":"La prueba de sello muestra si entra aire por los bordes."},{"q":"Un compañero tiene barba. ¿Qué pasa con su respirador de media cara?","o":["No sella y entra polvo por los bordes","Sella mejor, porque la barba ayuda a filtrar","Sella igual si aprieta más los elásticos","Sella igual si usa filtro P100"],"w":"El filtro no sirve si el aire entra por el borde."},{"q":"La pieza nasal y los elásticos del respirador se ajustan para:","o":["Que selle contra la cara y no entre polvo","Que no se caiga al agacharse","Que sea cómodo, aunque no selle","Que el filtro dure más tiempo"],"w":"Sin sello, el polvo entra sin pasar por el filtro."}]},{"s":"polvo_cambio","v":[{"q":"Cuesta mucho respirar con tu respirador. ¿Qué haces?","o":["Cambio el filtro o el respirador","Me lo saco y sigo sin él","Lo lavo con agua y sigo usándolo","Lo limpio con aire comprimido"],"w":"Un filtro saturado se cambia."},{"q":"¿Cómo guardas el respirador al terminar la jornada?","o":["Limpio y seco, en una bolsa o caja cerrada","Colgado al cuello para el día siguiente","En el bolsillo del pantalón de trabajo","Sobre la mesa de corte, a mano"],"w":"Guardado al aire libre se llena de polvo por dentro."},{"q":"Un filtro sucio, mojado o dañado debe cambiarse aunque no se haya cumplido su tiempo de uso.","vf":true,"w":"Verdadero. Un filtro en mal estado no protege."}]}]},{"id":"ruido","sec":"obra","title":"Ruido y protección auditiva en obra","thumb":"pz_epp_fonos","mins":5,"learn":[{"s":"noise","t":"El ruido daña sin doler","x":"El ruido alto, día tras día, destruye de a poco las <b>células del oído interno</b>, que no se regeneran. No duele y no se nota, hasta que ya no entiendes las conversaciones. <b>La sordera por ruido es permanente</b>: no se cura con gotas ni con descanso, y el oído no se acostumbra al ruido.","k":"Lo que se pierde por ruido, no se recupera."},{"s":"ruido_fuentes","t":"Fuentes de ruido en obra","x":"Sierra circular, esmeril, galletera, rotomartillo, martillo demoledor, vibrador de hormigón, compresor, betonera y maquinaria pesada. El esmeril y el demoledor pueden superar los <b>100 dB(A)</b>. El ruido también afecta a quienes trabajan cerca, aunque no operen la máquina: si trabajas cerca, también usas protector. Una máquina con el silenciador dañado hace más ruido: avisa."},{"s":"ruido_limite","t":"¿Cuánto es demasiado?","x":"El DS 594 fija <b>85 dB(A)</b> para 8 horas. Por cada <b>3 dB(A) más, la mitad del tiempo</b>: 88 dB(A), 4 horas; 91 dB(A), 2 horas; 94 dB(A), 1 hora. A 100 dB(A), solo 15 minutos sin protección. Donde hay letrero de zona de ruido, el protector es <b>obligatorio todo el tiempo</b>."},{"s":"ruido_metro","t":"La prueba del metro","x":"Si no hay medición a mano: si para hablar con alguien a <b>1 metro</b> tienes que gritar, el ruido probablemente supera el límite y debes usar protector auditivo. Que el ruido no te moleste no significa que no te dañe. Si notas un sector muy ruidoso sin letrero de zona de ruido, avisa a tu jefatura."},{"s":"muffs","t":"Fonos","x":"Los <b>fonos</b> deben cubrir la oreja completa y sellar contra la cabeza: sin pelo, gorro de lana ni patillas gruesas de lentes entre medio. Revisa que las almohadillas no estén rotas ni duras y que el arco apriete. En obra se usan fonos para casco, acoplados al casco, que se bajan sobre las orejas."},{"s":"plugs","t":"Tapones","x":"Para un tapón de espuma: con <b>manos limpias</b>, enróllalo hasta dejarlo delgado, <b>tira la oreja hacia arriba y atrás</b>, insértalo y sostenlo unos 30 segundos mientras se expande. Debe quedar dentro del oído, no asomado. Mal puesto protege muy poco. Los desechables se cambian cuando están sucios."},{"s":"ruido_siempre","t":"Todo el tiempo de exposición","x":"Sacarte los fonos <b>unos minutos</b> mientras hay ruido baja mucho la protección de toda la jornada. Úsalos <b>todo el tiempo</b> que dure la exposición, también mientras otros trabajan cerca. Para conversar, aléjate del ruido en vez de sacarte el protector. Si tu protector se pierde o se daña, pide otro de inmediato: el EPP es gratuito.","k":"Un ratito sin protector también daña."},{"s":"ruido_zumbido","t":"Señales de alerta","x":"Zumbido al final del día, oídos tapados, tener que subir el volumen de la tele o no entender conversaciones con ruido de fondo son <b>señales de daño</b>. Avisa a tu jefatura y consulta: el zumbido es una alarma, no algo normal del oficio. La música fuerte con audífonos fuera del trabajo también suma daño."},{"s":"ruido_prexor","t":"PREXOR","x":"El protocolo <b>PREXOR</b> del MINSAL fija un <b>nivel de acción de 82 dB(A)</b>: desde ahí se evalúa el puesto y se vigila la salud de los expuestos. La ACHS hace <b>audiometrías</b> periódicas para detectar a tiempo el daño. Asiste siempre a tu audiometría, aunque sientas que escuchas bien."}],"quiz":[{"s":"ruido_limite","v":[{"q":"¿Cuál es el límite de ruido para una jornada de 8 horas sin protección?","o":["85 dB(A)","82 dB(A)","90 dB(A)","100 dB(A)"],"w":"El DS 594 fija 85 dB(A) para 8 horas."},{"q":"Un sonómetro marca 85 dB(A) junto a la betonera. ¿Cuánto tiempo puedes estar sin protección?","o":["Hasta 8 horas","Hasta 4 horas","Hasta 2 horas","Hasta 12 horas"],"w":"85 dB(A) es el límite para una jornada de 8 horas."},{"q":"¿Qué indica un letrero de zona de ruido con protector obligatorio?","o":["Que ahí se supera el límite y el protector va siempre","Que el protector se usa solo si el ruido molesta","Que solo el operador de la máquina usa protector","Que el protector se usa después de 8 horas"],"w":"En la zona señalizada, el protector es obligatorio todo el tiempo."}]},{"s":"muffsBad","v":[{"q":"Este compañero trabaja junto al demoledor con los fonos así. ¿Qué está mal?","o":["Los fonos deben cubrir las orejas completas","Debería usar tapones además de los fonos","Los fonos solo protegen si son para casco","No está mal si el ruido no le molesta"],"w":"Fuera de la oreja, el fono no protege nada."},{"q":"¿Cómo deben quedar los fonos para proteger?","o":["Cubriendo toda la oreja y sellando, sin nada entremedio","Apoyados sobre la parte de arriba de la oreja","Sobre el gorro de lana, para que no aprieten","Algo sueltos, para escuchar a los compañeros"],"w":"Cualquier abertura deja pasar el ruido."},{"q":"Los fonos protegen igual aunque los uses sobre un gorro de lana o con el pelo entremedio.","vf":false,"w":"Falso. Lo que queda entre el fono y la cabeza rompe el sello."}]},{"s":"ruido_cilios","v":[{"q":"¿Qué pasa con la audición dañada por ruido?","o":["No se recupera: la pérdida es permanente","Se recupera tras unas semanas sin ruido","Se recupera con gotas y tratamiento","Se recupera si usas protector desde ahora"],"w":"Las células del oído dañadas no se regeneran."},{"q":"¿Por qué el ruido es engañoso?","o":["Daña de a poco y sin dolor hasta que ya no escuchas bien","Duele de inmediato, así que siempre se nota","Solo daña si es un ruido muy agudo","Solo daña a personas mayores"],"w":"No duele, por eso se subestima."},{"q":"La sordera por ruido se produce porque:","o":["Se dañan células del oído interno que no se regeneran","El polvo tapa el oído con cera","Se rompe el tímpano en cada exposición","El oído se inflama y luego se desinflama"],"w":"Es un daño interno y permanente."}]},{"s":"ruido_metro","v":[{"q":"Para hablar con un compañero a 1 metro tienes que gritar. ¿Qué indica?","o":["Que el ruido probablemente supera el límite: uso protector","Que el compañero escucha mal, no es el ruido","Que basta con alejarse medio metro","Que es un ruido normal en una obra"],"w":"Es la prueba del metro."},{"q":"No hay medición de ruido a mano. ¿Cómo sabes si necesitas protector auditivo?","o":["Si debo gritar para hablar a 1 metro","Si el ruido me duele en los oídos","Si llevo más de 8 horas en la obra","Si el supervisor usa protector"],"w":"Gritar a 1 metro indica ruido excesivo."},{"q":"¿Qué es la prueba del metro?","o":["Si a 1 metro debes gritar, el ruido es excesivo","Mantener la máquina a 1 metro de distancia","Usar protector solo a menos de 1 metro de la máquina","Hablar a 1 metro para probar los fonos"],"w":"Sirve para reconocer ruido peligroso sin instrumentos."}]},{"s":"ruido_3db","v":[{"q":"El límite es 85 dB(A) en 8 horas. ¿Cuánto tiempo sin protección permite 88 dB(A)?","o":["4 horas","6 horas","8 horas","2 horas"],"w":"3 dB(A) más, la mitad del tiempo."},{"q":"Por cada 3 dB(A) más de ruido, el tiempo permitido:","o":["Se reduce a la mitad","Se reduce en una hora","Se duplica","Se reduce en un tercio"],"w":"Así lo establece el DS 594."},{"q":"Con 91 dB(A), el tiempo máximo sin protección es de 2 horas.","vf":true,"w":"Verdadero. 85 son 8 horas, 88 son 4 y 91 son 2."}]},{"s":"plugs","v":[{"q":"¿Cómo se coloca un tapón de espuma?","o":["Lo enrollo, tiro la oreja hacia arriba y atrás, lo inserto y sostengo","Lo meto tal como viene, solo hasta la entrada","Lo mojo para que entre más fácil y lo empujo","Lo dejo en la entrada del oído para que no moleste"],"w":"Bien insertado, se expande y sella el conducto."},{"q":"Tu tapón queda asomado en la entrada del oído. ¿Qué pasa?","o":["Protege muy poco: debe ir bien insertado","Protege igual, lo importante es tenerlo","Protege más, porque tapa la oreja completa","Protege igual si lo usas toda la jornada"],"w":"Mal puesto, casi no protege."},{"q":"¿Cómo deben estar tus manos al ponerte tapones?","o":["Limpias, para no llevar suciedad al oído","Con guantes de trabajo puestos","Con cemento, si es solo un momento","Mojadas, para que el tapón se deslice"],"w":"La suciedad en el tapón irrita e infecta el oído."}]},{"s":"ruido_siempre","v":[{"q":"Trabajas con el demoledor. ¿Cuándo usas los fonos?","o":["Todo el tiempo que dure la exposición al ruido","Solo mientras el demoledor está golpeando","Solo cuando el ruido se vuelve molesto","Solo la primera hora, luego el oído se acostumbra"],"w":"Cualquier rato sin protector suma daño."},{"q":"Te sacas los fonos un ratito para conversar junto a la galletera funcionando. ¿Qué pasa?","o":["Baja mucho la protección de toda la jornada","No influye: cuenta el promedio del día","No influye si después los usas más rato","No influye si la galletera es nueva"],"w":"Para conversar, aléjate del ruido."},{"q":"Si el oído se acostumbra al ruido, ya no es necesario usar protector.","vf":false,"w":"Falso. El oído no se acostumbra: se va dañando."}]},{"s":"ruido_prexor","v":[{"q":"¿Para qué sirven las audiometrías del protocolo PREXOR?","o":["Para detectar a tiempo el daño auditivo","Para medir el ruido de las máquinas","Para elegir el tamaño de los fonos","Para revisar si el oído tiene cera"],"w":"Es vigilancia de la salud auditiva."},{"q":"La ACHS te cita a audiometría y sientes que escuchas bien. ¿Qué haces?","o":["Asisto: detectar a tiempo evita que empeore","No voy, porque si escucho bien no hace falta","Voy solo si me duele el oído o lo siento tapado","Voy solo si ya tengo zumbido al final del día"],"w":"El daño empieza sin que lo notes."},{"q":"Según PREXOR, ¿desde qué nivel de ruido se evalúa y vigila a los trabajadores?","o":["82 dB(A)","85 dB(A)","75 dB(A)","90 dB(A)"],"w":"82 dB(A) es el nivel de acción del protocolo."}]}]},{"id":"quimicos","sec":"obra","title":"Cemento, aditivos, solventes y otros químicos de obra","thumb":"quim_cc_cemento","mins":5,"learn":[{"s":"quim_cc_intro","t":"Químicos en la obra","x":"Cemento, morteros, aditivos, desmoldantes, impermeabilizantes, ácido muriático, pinturas, diluyentes, adhesivos, combustibles y gas. Pueden <b>quemar la piel, dañar los ojos, intoxicar o incendiarse</b>. Que sean de uso diario no los hace inofensivos: antes de usar uno nuevo, infórmate de sus peligros. Los usa solo quien fue instruido, con el EPP que indica su hoja de seguridad."},{"s":"quim_cc_cemento","t":"Cemento y hormigón fresco","x":"El cemento húmedo es <b>alcalino</b>: quema la piel aunque al principio no duela, y causa dermatitis. Usa <b>guantes impermeables</b> (nitrilo), botas de goma, ropa que cubra y <b>lentes</b>. Si entra hormigón en la bota o el guante, sácalo y <b>lava con abundante agua</b> de inmediato. Cámbiate la ropa empapada.","k":"Cemento en la piel: lava de inmediato."},{"s":"quimicos_label","t":"Etiqueta y pictogramas","x":"Antes de usar un producto, lee la etiqueta: nombre, <b>pictogramas</b> (rombos de borde rojo), palabra de advertencia e indicaciones. La llama indica <b>inflamable</b>; el signo de exclamación, <b>irritante o nocivo</b>; el de la mano y la superficie corroídas, <b>corrosivo</b>. La palabra <b>PELIGRO</b> indica un riesgo más grave que <b>ATENCIÓN</b>."},{"s":"quimicos_hds","t":"Hoja de Datos de Seguridad (HDS)","x":"Todo producto peligroso debe tener su <b>HDS</b> en español y disponible para los trabajadores en la obra (DS 57). Indica sus peligros, qué EPP usar, primeros auxilios, cómo almacenarlo y qué hacer ante derrame o incendio. Si llega un producto nuevo a la obra de {EMP}, pide su HDS a tu jefatura <b>antes de usarlo</b>."},{"s":"quim_cc_solvente","t":"Solventes y pinturas","x":"Sus <b>vapores son inflamables</b>, no se ven y pueden viajar hasta una chispa lejana. Úsalos con <b>ventilación</b>, lejos de soldaduras, esmeriles, estufas y cigarros, con el envase <b>tapado</b> cuando no lo usas. En recintos cerrados usa respirador con filtro para vapores según la HDS: el filtro de polvo P2 no sirve para vapores."},{"s":"ind_quimicos","t":"Nunca mezcles","x":"Nunca mezcles productos si la HDS no lo indica. Por ejemplo, <b>ácido muriático con cloro</b>, al limpiar ladrillo o cerámica, libera un <b>gas tóxico</b> que daña los pulmones, aunque se haga al aire libre. Usa cada producto solo, como dice su etiqueta, y no reutilices baldes con restos de otro químico."},{"s":"quimicos_bottles","t":"Nunca en botellas de bebida","x":"No traspases productos a <b>botellas de bebida</b> ni a envases de alimentos, <b>aunque los rotules</b>: alguien puede tomarlos por error. Si hay que fraccionar, se usa un envase adecuado, <b>rotulado</b> con el nombre del producto y su peligro. Un envase sin etiqueta no se usa: se avisa."},{"s":"quim_cc_alm","t":"Almacenamiento","x":"En bodega ventilada, ordenados, cerrados y etiquetados; los <b>inflamables separados</b>, lejos del calor y del tablero eléctrico, con extintor cerca y prohibido fumar. Los <b>cilindros de gas</b> van de pie, amarrados o encadenados y lejos del calor. No guardes químicos junto a la colación ni a la ropa."},{"s":"quim_cc_derrame","t":"Derrames y contacto","x":"<b>Derrame</b>: aleja a las personas, evita chispas y llamas, contén con material absorbente y <b>avisa</b>. <b>Ojos</b>: lava con agua corriente <b>al menos 15 minutos</b>, sin refregar, con los párpados abiertos. <b>Piel</b>: saca la ropa contaminada y lava con abundante agua. Luego consulta en la ACHS y lleva la etiqueta o la HDS.","k":"Ojo salpicado: lava 15 minutos y consulta."}],"quiz":[{"s":"quim_cc_cemento","v":[{"q":"Al hormigonar, se te mete hormigón fresco dentro de la bota. ¿Qué haces?","o":["Me saco la bota, lavo con abundante agua y aviso","Sigo hasta terminar y me lavo en casa","Lo seco con un trapo y sigo trabajando","Echo agua dentro de la bota y sigo con ella"],"w":"El cemento sigue quemando mientras esté en contacto."},{"q":"¿Por qué el cemento húmedo puede quemar la piel?","o":["Porque es alcalino y daña la piel con el contacto","Porque se calienta mucho al fraguar","Porque contiene ácido muriático","Solo quema si la piel tiene heridas"],"w":"Su alcalinidad produce quemaduras químicas."},{"q":"El cemento húmedo puede causar quemaduras aunque al principio no duela.","vf":true,"w":"Verdadero. La quemadura aparece después, por eso se lava de inmediato."}]},{"s":"quimicos_hds","v":[{"q":"¿Dónde encuentras qué EPP usar y qué hacer ante un derrame de un producto?","o":["En la Hoja de Datos de Seguridad","En la factura de compra","En la guía de despacho del camión","En el letrero de la bodega"],"w":"La HDS reúne toda la información de seguridad del producto."},{"q":"Llega un aditivo nuevo a la obra. ¿Qué debe estar disponible antes de usarlo?","o":["Su HDS, en español y a mano en la obra","Solo el envase original, sin documentos","La garantía del proveedor","La boleta, por si hay que devolverlo"],"w":"Sin HDS no sabes cómo protegerte."},{"q":"Según el DS 57, la HDS de un producto peligroso:","o":["Debe estar disponible para los trabajadores","La guarda solo el proveedor","La necesita solo el bodeguero","Se pide solo si hay un accidente"],"w":"Los trabajadores tienen derecho a conocerla."}]},{"s":"quimicos_bottles","v":[{"q":"Necesitas un poco de diluyente para limpiar brochas. ¿Dónde lo traspasas?","o":["A un envase adecuado rotulado con nombre y peligro","A una botella de bebida limpia y bien tapada","A un tarro de pintura vacío, sin rótulo","A un vaso desechable para usarlo de inmediato"],"w":"Envase adecuado y rotulado, nunca de bebida."},{"q":"¿Por qué nunca se traspasa un químico a una botella de bebida?","o":["Porque alguien puede tomarlo por error","Porque el plástico se ablanda con el sol","Porque se pierde parte del producto","Porque la botella no cierra bien"],"w":"Ha habido intoxicaciones graves por esta confusión."},{"q":"Traspasar un producto a una botella de bebida está permitido si se escribe el nombre con plumón.","vf":false,"w":"Falso. Los envases de bebida o alimentos nunca se usan, aunque se rotulen."}]},{"s":"quim_cc_solvente","v":[{"q":"Un pintor quiere usar diluyente cerca de donde otro suelda. ¿Qué corresponde?","o":["No: los vapores se inflaman, debe alejarse","Sí, si usa poca cantidad","Sí, si el soldador usa careta","Sí, si el envase está a medio metro"],"w":"Los vapores inflamables llegan a la chispa."},{"q":"¿Cómo se usa un solvente en un recinto cerrado?","o":["Con ventilación, envase tapado y respirador para vapores","Con la puerta cerrada para que no salga el olor","Con respirador P2, que sirve para todo","Con el envase abierto para que se evapore"],"w":"El filtro de partículas no detiene vapores."},{"q":"Los vapores de diluyente:","o":["Se inflaman y pueden viajar hasta una chispa lejana","Solo se inflaman si tocan la llama directa","No se inflaman si el envase es metálico","Solo son peligrosos si tienen olor fuerte"],"w":"Son invisibles y se desplazan."}]},{"s":"ind_quimicos","v":[{"q":"Para limpiar ladrillo, un compañero quiere mezclar ácido muriático con cloro. ¿Qué le dices?","o":["Que no: la mezcla libera un gas tóxico","Que sí, así limpia el doble de rápido","Que sí, si lo hace al aire libre","Que sí, si usa guantes y lentes"],"w":"Nunca se mezclan químicos si la HDS no lo indica."},{"q":"¿Se pueden mezclar dos productos de limpieza para hacerlos más fuertes?","o":["No, nunca si la HDS no lo indica","Sí, si son de la misma marca","Sí, si se mezclan en un balde abierto","Sí, si se diluyen en mucha agua"],"w":"Algunas mezclas liberan gases tóxicos."},{"q":"Mezclar cloro con ácido muriático es seguro si se hace al aire libre.","vf":false,"w":"Falso. El gas tóxico se libera igual."}]},{"s":"quimicos_pictos","v":[{"q":"Un envase tiene un rombo de borde rojo con una llama. ¿Qué indica?","o":["Que el producto es inflamable","Que el producto es corrosivo","Que el producto es explosivo","Que el producto es irritante"],"w":"La llama indica inflamable."},{"q":"Un envase tiene un rombo con un signo de exclamación. ¿Qué indica?","o":["Que es irritante o nocivo","Que es explosivo o reactivo","Que es inflamable con el calor","Que es corrosivo para la piel"],"w":"El signo de exclamación indica irritante o nocivo."},{"q":"En la etiqueta, la palabra PELIGRO en vez de ATENCIÓN indica:","o":["Un riesgo más grave","Un riesgo menor","Que el producto está vencido","Que es solo para uso industrial"],"w":"PELIGRO se usa para los peligros más graves."}]},{"s":"quim_cc_alm","v":[{"q":"¿Cómo se guardan los inflamables en la obra?","o":["Separados, ventilados, cerrados y lejos del calor","Junto al tablero eléctrico, que es un lugar seco","En la caseta junto a los equipos de soldar","En cualquier bodega, si están bien tapados"],"w":"Se alejan de toda fuente de calor o chispa."},{"q":"¿Cómo se almacenan los cilindros de gas?","o":["De pie, amarrados y lejos del calor","Acostados, para que no se caigan","Junto a la estufa, para que no se enfríen","Bajo la escalera, donde no estorban"],"w":"Un cilindro que cae o se calienta puede fugar o explotar."},{"q":"Junto a la bodega de inflamables debe haber:","o":["Un extintor y prohibición de fumar","Una estufa para mantener la temperatura","El tablero eléctrico de la faena","Los cilindros de oxígeno de soldar"],"w":"Se previene el fuego y se tiene con qué combatirlo."}]},{"s":"quimicos_eyes","v":[{"q":"Te salpica mortero en un ojo. ¿Qué haces?","o":["Lavo con agua al menos 15 minutos y consulto","Me refriego el ojo hasta sacar el grano","Lavo unos segundos y sigo trabajando","Me pongo gotas y espero que pase"],"w":"Lavado prolongado sin refregar y luego consulta."},{"q":"¿Cuánto tiempo, como mínimo, se lava un ojo salpicado con un químico?","o":["15 minutos","1 minuto","5 minutos","Hasta que deje de arder"],"w":"El químico sigue dañando aunque ya no arda."},{"q":"Si te salpica un químico en el ojo, debes lavarlo con agua corriente al menos 15 minutos, sin refregar, y luego consultar.","vf":true,"w":"Verdadero. Después consulta en la ACHS con la etiqueta o la HDS."}]}]},{"id":"tmert","sec":"obra","title":"Trabajo repetitivo y posturas forzadas (TMERT)","thumb":"tmert_neutro","learn":[{"s":"tmert_intro","t":"¿Qué son los TMERT?","x":"Son lesiones de <b>hombro, codo, muñeca y mano</b> por movimientos repetidos, fuerza y posturas forzadas: tendinitis, epicondilitis o túnel carpiano. En obra afectan a enfierradores, ceramistas, yeseros, pintores, carpinteros y albañiles. Aparecen de a poco y pueden dejarte sin trabajar por meses. Se previenen con buena postura, herramientas adecuadas, pausas y avisando a tiempo."},{"s":"tmert_factores","t":"Los factores","x":"<b>Repetición</b> (el mismo gesto muchas veces), <b>fuerza</b>, <b>posturas</b> forzadas (brazos sobre los hombros, muñeca doblada) y <b>falta de pausas</b>. Juntos multiplican el riesgo; la vibración del rotomartillo y el frío lo aumentan. Por el protocolo <b>TMERT</b> del MINSAL, la empresa debe evaluar las tareas repetitivas y aplicar medidas de control.","k":"Repetición, fuerza, postura y falta de pausas: juntos multiplican el riesgo."},{"s":"tmert_repet","t":"Repetición","x":"Amarrar fierro con alambre, atornillar placas a mano, pintar o cortar con tijera repiten el mismo gesto miles de veces al día. Si además hay <b>fuerza</b> y no hay pausas, el tendón no alcanza a recuperarse. Las herramientas eléctricas, como el atornillador, reducen miles de giros de muñeca."},{"s":"tmert_alto","t":"Brazos sobre los hombros","x":"Instalar cielos, pintar o perforar arriba y acopiar material en altura obligan a tener los brazos sobre los hombros, lo que sobrecarga los hombros. Usa un <b>andamio o plataforma</b> a la altura correcta, o herramientas con <b>alargador</b>, como el rodillo, para trabajar con los brazos más bajos."},{"s":"tmert_neutro","t":"Postura neutra","x":"Trabaja con las <b>manos entre la cintura y los hombros</b>, la <b>muñeca recta</b> y los codos cerca del cuerpo. Ajusta el banco o la pieza a esa altura. En trabajos en el piso, como instalar cerámica, usa <b>rodilleras</b> y cambia de postura seguido. Para girar, mueve los pies en vez de torcer el tronco.","k":"Muñeca recta, codos cerca, manos entre cintura y hombros."},{"s":"tmert_herram","t":"Herramientas adecuadas","x":"Elige herramientas con buen <b>mango</b>, que te permitan mantener la <b>muñeca recta</b>, livianas y en buen estado: una tijera o un serrucho sin filo obligan a hacer más fuerza. Doblar la muñeca mientras haces fuerza es lo que más lesiona. No uses guantes holgados que obliguen a apretar más."},{"s":"tmert_alternar","t":"Alterna tareas","x":"Cambia entre tareas que usan <b>distintos músculos</b>: por ejemplo, un ceramista puede alternar cortar, preparar mezcla e instalar. Mientras unos músculos trabajan, otros descansan. Si llevas mucho rato con el mismo gesto, cambia de tarea o haz una pausa. La jefatura puede organizar rotaciones dentro de la cuadrilla."},{"s":"tmert_pausa","t":"Pausas","x":"Las <b>pausas cortas y frecuentes</b> recuperan mejor que una sola pausa larga al final del día. En la pausa activa, <b>estira</b> manos, muñecas, brazos, hombros y cuello unos minutos. No esperes a sentir dolor para hacer una pausa. Aprovéchala también para cambiar de postura, soltar los hombros e hidratarte."},{"s":"tmert_sintomas","t":"Avisa temprano","x":"Hormigueo, adormecimiento, dolor que te despierta en la noche o pérdida de fuerza en las manos son señales de alerta. <b>Avisa de inmediato</b> a tu jefatura: puede derivarte a la ACHS. Tratado al principio, se recupera mejor; con analgésicos solo tapas el problema. Si la lesión es por el trabajo, su tratamiento lo cubre la Ley 16.744."}],"quiz":[{"s":"tmert_herram","v":[{"q":"¿Qué posición de muñeca protege más al usar una herramienta?","o":["Recta, alineada con el antebrazo","Doblada hacia abajo para hacer más fuerza","Doblada hacia arriba para tener control","Girada hacia afuera, según el trabajo"],"w":"La muñeca recta reduce la carga en tendones."},{"q":"Al atornillar todo el día, tu muñeca queda doblada. ¿Qué ayuda?","o":["Una herramienta cuyo mango deje la muñeca recta","Apretar más fuerte para terminar antes","Usar guantes más gruesos","Cambiar de mano solo al final del día"],"w":"El mango adecuado evita doblar la muñeca."},{"q":"Doblar la muñeca al hacer fuerza ayuda a evitar lesiones.","vf":false,"w":"Falso. Es la combinación que más lesiona."}]},{"s":"tmert_alto","v":[{"q":"Debes instalar planchas de cielo todo el día. ¿Qué es lo mejor?","o":["Usar plataforma o andamio a la altura adecuada","Trabajar con los brazos estirados para avanzar","Subirte a un balde volteado para alcanzar","Turnarte con un compañero solo al final"],"w":"Así bajan los brazos y se protegen los hombros."},{"q":"¿Por qué es dañino trabajar con los brazos sobre los hombros?","o":["Porque sobrecarga los hombros y causa lesiones","Porque cansa las piernas al estar de pie","Porque cae polvo del cielo en la cara","Solo si se levantan más de 25 kilos"],"w":"Los hombros no están hechos para sostener esa postura."},{"q":"Para pintar un cielo, ¿qué reduce el tiempo con los brazos arriba?","o":["Rodillo con alargador o plataforma más alta","Una brocha más pequeña","Pintar más rápido","Pintar siempre con una sola mano"],"w":"El alargador y la plataforma bajan los brazos."}]},{"s":"tmert_sintomas","v":[{"q":"Hace dos semanas sientes hormigueo y dolor nocturno en la mano. ¿Qué haces?","o":["Aviso de inmediato a mi jefatura","Espero a que el dolor sea fuerte para avisar","Tomo analgésicos y sigo igual","Cambio de mano y no digo nada"],"w":"Tratado al principio se recupera mejor."},{"q":"¿Por qué hay que avisar los síntomas al principio?","o":["Porque tratados a tiempo se recuperan mejor","Porque así te dan días libres","Porque después ya no tienen tratamiento","Porque después la ley ya no te cubre"],"w":"Esperar deja que la lesión avance."},{"q":"Hormigueo, dolor nocturno y pérdida de fuerza en las manos son señales que se deben avisar a tiempo.","vf":true,"w":"Verdadero. Son señales de alerta de TMERT."}]},{"s":"tmert_neutro","v":[{"q":"¿Cuál es la postura neutra para trabajar?","o":["Manos entre cintura y hombros, muñeca recta, codos cerca","Manos sobre los hombros y codos abiertos","Espalda inclinada y brazos estirados","Muñeca doblada y codos lejos del cuerpo"],"w":"Es la postura que menos carga los músculos."},{"q":"Al preparar enfierradura en un banco, ¿a qué altura conviene trabajar?","o":["Con las manos entre la cintura y los hombros","Con las manos a la altura de las rodillas","Con las manos sobre la cabeza","A cualquier altura, mientras no duela"],"w":"Se ajusta el banco o la pieza a esa altura."},{"q":"¿Dónde deben ir los codos al trabajar?","o":["Cerca del cuerpo","Abiertos, a la altura de los hombros","Estirados hacia adelante","Apoyados en las rodillas"],"w":"Codos cerca, menos carga en hombros."}]},{"s":"tmert_repet","v":[{"q":"Amarras fierro con alambre toda la mañana con el mismo gesto. ¿Qué factor de riesgo TMERT predomina?","o":["La repetición","El ruido","La exposición al sol","El polvo"],"w":"Es el mismo gesto miles de veces."},{"q":"¿Qué hace más riesgosa una tarea repetitiva?","o":["Repetir el gesto con fuerza y sin pausas","Hacerla con herramientas eléctricas","Hacerla en la mañana","Cambiar de tarea cada cierto tiempo"],"w":"Sin pausa, el tendón no se recupera."},{"q":"¿Por qué atornillar placas a mano todo el día es más riesgoso que hacerlo con atornillador eléctrico?","o":["Porque repites miles de giros de muñeca con fuerza","Porque el eléctrico hace más ruido","Porque el destornillador manual pesa más","Porque el eléctrico se aprende más rápido"],"w":"La herramienta eléctrica elimina la repetición."}]},{"s":"tmert_pausa","v":[{"q":"¿Qué ayuda más a recuperar los músculos durante la jornada?","o":["Pausas cortas y frecuentes con estiramientos","Una sola pausa larga al final del día","Trabajar sin parar y salir antes","Pausas solo cuando aparece el dolor"],"w":"La recuperación debe ser frecuente."},{"q":"En una pausa activa, ¿qué haces?","o":["Estiro manos, brazos, hombros y cuello","Fumo un cigarro para relajarme","Reviso el celular sentado sin moverme","Levanto peso para fortalecerme"],"w":"Los estiramientos recuperan los músculos usados."},{"q":"Es mejor trabajar sin pausas y descansar todo junto al final del día.","vf":false,"w":"Falso. Las pausas cortas y frecuentes recuperan mejor."}]},{"s":"tmert_factores","v":[{"q":"¿Qué combinación aumenta más el riesgo de TMERT?","o":["Repetición, fuerza, postura forzada y falta de pausas","Ruido, polvo, humedad y frío del invierno","Altura, viento, lluvia y barro en la obra","Turnos largos, metas exigentes y presión"],"w":"Son los cuatro factores del protocolo TMERT."},{"q":"Los factores de riesgo TMERT son repetición, fuerza, postura y:","o":["Falta de pausas o recuperación","Ruido sobre 85 dB(A) en la obra","Exposición al sol sin bloqueador","Polvo de sílice en el aire"],"w":"Sin recuperación, el riesgo aumenta."},{"q":"Según el protocolo TMERT del MINSAL, ¿qué debe hacer la empresa con las tareas repetitivas?","o":["Evaluarlas y aplicar medidas de control","Pagar un bono por el esfuerzo","Prohibirlas en toda la obra","Dejar que cada trabajador decida"],"w":"La evaluación permite corregir las tareas de mayor riesgo."}]},{"s":"tmert_alternar","v":[{"q":"¿Cómo ayuda alternar tareas durante la jornada?","o":["Descansan unos músculos mientras trabajan otros","Permite terminar más rápido el trabajo","Evita tener que hacer pausas","Reemplaza a las herramientas eléctricas"],"w":"Variar reparte la carga."},{"q":"Un ceramista corta, prepara mezcla e instala durante el día. ¿Por qué conviene alternar?","o":["Porque usa distintos músculos y reduce la sobrecarga","Porque así se aburre menos durante el día","Porque así no necesita usar sus EPP","Porque así puede saltarse las pausas"],"w":"Cada tarea usa músculos distintos."},{"q":"Llevas dos horas amarrando fierro. Lo recomendable es:","o":["Cambiar a una tarea con otros músculos o hacer pausa","Seguir hasta terminar para no perder el ritmo","Apurarte para terminar antes de colación","Cambiar de mano y seguir con lo mismo"],"w":"El mismo gesto prolongado sobrecarga el tendón."}]}]},{"id":"electrico","sec":"esp","title":"Riesgo eléctrico en obra","thumb":"pz_elec_tablero_ok","mins":5,"learn":[{"s":"pz_elec_tablero_mal","t":"La electricidad no se ve","x":"No tiene olor ni color y no avisa. Una descarga puede causar <b>quemaduras, paro cardíaco</b>, caídas desde altura y la muerte. En obra el riesgo aumenta por el agua, el barro, los cables dañados y los tableros abiertos. Un tablero con la tapa abierta, rota o con cables a la vista <b>no se usa</b>: se avisa."},{"s":"pz_elec_tablero_ok","t":"El tablero de faena","x":"Toda herramienta se conecta a un <b>tablero de faena</b> con <b>protector diferencial</b>, puesta a tierra, tapa cerrada, enchufes industriales y señalización. El diferencial corta la corriente si hay una fuga hacia una persona o a tierra. Si salta seguido con una herramienta, esa herramienta tiene una falla: <b>no la uses, no puentees el diferencial y avisa</b>.","k":"Sin diferencial, no se conecta."},{"s":"pz_elec_autorizado","t":"Solo personal autorizado","x":"Las instalaciones y reparaciones eléctricas las hace <b>personal capacitado y autorizado</b>, con licencia SEC cuando corresponde. Nadie más abre tableros, cambia enchufes, hace puentes ni empalmes, aunque sepa un poco o use guantes. Tampoco se cambian fusibles ni se reponen protecciones por cuenta propia. Si ves una falla, aléjate y avisa."},{"s":"pz_elec_ext_mal","t":"Extensiones y enchufes","x":"Extensiones <b>sin uniones con cinta</b>, sin cables pelados y con enchufes industriales en buen estado. Nunca conectes los cables pelados directo al enchufe, a pelo. Fuera de charcos, barro y del paso de vehículos. Una extensión dañada se saca de uso y se avisa: no se repara en terreno."},{"s":"pz_elec_ext_ok","t":"Cables en altura","x":"Las extensiones van <b>colgadas en altura</b> o protegidas en ductos, nunca tiradas en el barro ni bajo materiales, moldajes o maquinaria. Si cruzan un camino de vehículos, se cuelgan o se protegen para que no las aplasten. Un cable aplastado pierde su aislamiento aunque por fuera se vea bien."},{"s":"pz_elec_bloqueo","t":"Bloqueo antes de intervenir","x":"Antes de trabajar en un circuito: <b>desenergizar</b>, <b>bloquear</b> con candado, poner <b>tarjeta</b> de NO OPERAR y <b>verificar</b> con instrumento que no hay tensión, porque puede haber otra fuente o un error de circuito. Si trabajan varios, <b>cada uno pone su propio candado</b> y solo lo retira quien lo puso."},{"s":"pz_elec_lineas","t":"Líneas eléctricas aéreas","x":"Mantén distancia de las líneas del tendido con <b>escalas metálicas, fierros largos, andamios, grúas y la retro</b>. Los fierros se trasladan horizontales y lejos de la línea. Las máquinas bajo líneas trabajan respetando la distancia del procedimiento y con señalero. No se necesita tocar la línea: la corriente puede saltar si te acercas demasiado."},{"s":"emergencias_luz","t":"Si alguien se electrocuta","x":"<b>No lo toques</b> mientras siga en contacto. Primero <b>corta la energía</b> en el tablero. Si no puedes, sepáralo con algo seco y aislante, como una madera seca, nunca con fierro ni algo mojado. Llama al <b>131</b> y avisa a tu jefatura: es un accidente grave. La atención la entrega la ACHS (1404).","k":"Primero corta la energía; nunca lo toques."}],"quiz":[{"s":"pz_elec_tablero_mal","v":[{"q":"Vas a conectar tu galletera y el tablero de faena está así. ¿Qué haces?","o":["No conecto y aviso para que lo revise un eléctrico","Conecto con cuidado, sin tocar los cables","Cierro la tapa yo mismo y conecto","Conecto si tengo guantes de cuero"],"w":"Un tablero abierto o con cables a la vista no se usa."},{"q":"¿Qué debe tener un tablero de faena seguro?","o":["Diferencial, tierra, tapa cerrada y señalización","Solo un interruptor general a la vista","Enchufes domésticos y tapa abierta para ventilar","Fusibles reforzados con alambre"],"w":"Así protege a quien conecta herramientas."},{"q":"Si el tablero tiene la tapa rota pero funciona, se puede seguir usando mientras nadie toque adentro.","vf":false,"w":"Falso. No se usa y se avisa para que lo repare personal autorizado."}]},{"s":"pz_elec_tablero_ok","v":[{"q":"¿Para qué sirve el protector diferencial?","o":["Corta la corriente si hay una fuga a una persona o a tierra","Sube el voltaje cuando la herramienta lo necesita","Evita que se corte la luz en la obra","Protege solo la herramienta, no a las personas"],"w":"Es la protección contra descargas por fuga."},{"q":"El diferencial salta cada vez que conectas el rotomartillo. ¿Qué haces?","o":["Dejo de usarlo y aviso: tiene una falla","Lo conecto en un enchufe sin diferencial","Mantengo el diferencial subido con cinta","Lo sigo reconectando hasta que funcione"],"w":"El diferencial está detectando una fuga."},{"q":"¿Por qué toda herramienta se conecta a un tablero con diferencial?","o":["Porque corta la corriente si hay una fuga","Porque la herramienta tiene más potencia","Porque se gasta menos electricidad en la obra","Porque la herramienta no se calienta tanto"],"w":"Corta la corriente en una fracción de segundo."}]},{"s":"pz_elec_ext_mal","v":[{"q":"Tu extensión tiene una unión con cinta aislante. ¿Qué haces?","o":["La saco de uso y aviso","La uso si la unión queda lejos del agua","Le pongo más cinta para que quede firme","La uso solo con herramientas pequeñas"],"w":"Una extensión parchada no se usa."},{"q":"Un compañero conecta los cables pelados directo al enchufe, sin clavija. ¿Qué corresponde?","o":["Detenerlo: nunca se conecta a pelo","Ayudarlo a sujetar los cables","Dejarlo si es solo un momento","Dejarlo si usa guantes secos"],"w":"Los cables a la vista dan descarga al menor contacto."},{"q":"¿Dónde no debe quedar nunca una extensión?","o":["En charcos o barro, o donde pasan vehículos","Colgada en altura sobre el paso","Protegida dentro de un ducto","Junto a un muro, fuera del paso"],"w":"Agua y aplastamiento dañan el aislamiento."}]},{"s":"pz_elec_autorizado","v":[{"q":"El tablero quedó sin energía y hay un cable suelto. ¿Quién lo repara?","o":["Un eléctrico capacitado y autorizado","El maestro con más experiencia","Cualquiera con guantes y herramientas aisladas","El capataz, si cortó la energía antes"],"w":"Solo personal autorizado interviene instalaciones."},{"q":"Un compañero quiere puentear el diferencial para que no salte. ¿Qué haces?","o":["Lo detengo y aviso a la jefatura","Lo ayudo si sabe de electricidad","Lo dejo si es solo por hoy","Lo dejo si usa guantes de goma"],"w":"Puentear el diferencial elimina la protección de todos."},{"q":"Solo personal eléctrico capacitado y autorizado puede abrir tableros, hacer empalmes o reparar instalaciones.","vf":true,"w":"Verdadero. Nadie más interviene."}]},{"s":"pz_elec_bloqueo","v":[{"q":"Antes de intervenir un circuito, ¿cuál es la secuencia correcta?","o":["Desenergizar, bloquear, etiquetar y verificar","Etiquetar, trabajar rápido y luego desenergizar","Desenergizar y trabajar sin candado si es rápido","Bloquear y trabajar sin verificar la tensión"],"w":"Cada paso evita una energización inesperada."},{"q":"Tres eléctricos trabajan en el mismo circuito. ¿Cuántos candados se ponen?","o":["Uno por cada trabajador","Uno solo, el del supervisor","Uno solo, el del primero que llegó","Ninguno, si se avisan entre ellos"],"w":"Nadie puede energizar mientras haya alguien trabajando."},{"q":"¿Por qué se verifica que no hay tensión después de bloquear?","o":["Puede haber otra fuente o un error de circuito","Lo pide la tarjeta de bloqueo","Para probar que el candado funciona","Para saber cuánto consume el circuito"],"w":"Se confirma antes de tocar."}]},{"s":"emergencias_luz","v":[{"q":"Un compañero queda pegado a una extensión dañada. ¿Qué haces primero?","o":["Cortar la energía en el tablero","Tomarlo de la ropa y tirarlo","Echarle agua para separarlo","Tomarlo de la mano con guantes de cuero"],"w":"Si lo tocas con energía, te electrocutas tú también."},{"q":"No puedes cortar la energía y tu compañero sigue en contacto con el cable. ¿Qué haces?","o":["Lo separo con una madera seca","Lo separo con un fierro largo","Lo tomo de los pies, lejos del cable","Lo separo con un trapo mojado"],"w":"Solo un material seco y aislante no conduce la corriente."},{"q":"Si alguien sufre una descarga, no debes tocarlo hasta cortar la energía o separarlo con algo seco y aislante.","vf":true,"w":"Verdadero. Luego llama al 131 y avisa."}]},{"s":"pz_elec_lineas","v":[{"q":"Debes trasladar fierros de 6 metros cerca de una línea aérea. ¿Cómo lo haces?","o":["Horizontales y lejos de la línea","Verticales, para ocupar menos espacio","Rápido, pasando bajo la línea","Con guantes de goma, por cualquier lado"],"w":"Un fierro largo puede tocar o acercarse a la línea."},{"q":"La retro debe trabajar bajo una línea del tendido eléctrico. ¿Qué corresponde?","o":["Respetar la distancia del procedimiento y usar señalero","Trabajar si el operador tiene experiencia","Levantar el brazo despacio para no tocar","Trabajar si la línea parece desconectada"],"w":"La corriente puede saltar sin contacto directo."},{"q":"Una escala metálica se puede usar cerca de una línea aérea si se apoya con cuidado.","vf":false,"w":"Falso. Hay que mantener la distancia de seguridad."}]},{"s":"pz_elec_ext_ok","v":[{"q":"¿Cómo deben ir las extensiones en la obra?","o":["Colgadas en altura o protegidas, fuera del paso","En el suelo, pegadas al muro","Bajo los moldajes, para que no se pisen","Enrolladas junto al tablero"],"w":"Así no se dañan ni quedan en el agua."},{"q":"Una extensión cruza el camino de los camiones. ¿Qué corresponde?","o":["Colgarla en altura o protegerla","Taparla con tierra para que no se vea","Dejarla, si es una extensión gruesa","Pedir a los choferes que pasen despacio"],"w":"Aplastada pierde su aislamiento."},{"q":"¿Por qué no se dejan extensiones bajo materiales o en el barro?","o":["Se dañan y pierden el aislamiento","Se ensucian y luego no se ven","Se pierden entre los materiales","Dejan de funcionar con el frío"],"w":"Un aislamiento dañado causa descargas."}]}]},{"id":"caliente","sec":"esp","title":"Trabajos en caliente: soldadura y oxicorte","thumb":"pz_cal_ok","mins":5,"learn":[{"s":"pz_cal_intro","t":"¿Qué es un trabajo en caliente?","x":"Es toda tarea que genera <b>llama, chispas o calor</b>: soldar al arco, cortar con oxicorte, esmerilar o calentar con soplete. En obra se sueldan insertos, barandas, fierros y estructuras. Riesgos principales: <b>incendio</b> de moldajes, aserrín o plásticos; <b>quemaduras</b>; <b>daño a la vista</b> por el arco; <b>humos metálicos</b> que dañan los pulmones, y descarga eléctrica. Una chispa puede saltar varios metros y caer a los pisos de abajo."},{"s":"pz_cal_permiso","t":"Permiso y preparación del área","x":"Antes de encender:<ul><li>Tramita el <b>permiso de trabajo en caliente</b> cuando la obra lo exija.</li><li>Retira o cubre con mantas ignífugas todo lo combustible en unos <b>10 metros</b> a la redonda: madera, aserrín, cartón, plásticos, solventes.</li><li>Tapa rendijas y aberturas por donde caigan chispas al piso de abajo.</li><li>Deja un <b>extintor</b> a mano y define quién será el vigía.</li></ul>Mojar el aserrín o tapar con plástico no basta.","k":"Primero el área, después la chispa."},{"s":"pz_cal_ok","t":"EPP del soldador","x":"<ul><li><b>Careta de soldar</b> con filtro del tono adecuado; para oxicorte, lentes o careta de oxicorte.</li><li>Guantes, coleto y polainas de <b>cuero</b>.</li><li>Ropa de <b>algodón o ignífuga</b>: el polar y el nylon se derriten y se pegan a la piel.</li><li><b>Respirador</b> para humos metálicos si no hay buena ventilación.</li><li><b>Biombo</b> para proteger a los demás.</li></ul>El EPP es gratis y obligatorio: revísalo antes de usarlo y pide recambio si está dañado."},{"s":"pz_cal_mal","t":"El arco daña los ojos","x":"La luz del arco quema la córnea aunque la mires <b>un solo segundo</b>: es el “ojo de soldador”. Los síntomas aparecen horas después: dolor intenso, ardor, lagrimeo y sensación de arena en los ojos. Los lentes de seguridad claros <b>no</b> protegen del arco. Se usan <b>biombos</b> para que los compañeros no lo vean; si trabajas cerca de un soldador, no mires el arco. Con síntomas, avisa y consulta en la ACHS."},{"s":"pz_cal_cilindros","t":"Cilindros de oxígeno y acetileno","x":"<ul><li>Siempre <b>de pie y encadenados</b>, lejos del calor, del sol directo y de la zona de chispas.</li><li>Se trasladan en <b>carro</b> y con el <b>capuchón</b> puesto; nunca rodándolos ni izados desde el regulador.</li><li>Mangueras y reguladores en buen estado, con <b>válvulas antirretroceso</b>, que impiden que la llama se devuelva.</li><li><b>Nunca grasa ni aceite</b> en el oxígeno, ni guantes engrasados: puede inflamarse o explotar.</li></ul>"},{"s":"pz_elec_ext_mal","t":"Soldadura al arco: riesgo eléctrico","x":"<ul><li>Máquina con <b>puesta a tierra</b>, conectada a un tablero con sus protecciones.</li><li>Cables y pinza <b>sin daños</b> ni uniones con cinta.</li><li>Nunca sueldes con ropa o guantes <b>mojados</b>, ni parado en agua o barro.</li><li>Cambia el electrodo con guantes secos y deja la pinza sobre algo aislante, nunca sobre la estructura.</li></ul>Si ves un cable dañado o tirado en el agua, no lo uses y avisa."},{"s":"pz_cal_vigia","t":"Vigía de fuego","x":"Mientras se suelda, un compañero designado como <b>vigía</b> observa dónde caen las chispas, también en el piso de abajo, con un <b>extintor</b> listo para usar. El vigía no hace otra tarea al mismo tiempo. Al terminar, el área se sigue revisando por <b>al menos 30 minutos</b>: un rescoldo en el aserrín, en una aislación o en un plástico puede encenderse mucho después."},{"s":"quim_cc_solvente","t":"Nunca en envases con restos","x":"No sueldes, cortes ni esmerilles tambores, bidones o estanques que contuvieron <b>combustible, diluyente, pintura o gas</b>. Aunque se vean vacíos y secos, por dentro quedan <b>vapores</b> que explotan con una chispa. Dejarlo al sol para que se evapore no sirve. Si hay que intervenir uno, avisa a tu jefatura: requiere limpieza y un procedimiento especial.","k":"Nunca sueldes ni cortes un envase que tuvo combustible."},{"s":"ind_extintor","t":"Si se inicia un amago","x":"Si una chispa enciende algo, actúa solo si el fuego es pequeño y tienes la salida a tu espalda:<ul><li><b>Saca el seguro</b>.</li><li><b>Apunta a la base</b> del fuego, no a las llamas.</li><li><b>Presiona</b> la manilla.</li><li><b>Barre</b> de lado a lado.</li></ul>Si no se apaga, <b>retírate</b>, da la alarma y que llamen a Bomberos al <b>132</b>. Nunca agua sobre equipos energizados."}],"quiz":[{"s":"pz_cal_ok","v":[{"q":"Vas a soldar una baranda en la losa. ¿Cuál es la preparación correcta?","o":["Careta con filtro, cuero, biombo y extintor a mano","Careta con filtro y cuero; el extintor queda en bodega","Lentes oscuros de sol, guantes de cuero y biombo","Careta con filtro, chaqueta de polar y extintor a mano"],"w":"Careta con filtro, cuero, ropa que no se derrita, biombo para los demás y extintor listo."},{"q":"¿Cuál de estos equipos de soldador está completo?","o":["Careta con filtro, guantes, coleto y polainas de cuero, ropa de algodón","Careta con filtro, guantes de cuero y chaqueta de nylon","Lentes de seguridad claros, guantes y coleto de cuero","Careta con filtro, guantes de látex y ropa de algodón"],"w":"El cuero protege de chispas y calor; el algodón no se derrite; los lentes claros no protegen del arco."},{"q":"La ropa de polar o nylon sirve para soldar si es gruesa.","vf":false,"w":"Falso. El polar y el nylon se derriten y se pegan a la piel: algodón o ropa ignífuga."}]},{"s":"pz_cal_permiso","v":[{"q":"Debes soldar un inserto junto a moldajes de madera con aserrín en el piso. ¿Qué haces antes de encender?","o":["Retiro o cubro lo combustible en unos 10 m, veo el permiso y dejo extintor","Mojo el aserrín y empiezo, porque la madera húmeda no arde","Empiezo y pido a un compañero que barra mientras sueldo","Cubro los moldajes con plástico y dejo un balde de agua"],"w":"Las chispas saltan lejos: se retira o cubre con manta ignífuga lo combustible. El plástico arde."},{"q":"¿En qué orden se prepara un trabajo en caliente?","o":["Revisar el área, retirar lo combustible, permiso y vigía con extintor, y recién encender","Encender, ver hacia dónde saltan las chispas y retirar lo más cercano","Encender y pedir el permiso al terminar, para dejar registro","Retirar lo combustible solo si el trabajo dura más de una hora"],"w":"Primero el área y el permiso; después la chispa."},{"q":"¿Hasta qué distancia aproximada se retira o se cubre el material combustible?","o":["Unos 10 metros a la redonda","Un metro alrededor de la pieza","Solo lo que está justo debajo","Unos 3 metros a la redonda"],"w":"Las chispas viajan varios metros y caen a pisos inferiores."}]},{"s":"pz_cal_cilindros","v":[{"q":"¿Cómo deben estar los cilindros de oxígeno y acetileno en la obra?","o":["De pie, encadenados y lejos del calor","Acostados en el suelo para que no se caigan","De pie, sueltos y junto al punto de soldadura","Encadenados, pero al sol para que no se enfríen"],"w":"Encadenados no se caen ni se rompen las válvulas; el calor aumenta la presión."},{"q":"Hay que llevar un cilindro de acetileno a otro sector. ¿Cómo se hace?","o":["En carro, de pie, asegurado y con el capuchón puesto","Rodándolo por el suelo con el regulador puesto","Izándolo amarrado desde el regulador","Acostado en la carretilla, sin capuchón para ver la válvula"],"w":"El capuchón protege la válvula; un golpe en ella puede ser grave."},{"q":"¿Qué dispositivo impide que la llama se devuelva por las mangueras?","o":["La válvula antirretroceso","El manómetro del regulador","El capuchón del cilindro","La boquilla del soplete"],"w":"La antirretroceso evita que la llama vuelva hacia el cilindro."}]},{"s":"pz_cal_mal","v":[{"q":"Mirar el arco de soldadura sin careta, aunque sea un segundo, puede quemar la córnea.","vf":true,"w":"Verdadero. Es el ojo de soldador, y los síntomas aparecen horas después."},{"q":"Un compañero suelda a tu lado y no hay biombo. ¿Qué haces?","o":["Pido instalar un biombo y no miro el arco","Miro de reojo, porque así no daña","Me pongo mis lentes claros y sigo","Cierro un ojo cada vez que hay chispazo"],"w":"Los lentes claros no protegen del arco: se usa biombo y no se mira."},{"q":"¿Qué es el “ojo de soldador”?","o":["Una quemadura de la córnea por mirar el arco sin careta","Una alergia de los ojos por los humos metálicos","Un cansancio de la vista que pasa en minutos","Una herida por una chispa que salta al ojo"],"w":"La luz del arco quema la córnea: dolor, ardor y sensación de arena horas después."}]},{"s":"pz_cal_vigia","v":[{"q":"Terminaste de soldar en la losa. ¿Qué corresponde?","o":["Seguir revisando el área al menos 30 minutos por rescoldos","Guardar los equipos y retirarse de inmediato","Echar aserrín sobre las chispas para apagarlas","Revisar solo si se ve humo al irse"],"w":"Un rescoldo puede encenderse mucho después de terminar."},{"q":"¿Qué hace el vigía de fuego?","o":["Vigila las chispas con extintor durante el trabajo y revisa después","Sostiene la pieza mientras el soldador trabaja","Revisa el permiso al empezar y se va a otra tarea","Llama a Bomberos antes de empezar a soldar"],"w":"El vigía solo vigila: chispas, piso de abajo y extintor listo."},{"q":"¿Por qué el área se sigue revisando después de soldar?","o":["Porque un rescoldo puede encenderse mucho después","Para ordenar los cables de la máquina","Para que el vigía firme el permiso","Para medir cuánto electrodo se gastó"],"w":"El fuego puede iniciarse en aserrín o aislación sin que se note al terminar."}]},{"s":"ind_extintor","v":[{"q":"Una chispa enciende un cartón junto a la zona de soldadura. ¿Cómo usas el extintor?","o":["Saco el seguro, apunto a la base, presiono y barro","Saco el seguro y apunto a las llamas más altas","Presiono primero para probarlo y después saco el seguro","Apunto a la base y descargo sin mover la boquilla"],"w":"Seguro, base, presionar y barrer de lado a lado."},{"q":"¿Hacia dónde se dirige el chorro del extintor?","o":["A la base del fuego, barriendo de lado a lado","A la parte más alta de las llamas","Al humo, para que no se acumule","Al centro de las llamas, sin mover la boquilla"],"w":"El fuego se apaga atacando lo que se quema, en la base."},{"q":"El amago no se apaga con el extintor. ¿Qué haces?","o":["Me retiro, doy la alarma y se llama a Bomberos al 132","Busco otro extintor y sigo solo hasta apagarlo","Le echo agua aunque haya cables energizados","Lo tapo con cartón para ahogarlo"],"w":"Si no se apaga, la prioridad es salir y avisar: 132 Bomberos."}]},{"s":"quim_cc_solvente","v":[{"q":"Te piden cortar con oxicorte un tambor vacío que tuvo diluyente. ¿Qué haces?","o":["No lo corto: los vapores pueden explotar; aviso a mi jefatura","Lo corto, porque si está vacío no hay peligro","Lo dejo al sol un rato para que se evapore y lo corto","Lo corto rápido, con el vigía mirando"],"w":"Los vapores que quedan dentro explotan con la chispa."},{"q":"Un envase de combustible “vacío” es peligroso al soldarlo porque:","o":["Quedan vapores inflamables dentro","El metal se debilita con el combustible","La pintura del envase da humos tóxicos","El envase pesa más de lo que parece"],"w":"Vacío no significa sin vapores."},{"q":"Un tambor que contuvo solvente puede soldarse sin riesgo si se ve seco por dentro.","vf":false,"w":"Falso. Aunque se vea seco, quedan vapores que explotan."}]},{"s":"pz_cal_cilindros","v":[{"q":"El regulador del oxígeno está duro al girarlo. ¿Qué haces?","o":["No lo lubrico: lo saco de uso y aviso","Le pongo un poco de grasa","Le echo unas gotas de aceite de máquina","Lo giro con un alicate hasta que ceda"],"w":"Oxígeno con grasa o aceite puede inflamarse o explotar."},{"q":"El oxígeno en contacto con grasa o aceite puede inflamarse.","vf":true,"w":"Verdadero. Por eso nunca grasa, aceite ni guantes engrasados en el oxígeno."},{"q":"¿Por qué el equipo de oxígeno nunca debe tocar grasa ni aceite?","o":["Porque puede inflamarse o explotar","Porque se tapa la manguera","Porque el oxígeno se contamina y huele mal","Porque se congela el regulador"],"w":"El oxígeno a presión hace arder la grasa de forma violenta."}]}]},{"id":"izaje","sec":"esp","title":"Izaje de cargas y trabajo cerca de grúas","thumb":"pz_izaje_ok","mins":5,"learn":[{"s":"pz_izaje_mal","t":"La carga suspendida","x":"Una carga izada puede <b>caer, girar o balancearse</b> por una eslinga mal puesta, una pieza suelta, el viento o una mala maniobra. Paquetes de moldajes, fierro o planchas pesan cientos de kilos: si caen, no hay casco que proteja. <b>Nadie pasa ni se queda bajo una carga suspendida</b>, ni siquiera un segundo, ni en su recorrido.","k":"Nunca pases ni te quedes bajo una carga suspendida."},{"s":"pz_izaje_ok","t":"Zona de izaje delimitada","x":"El área bajo la maniobra y en todo el <b>recorrido</b> de la carga se <b>delimita</b> con cinta, conos o barreras, y solo entra el personal de la maniobra. Si la carga pasa sobre lugares de trabajo o pasillos, ese sector se despeja antes de izar. Respeta la delimitación aunque te desvíe: es la que te deja fuera de la línea de caída."},{"s":"pz_izaje_rigger","t":"Un solo rigger","x":"El <b>rigger o señalero</b> revisa el estrobado y es el <b>único</b> que da las señales al operador, con señales acordadas o por radio. Si el operador recibe señales de dos personas o no ve al rigger, se detiene. Pero <b>cualquiera</b> puede dar la señal de <b>PARE</b> si ve un peligro, y el operador la obedece."},{"s":"pz_izaje_eslinga","t":"Elementos de izaje","x":"Eslingas, estrobos, grilletes y ganchos deben ser <b>certificados</b>, con su <b>etiqueta de capacidad legible</b>, y se revisan antes de cada uso. Se sacan de uso:<ul><li>Eslingas con cortes, quemaduras, hilos deshilachados o sin etiqueta.</li><li>Estrobos con alambres cortados, aplastados o con nudos.</li><li>Ganchos deformados o <b>sin pestillo de seguridad</b>.</li></ul>No se reparan con nudos ni alambre."},{"s":"c5pe_eslinga","t":"Cantoneras en los cantos vivos","x":"Perfiles, fierros y planchas tienen <b>cantos filosos</b> que cortan una eslinga de cinta en plena maniobra. Por eso, donde la eslinga toque un canto, se pone una <b>cantonera</b> o protector. Tampoco se arrastra la eslinga por el suelo ni se deja aplastada bajo la carga al bajarla."},{"s":"pz_izaje_ok","t":"Cuerda guía","x":"Para controlar el giro de la carga se usa una <b>cuerda guía</b> amarrada a la carga y manejada desde fuera de su línea de caída. Nunca guíes la carga con las manos ni con el hombro, y nunca te pongas <b>entre la carga y un muro, una columna u otra carga</b>: un giro te puede aplastar."},{"s":"camion_carga_grua","t":"Antes de izar","x":"<ul><li>Conoce el <b>peso</b> de la carga y verifica que no supere la capacidad de la grúa ni de las eslingas.</li><li>Carga <b>bien amarrada y equilibrada</b>, sin piezas sueltas encima.</li><li>Recorrido libre de personas.</li><li>Haz <b>contacto visual</b> con el operador.</li></ul>Con <b>viento fuerte</b> o si la carga empieza a balancearse, la maniobra <b>se suspende</b>: las planchas grandes actúan como vela."},{"s":"pz_elec_lineas","t":"Líneas eléctricas","x":"La pluma, el cable y la carga deben mantenerse lejos de las <b>líneas eléctricas</b>: la corriente puede saltar sin que haya contacto. Respeta la distancia que fija el procedimiento y, si no se puede, no se iza hasta coordinar el corte. Si hay contacto: el operador se queda en la cabina y los demás se alejan con pasos cortos, sin tocar la carga ni la grúa, y avisan."},{"s":"pz_derechos","t":"Personal acreditado y derecho a detenerse","x":"La grúa la opera solo un <b>operador acreditado y autorizado</b> por la empresa, y el estrobado lo hace personal capacitado. <b>Nadie viaja sobre la carga ni en el gancho.</b> Si ves un riesgo grave e inminente, tienes derecho a <b>detenerte</b> y salir de la zona (Código del Trabajo, art. 184 bis), avisando de inmediato a tu jefatura."}],"quiz":[{"s":"pz_izaje_mal","v":[{"q":"Se iza un paquete de moldajes. ¿Dónde debes estar?","o":["Fuera de la zona delimitada y lejos del recorrido","Bajo la carga, listo para recibirla","Junto a la carga, sujetándola con las manos","Dentro de la zona, detrás del rigger"],"w":"Fuera de la zona y de la línea de caída: la carga puede caer o girar."},{"q":"Un compañero cruza bajo la carga “porque es rápido”. ¿Qué corresponde?","o":["Dar la señal de PARE y sacarlo de la zona","Dejarlo pasar si la carga está bien amarrada","Comentárselo al terminar la jornada","Pedir al operador que suba más la carga"],"w":"Nadie pasa bajo una carga suspendida, y cualquiera puede dar PARE."},{"q":"Si la carga está bien estrobada, se puede pasar rápido por debajo.","vf":false,"w":"Falso. Ningún estrobado elimina el riesgo de caída: nunca bajo la carga."}]},{"s":"pz_izaje_rigger","v":[{"q":"¿Quién da las señales al operador de la grúa?","o":["Solo el rigger designado; cualquiera puede dar PARE","El trabajador que esté más cerca de la carga","El capataz y el rigger, al mismo tiempo","Cualquiera de la cuadrilla que vea la carga"],"w":"Una sola voz evita confusiones; el PARE lo puede dar cualquiera."},{"q":"Durante una maniobra, el operador recibe señales de dos personas distintas. ¿Qué debe hacer?","o":["Detenerse y aclarar quién es el único rigger","Seguir al que tenga más experiencia","Seguir la última señal que recibió","Seguir al que esté más cerca de la carga"],"w":"Con señales cruzadas, la maniobra se detiene."},{"q":"Ves un peligro durante el izaje y no eres el rigger. ¿Puedes dar la señal de PARE?","o":["Sí, cualquiera puede dar PARE ante un peligro","No, solo el rigger puede hacer señales","Solo si el capataz me autoriza","Solo cuando la carga ya está abajo"],"w":"El PARE es de todos; las demás señales, solo del rigger."}]},{"s":"pz_izaje_eslinga","v":[{"q":"Una eslinga con cortes, quemaduras o hilos deshilachados se saca de uso aunque la carga sea liviana.","vf":true,"w":"Verdadero. Un elemento dañado no se usa con ninguna carga."},{"q":"Revisas eslingas antes de izar. ¿Cuál se saca de uso?","o":["La que no tiene etiqueta legible, aunque se vea sana","La que tiene polvo de cemento, con etiqueta y sin daños","La que se usó ayer, con etiqueta y sin daños","La de capacidad mayor a la carga, con etiqueta y sin daños"],"w":"Sin etiqueta no se conoce su capacidad: fuera de uso."},{"q":"Un gancho de izaje sin su pestillo de seguridad:","o":["Se saca de uso hasta repararlo","Se puede usar si la carga es liviana","Se puede usar cerrándolo con alambre","Se usa solo para izajes cortos"],"w":"Sin pestillo, la eslinga puede salirse del gancho."}]},{"s":"pz_izaje_ok","v":[{"q":"La carga empieza a girar en el aire. ¿Cómo se controla?","o":["Con la cuerda guía, desde fuera de su línea de caída","Sujetándola con las manos cuando baja","Frenándola con el hombro","Con un fierro largo apoyado en la carga"],"w":"La cuerda guía controla el giro sin acercarse a la carga."},{"q":"Al bajar un paquete de fierro junto a un muro, ¿dónde nunca te pones?","o":["Entre la carga y el muro","En el extremo de la cuerda guía","Fuera de la zona delimitada","Junto al rigger, fuera del radio"],"w":"Un giro de la carga aplasta a quien queda entre ella y el muro."},{"q":"¿Para qué sirve la cuerda guía en un izaje?","o":["Para controlar el giro sin acercarse a la carga","Para amarrar la carga al gancho","Para asegurar al trabajador a la estructura","Para subir herramientas al piso de arriba"],"w":"Mantiene a las personas lejos de la carga."}]},{"s":"pz_izaje_rigger","v":[{"q":"Se levanta viento fuerte y la carga empieza a balancearse. ¿Qué corresponde?","o":["Suspender la maniobra y bajar la carga de forma controlada","Terminar más rápido para ganarle al viento","Sujetar la carga entre dos personas","Seguir, si la carga es liviana"],"w":"Con viento fuerte, el izaje se suspende."},{"q":"Con viento fuerte, las maniobras de izaje:","o":["Se suspenden hasta que el viento baje","Se hacen solo con cargas pequeñas","Siguen igual si hay cuerda guía","Se aceleran para terminar antes"],"w":"La cuerda guía no basta contra el viento fuerte."},{"q":"Hay que izar planchas grandes de terciado con viento. ¿Por qué es más peligroso?","o":["Porque actúan como vela y la carga se balancea","Porque el viento las moja y pesan más","Porque el viento suelta los grilletes","Porque el operador pierde la radio"],"w":"Las superficies grandes toman el viento como una vela."}]},{"s":"pz_derechos","v":[{"q":"Se puede subir a la carga para guiarla hasta su lugar si la grúa va despacio.","vf":false,"w":"Falso. Nadie viaja sobre la carga ni en el gancho."},{"q":"Necesitas llegar a la losa de arriba y la grúa está subiendo una carga. ¿Puedes viajar en ella?","o":["No, nadie viaja en la carga ni en el gancho","Sí, si me amarro bien al gancho","Sí, si el operador va despacio","Sí, con el arnés conectado a la eslinga"],"w":"La grúa no es para transportar personas."},{"q":"¿Quién puede operar la grúa en la obra?","o":["Un operador acreditado y autorizado por la empresa","El rigger, cuando el operador sale a colación","Cualquiera que sepa manejar maquinaria","El trabajador más antiguo de la cuadrilla"],"w":"Solo operador acreditado y autorizado."}]},{"s":"camion_carga_grua","v":[{"q":"Antes de izar un paquete de moldajes, ¿qué se verifica?","o":["Peso dentro de la capacidad, amarre firme y nada suelto encima","Que esté amarrado; el peso se ve al levantarlo","Que tenga cuerda guía; el peso no importa si es corto","Que esté equilibrado, aunque queden tablas sueltas"],"w":"Peso conocido, amarre, equilibrio y nada suelto."},{"q":"Sobre un paquete de fierros quedaron dos trozos sueltos. ¿Qué haces antes de izar?","o":["Los retiro o los amarro antes de dar la señal","Lo izo despacio para que no caigan","Los dejo, porque pesan poco","Pido que se suba más rápido"],"w":"Una pieza suelta cae desde la altura del izaje."},{"q":"¿Por qué hay que conocer el peso de la carga antes de izar?","o":["Para no superar la capacidad de la grúa ni de las eslingas","Para anotarlo en la guía de despacho","Para calcular cuánto durará la maniobra completa","Para saber cuántas personas la reciben abajo"],"w":"Superar la capacidad puede cortar la eslinga o volcar la grúa."}]},{"s":"pz_elec_lineas","v":[{"q":"La pluma de la grúa debe pasar cerca de una línea eléctrica. ¿Qué corresponde?","o":["Respetar la distancia y, si no se puede, no izar hasta coordinar el corte","Pasar despacio y con cuidado, porque el cable está aislado","Pasar rápido, para no alcanzar a hacer contacto con el cable","Pedir que alguien levante el cable con un palo seco"],"w":"La corriente puede saltar sin contacto."},{"q":"La carga toca una línea eléctrica y tú estás en el suelo cerca. ¿Qué haces?","o":["Me alejo con pasos cortos, sin tocar la carga ni la grúa, y aviso","Tomo la cuerda guía para separar la carga del cable","Corro a sujetar la carga para que no se mueva más","Me acerco a la grúa para ayudar al operador a bajar"],"w":"La grúa, la carga y el suelo cercano pueden estar energizados."},{"q":"Una línea eléctrica puede hacer saltar la corriente a la pluma aunque no la toque.","vf":true,"w":"Verdadero. Por eso se respeta la distancia del procedimiento."}]}]},{"id":"maquinaria","sec":"conductores","title":"Operación segura de maquinaria pesada","thumb":"pz_senalero","mins":5,"learn":[{"s":"pz_retro_ok","t":"Solo operadores autorizados","x":"Retroexcavadora, minicargador, rodillo o camión los opera solo quien tiene la <b>licencia que corresponde</b>, la <b>capacitación</b> en ese equipo y la <b>autorización escrita</b> de {EMP}. Nadie más los mueve, ni “un poquito”. Nadie viaja como pasajero ni en el balde. Si tienes que acercarte a una máquina, primero haz <b>contacto visual</b> con el operador y espera su señal.","k":"Sin licencia y autorización, no se opera."},{"s":"camion_conduccion_revision","t":"Revisión antes de operar","x":"Cada turno, antes de partir, el operador revisa y registra en el checklist:<ul><li><b>Frenos</b>, dirección y freno de estacionamiento.</li><li><b>Luces, baliza y alarma de retroceso</b>.</li><li>Neumáticos u orugas, niveles y <b>fugas</b> de aceite o combustible.</li><li>Espejos, vidrios, <b>cinturón</b> y extintor.</li></ul>Si encuentras una falla, la máquina queda detenida y avisas: no se opera “con cuidado”."},{"s":"camion_conduccion_cabina","t":"Cinturón y tres puntos de apoyo","x":"El <b>cinturón</b> te mantiene dentro de la cabina si la máquina se vuelca; sin él, la misma máquina te aplasta. Úsalo siempre, aunque el tramo sea corto. Sube y baja <b>de frente</b>, con <b>3 puntos de apoyo</b>: dos manos y un pie, o dos pies y una mano. Nunca saltes ni bajes con cosas en las manos."},{"s":"pz_retro_radio","t":"Radio de giro despejado","x":"El brazo, el balde y la parte trasera de la retro barren un círculo al girar: es el <b>radio de giro</b>. Antes de girar o retroceder, verifica que no haya nadie dentro. Si alguien entra, <b>detén la máquina</b> y no sigas hasta que salga. La alarma de retroceso avisa, pero <b>no reemplaza</b> tu verificación.","k":"Si alguien entra al radio de giro, detén la máquina."},{"s":"pz_senalero","t":"Señalero y retroceso","x":"En retroceso, en espacios reducidos o con poca visibilidad se trabaja <b>con señalero</b>. El señalero se ubica donde el operador lo vea siempre, fuera del recorrido de la máquina, y usa señales acordadas. Si pierdes de vista al señalero, <b>detente</b> hasta volver a verlo."},{"s":"pz_zanja_borde","t":"Bordes, taludes y pendientes","x":"No acerques la máquina al borde de excavaciones ni taludes: su peso puede <b>derrumbar el borde</b> y volcarla, aunque el suelo esté seco. Respeta la distancia que fije el procedimiento. Evita terreno blando y rellenos recientes, sube y baja pendientes de frente, nunca de lado, y con el balde bajo."},{"s":"pz_elec_lineas","t":"Líneas eléctricas","x":"Con el brazo o la tolva en alto, mantén la distancia de las <b>líneas eléctricas</b> y trabaja con señalero si te acercas: la corriente puede saltar sin contacto. Si la máquina toca un cable, <b>quédate en la cabina</b> y avisa que nadie se acerque. Los demás se alejan con pasos cortos y no tocan la máquina."},{"s":"camion_conduccion_alcohol","t":"Cero alcohol y drogas; celular guardado","x":"Operar maquinaria exige <b>cero alcohol y cero drogas</b>. La Ley 20.580 considera bajo la influencia desde <b>0,3 g/l</b> y ebriedad desde <b>0,8 g/l</b>, pero en el trabajo la regla es cero, y el alcohol de la noche anterior puede seguir en la sangre. Avisa si un medicamento te da sueño. El <b>celular</b> va guardado mientras operas."},{"s":"horquilla_estacionar","t":"Al estacionar","x":"Al dejar la máquina, aunque sea por un momento:<ul><li><b>Balde y pala apoyados en el suelo</b>.</li><li><b>Freno de estacionamiento</b> puesto.</li><li><b>Motor apagado y llave retirada</b>, para que nadie no autorizado la use.</li></ul>Estaciona en terreno plano, lejos de bordes y vías de tránsito; si hay pendiente, pon cuñas."}],"quiz":[{"s":"camion_conduccion_revision","v":[{"q":"En la revisión de la retro notas una fuga de aceite hidráulico. ¿Qué haces?","o":["La dejo detenida y aviso","La opero y reviso el nivel al final del turno","Relleno aceite y empiezo sin avisar","La opero solo en trabajos cortos"],"w":"Con falla, la máquina no se opera."},{"q":"¿Qué se revisa antes de operar una máquina?","o":["Frenos, luces, alarma de retroceso, neumáticos, fugas, extintor y cinturón","Solo el combustible y el aceite; lo demás lo revisa mantención","Frenos y luces cada día; lo demás, una vez por semana","Que encienda bien, que tenga la llave y el estanque lleno"],"w":"La revisión completa se hace cada turno."},{"q":"¿Quién y cuándo hace la revisión pre-uso?","o":["El operador, antes de cada turno","El mecánico, una vez al mes","El jefe de obra, cuando llega a la obra","El operador del turno anterior, al terminar"],"w":"Quien va a operar revisa antes de partir."}]},{"s":"pz_retro_mal","v":[{"q":"Estás excavando y un jornal entra en el radio de giro de tu retro. ¿Qué haces?","o":["Detengo la máquina y no sigo hasta que salga","Toco la bocina y sigo girando","Giro más lento para no tocarlo","Sigo, porque él sabe que estoy trabajando"],"w":"Con alguien en el radio de giro, la máquina se detiene."},{"q":"Necesitas pasar junto a una retro que está trabajando. ¿Qué haces?","o":["Espero contacto visual y que el operador detenga la máquina","Paso rápido por detrás, junto al contrapeso","Paso si escucho la alarma de retroceso","Paso por el lado del brazo, donde él mira"],"w":"Sin contacto visual y máquina detenida, no te acerques."},{"q":"La alarma de retroceso no reemplaza verificar que nadie esté en el radio de giro.","vf":true,"w":"Verdadero. La alarma avisa, pero el operador debe verificar y detenerse."}]},{"s":"pz_senalero","v":[{"q":"Retrocedes con la máquina y pierdes de vista al señalero. ¿Qué haces?","o":["Me detengo hasta volver a verlo","Sigo despacio, porque ya sé el camino","Sigo guiándome por el espejo","Toco la bocina y avanzo"],"w":"Sin ver al señalero, no se avanza."},{"q":"¿Dónde debe ubicarse el señalero?","o":["Donde el operador lo vea siempre, fuera del recorrido","Detrás de la máquina, en su camino, para ver mejor","Al lado del brazo, dentro del radio de giro","En la cabina, junto al operador, indicándole"],"w":"Visible y fuera del recorrido."},{"q":"¿Cuándo se trabaja con señalero?","o":["En retroceso, en espacios reducidos o con poca visibilidad","Solo cuando lo pide el mandante o la inspección","Solo en trabajos nocturnos o con neblina","Solo si el operador es nuevo en la obra"],"w":"Donde el operador no ve bien, se necesita señalero."}]},{"s":"altura_camion_ok","v":[{"q":"Bajar de la máquina saltando está permitido si es poca altura.","vf":false,"w":"Falso. Siempre de frente y con 3 puntos de apoyo."},{"q":"¿Cómo se sube y se baja de la cabina?","o":["De frente, con 3 puntos de apoyo","De espaldas, saltando el último peldaño","Afirmado solo de la puerta","Con una mano, llevando la mochila en la otra"],"w":"Dos manos y un pie, o dos pies y una mano."},{"q":"Vas a bajar de la máquina con un termo en la mano. ¿Qué es correcto?","o":["Dejar el termo y bajar de frente con 3 puntos","Bajar de espaldas con una mano libre","Saltar desde el último peldaño","Bajar de frente afirmado solo de la puerta"],"w":"Con algo en las manos no hay 3 puntos de apoyo."}]},{"s":"pz_elec_lineas","v":[{"q":"El brazo de la retro toca una línea eléctrica. ¿Qué haces como operador?","o":["Me quedo en la cabina y aviso que nadie se acerque","Salto de la cabina y corro lejos de la máquina","Me bajo con cuidado a revisar el brazo","Bajo por la escalerilla y pido que corten la luz"],"w":"La máquina puede estar energizada: dentro de la cabina estás más seguro."},{"q":"Estás cerca de una máquina que tocó un cable. ¿Qué haces?","o":["Me alejo con pasos cortos y no toco la máquina","Toco la máquina para ayudar al operador a bajar","Me acerco a revisar el cable","Le paso una mano al operador para que baje"],"w":"El suelo cercano y la máquina pueden estar energizados."},{"q":"Trabajas con la tolva en alto cerca de cables eléctricos. ¿Qué corresponde?","o":["Mantener la distancia y trabajar con señalero","Subir y bajar la tolva rápido","Acercarse si los cables tienen aislación","Bajar la tolva solo si toca el cable"],"w":"La corriente puede saltar sin contacto."}]},{"s":"horquilla_estacionar","v":[{"q":"Terminas el turno con la retro. ¿Cómo la dejas?","o":["Balde y pala en el suelo, freno, motor apagado y llave retirada","Balde en alto para que no se ensucie, motor apagado","Motor en marcha para que no se enfríe, con freno","Llave puesta para el operador siguiente"],"w":"Implementos al suelo, freno, motor apagado y sin llave."},{"q":"¿Por qué se retira la llave al estacionar la máquina?","o":["Para que nadie no autorizado la opere","Para que no se descargue la batería","Para cumplir con el seguro del vehículo","Para que el motor se enfríe antes"],"w":"La máquina solo la opera personal autorizado."},{"q":"Debes dejar la máquina en un sector con pendiente. ¿Qué corresponde?","o":["Implementos al suelo, freno puesto y cuñas","Dejar el balde en alto como freno","Dejar el motor en marcha y en neutro","Estacionarla de lado a la pendiente"],"w":"Con pendiente, además de freno e implementos al suelo, se ponen cuñas."}]},{"s":"pz_zanja_borde","v":[{"q":"El peso de la máquina puede derrumbar el borde de una zanja aunque el suelo esté seco.","vf":true,"w":"Verdadero. Por eso la máquina se mantiene lejos del borde."},{"q":"Debes cargar tierra junto a una excavación. ¿Dónde ubicas la máquina?","o":["Lejos del borde, en terreno firme, a la distancia del procedimiento","Lo más cerca del borde, para alcanzar mejor la tierra","Sobre el talud, para quedar más alto que el camión","En el borde, siempre que el suelo esté seco y firme"],"w":"El peso de la máquina carga el borde y puede derrumbarlo."},{"q":"¿Cómo se sube una pendiente con la retro?","o":["De frente y con el balde bajo","De lado, para ir más estable","Con el balde en alto para ver mejor","En diagonal y rápido"],"w":"De lado o con el balde en alto aumenta el riesgo de volcamiento."}]},{"s":"pz_retro_ok","v":[{"q":"Un jornal con licencia de auto quiere mover el minicargador “solo un poco”. ¿Puede?","o":["No: se necesita la licencia que corresponde y autorización","Sí, si es un trayecto corto dentro de la obra","Sí, si el operador autorizado lo acompaña","Sí, si ya tiene experiencia en otra obra"],"w":"Licencia, capacitación y autorización escrita de la empresa."},{"q":"¿Quién puede operar maquinaria en la obra?","o":["Quien tiene licencia, capacitación y autorización escrita","Cualquiera con experiencia demostrada","El trabajador más antiguo de la cuadrilla","Quien tenga licencia de conducir clase B"],"w":"Sin licencia y autorización, no se opera."},{"q":"El operador autorizado faltó hoy. ¿Quién lo reemplaza?","o":["Otro operador con licencia y autorización","El jornal que siempre lo mira operar","El capataz, aunque no tenga licencia","Cualquiera que sepa encenderla"],"w":"El reemplazo también debe estar autorizado."}]}]},{"id":"camion_conduccion","sec":"conductores","title":"Conducción segura de camiones","thumb":"camion_conduccion_intro","mins":5,"learn":[{"s":"camion_conduccion_intro","t":"Manejas un camión cargado","x":"Un camión con carga pesa varias toneladas: <b>necesita mucha más distancia para frenar</b> y tiene <b>zonas que no ves</b>. Para conducirlo necesitas la <b>licencia profesional</b> que corresponde (Ley 18.290): clase A4 para camión simple de más de 3.500 kg y A5 para articulados; la clase B no sirve. Además, la autorización de {EMP}. Un choque o atropello durante el trabajo es <b>accidente del trabajo</b> (Ley 16.744)."},{"s":"camion_conduccion_revision","t":"Revisión antes de salir","x":"Antes de cada salida, da una vuelta completa al camión y revisa:<ul><li><b>Frenos</b> y freno de mano.</li><li><b>Neumáticos</b>: presión, cortes y pernos.</li><li><b>Luces</b>, intermitentes y alarma de retroceso.</li><li><b>Espejos</b> limpios y bien puestos.</li><li>Fugas bajo el camión, extintor, cuñas y carga amarrada.</li></ul>Si algo falla, <b>no salgas</b> y avisa a tu jefatura: una falla en ruta, con carga, es mucho más peligrosa."},{"s":"camion_conduccion_ciegos","t":"Puntos ciegos","x":"Alrededor del camión hay zonas que <b>no ves</b>, ni siquiera con los espejos bien ajustados:<ul><li><b>Atrás</b>: la zona más grande.</li><li><b>Al lado derecho</b>, junto a la cabina.</li><li><b>Justo delante</b> de la cabina.</li></ul>Antes de mover el camión, mira los espejos y <b>da una vuelta</b> si alguien pudo acercarse. Para los peatones: si no ves los espejos del camión, el conductor no te ve."},{"s":"camion_conduccion_retro_ok","t":"Retroceder con ayuda","x":"Retroceder es la maniobra más riesgosa: atrás está tu zona ciega más grande.<ul><li>Usa un <b>señalero</b> (tu ayudante), siempre <b>visible en tu espejo</b> y fuera del recorrido.</li><li>La <b>alarma de retroceso</b> debe funcionar, pero no basta por sí sola.</li><li>Si pierdes de vista al señalero, <b>detente</b>.</li><li>Si estás solo y no ves, <b>bájate y mira</b>.</li></ul>","k":"Si pierdes de vista al señalero, detente."},{"s":"camion_conduccion_velocidad","t":"Velocidad y distancia","x":"Respeta los <b>límites de velocidad</b> y las reglas internas de {EMP}. Deja <b>mucha más distancia</b> con el vehículo de adelante que en un auto, como referencia <b>al menos 4 segundos</b>: con carga, el camión tarda más en detenerse. Baja la velocidad con <b>lluvia, neblina, ripio y curvas</b>, y cerca de colegios y obras. Llegar unos minutos tarde no es grave; un choque sí."},{"s":"camion_conduccion_fatiga","t":"Fatiga y sueño","x":"Si cierras los ojos <b>un segundo, el camión sigue avanzando</b> varios metros sin control. Señales: bostezos, pestañeo seguido, cabeceo, no recordar los últimos kilómetros.<ul><li>Duerme bien antes de tu turno y respeta los descansos.</li><li>Si tienes sueño, <b>detente en un lugar seguro</b>: la ventana abierta o la música no lo quitan.</li><li>Avisa a tu jefatura si un medicamento te da sueño.</li></ul>"},{"s":"camion_conduccion_cabina","t":"Cinturón y celular","x":"<ul><li><b>Cinturón de seguridad</b> siempre, para ti y para tu <b>ayudante</b>, aunque el tramo sea corto o dentro de la obra.</li><li>La Ley de Tránsito <b>prohíbe manipular el celular</b> al conducir: ni llamar con el teléfono en la mano, ni escribir, ni revisar mensajes, tampoco en un semáforo.</li><li>Si necesitas llamar o revisar una dirección, <b>detente en un lugar seguro</b>.</li></ul>"},{"s":"camion_conduccion_alcohol","t":"Cero alcohol y cero drogas","x":"La Ley 20.580 (“Tolerancia Cero”) establece:<ul><li>desde <b>0,3 g/l</b>: <b>bajo la influencia</b> del alcohol;</li><li>desde <b>0,8 g/l</b>: <b>estado de ebriedad</b>.</li></ul>En el trabajo, la regla es <b>cero alcohol y cero drogas</b>. El alcohol de la noche anterior puede seguir en tu sangre aunque te sientas bien. Si alguien llega bajo los efectos del alcohol, <b>no conduce</b>: se avisa a la jefatura.","k":"Al trabajar: cero alcohol y cero drogas."},{"s":"camion_conduccion_obra","t":"Al llegar a la obra","x":"Antes de entrar, <b>mira el lugar</b>:<ul><li><b>Cables eléctricos</b> aéreos: la carga, la rampla o la pluma no deben acercarse.</li><li><b>Terreno blando</b>, zanjas o rellenos que pueden ceder.</li><li><b>Pendientes</b>: no descargues en desnivel; freno puesto y cuñas.</li><li>Trabajadores y peatones alrededor.</li></ul>Si no es seguro, <b>no entres</b>: busca otro punto y coordina con la obra."},{"s":"camion_conduccion_auto","t":"Autocuidado al volante","x":"La mayoría de los accidentes se relacionan con <b>acciones inseguras</b>. En el camión, la típica es <b>el apuro</b>: retroceder sin mirar, saltarse la revisión, contestar el celular. La decisión segura: <b>revisar, mirar y, si dudas, bajarte a ver</b>. Avisa también las condiciones inseguras, como frenos raros, un espejo roto o un acceso peligroso, y no salgas hasta que se corrijan."}],"quiz":[{"s":"camion_conduccion_revision","v":[{"q":"En la revisión notas que el freno está raro. ¿Qué haces?","o":["No salgo y aviso a mi jefatura","Salgo despacio y lo reviso a la vuelta","Salgo sin carga para probarlo en ruta","Lo anoto en el checklist y salgo igual"],"w":"Un camión con falla no sale."},{"q":"Revisas un neumático y ves un corte profundo en el costado. ¿Qué corresponde?","o":["No salgo hasta que se cambie y aviso","Salgo, porque tiene buena presión","Salgo con menos carga para cuidarlo","Lo cambio a la vuelta del despacho"],"w":"Un neumático cortado puede reventar con carga."},{"q":"¿Cuándo se hace la revisión del camión?","o":["Antes de cada salida","Una vez por semana","Solo cuando se enciende una alarma","Solo si otro conductor lo usó antes"],"w":"Cada salida, una vuelta completa al camión."}]},{"s":"camion_conduccion_ciegos","v":[{"q":"¿Dónde está la zona ciega más grande de un camión?","o":["Atrás del camión","Al lado izquierdo, junto al conductor","Varios metros delante de la cabina","Sobre la carga"],"w":"Atrás no ves nada directamente: por eso se retrocede con señalero."},{"q":"Un peatón camina pegado al lado derecho de la cabina. ¿Qué ocurre?","o":["Está en un punto ciego: el conductor puede no verlo","El conductor lo ve bien por el espejo izquierdo","No hay riesgo si el camión va lento","Solo hay riesgo si el camión retrocede"],"w":"Junto a la cabina, al lado derecho, hay un punto ciego."},{"q":"Al lado derecho de la cabina hay una zona que el conductor no ve, aunque tenga los espejos bien puestos.","vf":true,"w":"Verdadero. Atrás, al lado derecho y justo delante hay puntos ciegos."}]},{"s":"camion_conduccion_retro_mal","v":[{"q":"Debes retroceder para descargar y nadie te guía. ¿Qué haces?","o":["Me bajo a mirar y busco un señalero antes de retroceder","Retrocedo despacio confiando en la alarma","Retrocedo mirando solo el espejo izquierdo","Toco la bocina varias veces y retrocedo"],"w":"Sin señalero y sin ver, se baja y se mira."},{"q":"¿Cuál es la condición correcta para retroceder?","o":["Señalero visible en el espejo y alarma funcionando","Alarma funcionando, aunque no haya señalero","Señalero detrás del camión, en su recorrido","Ventana abierta para escuchar si alguien grita"],"w":"El señalero se ubica donde lo veas, fuera del recorrido."},{"q":"Retrocedes y el señalero desaparece de tu espejo. ¿Qué haces?","o":["Me detengo hasta volver a verlo","Sigo, porque ya me indicó que había espacio","Sigo más lento","Toco la bocina y sigo"],"w":"Si pierdes de vista al señalero, te detienes."}]},{"s":"camion_conduccion_auto","v":[{"q":"Vas atrasado con el despacho. ¿Cuál es la decisión segura?","o":["Hacer la revisión y maniobrar con calma igual","Saltarme la revisión solo por esta vez","Retroceder sin señalero para ganar tiempo","Revisar a la vuelta, con el camión vacío"],"w":"La mayoría de los accidentes vienen del apuro."},{"q":"Notas que el espejo derecho está roto. ¿Qué haces?","o":["Aviso y no salgo hasta que se repare","Salgo y uso más el espejo izquierdo","Lo afirmo con cinta y salgo","Salgo y lo informo al final del día"],"w":"Una condición insegura se avisa y se corrige antes de salir."},{"q":"Dudas si hay espacio para maniobrar en la obra. ¿Qué haces?","o":["Me bajo y miro antes de mover el camión","Avanzo despacio y corrijo si topo","Pido que alguien grite si me acerco","Confío en la alarma de retroceso"],"w":"Si dudas, bájate y mira: toma un minuto."}]},{"s":"camion_conduccion_alcohol","v":[{"q":"Según la Ley 20.580, ¿desde qué nivel de alcohol hay “estado de ebriedad”?","o":["Desde 0,8 g/l","Desde 0,3 g/l","Desde 1,0 g/l","Desde 0,5 g/l"],"w":"Desde 0,3 g/l es bajo la influencia; desde 0,8 g/l, ebriedad."},{"q":"¿Desde qué nivel se considera “bajo la influencia del alcohol”?","o":["Desde 0,3 g/l","Desde 0,8 g/l","Desde 0,5 g/l","Desde 0,1 g/l"],"w":"Desde 0,3 g/l, bajo la influencia; desde 0,8 g/l, ebriedad."},{"q":"Un conductor marca 0,5 g/l. ¿Cómo lo clasifica la ley?","o":["Bajo la influencia del alcohol","Estado de ebriedad","Dentro de lo permitido","Ebriedad leve"],"w":"Entre 0,3 y 0,8 g/l es bajo la influencia."}]},{"s":"camion_conduccion_alcohol","v":[{"q":"Si el examen marca menos de 0,3 g/l, puedo conducir el camión de la obra sin problema.","vf":false,"w":"Falso. Al trabajar la regla es cero alcohol y cero drogas."},{"q":"Anoche tomaste bastante y hoy te sientes bien. ¿Qué haces?","o":["Aviso a mi jefatura antes de conducir","Conduzco, porque ya dormí","Tomo café cargado y conduzco","Conduzco solo trayectos cortos"],"w":"El alcohol puede seguir en la sangre aunque te sientas bien."},{"q":"Un compañero llega con olor a alcohol y le toca conducir. ¿Qué corresponde?","o":["Avisar a la jefatura: no debe conducir","Dejarlo conducir si dice que está bien","Acompañarlo para vigilarlo","Esperar a ver si maneja mal"],"w":"Quien está bajo los efectos del alcohol no conduce."}]},{"s":"camion_conduccion_fatiga","v":[{"q":"Vas manejando y empiezas a bostezar y pestañear seguido. ¿Qué haces?","o":["Me detengo en un lugar seguro","Abro la ventana y sigo","Subo el volumen de la radio y sigo","Acelero para llegar antes"],"w":"La ventana o la música no quitan el sueño."},{"q":"¿Cuál de estas es una señal de sueño al volante?","o":["No recordar los últimos kilómetros","Tener hambre","Sentir frío en las manos","Ver reflejos en el parabrisas"],"w":"Bostezos, pestañeo, cabeceo y no recordar el camino."},{"q":"Tomaste un antialérgico que da sueño y te toca conducir. ¿Qué haces?","o":["Aviso a mi jefatura antes de conducir","Conduzco con la ventana abierta","Tomo una bebida energética y salgo","Conduzco solo por la mañana"],"w":"Un medicamento que da sueño se avisa antes de conducir."}]},{"s":"camion_conduccion_celu_mal","v":[{"q":"Suena el celular mientras manejas. ¿Qué haces?","o":["Me detengo en un lugar seguro y devuelvo la llamada","Contesto rápido con el teléfono en la mano","Leo el mensaje en el próximo semáforo","Contesto en altavoz sosteniéndolo en la mano"],"w":"El celular se usa solo detenido en un lugar seguro."},{"q":"Necesitas revisar la dirección de la obra en el celular. ¿Qué haces?","o":["Me detengo en un lugar seguro y la reviso","La reviso en un semáforo en rojo","La reviso rápido en una recta","Escribo la dirección mientras manejo despacio"],"w":"Manipular el celular al conducir está prohibido."},{"q":"¿Qué prohíbe la Ley de Tránsito sobre el celular al conducir?","o":["Manipularlo: llamar con él en la mano o escribir","Solo enviar mensajes; llamar está permitido","Solo usarlo en carretera","Usarlo solo si se va a más de 50 km/h"],"w":"Ni llamar con el teléfono en la mano, ni escribir."}]},{"s":"camion_conduccion_cabina","v":[{"q":"El ayudante también debe usar cinturón de seguridad, aunque el viaje sea corto.","vf":true,"w":"Verdadero. Todos los que van en la cabina usan cinturón."},{"q":"¿Quiénes deben usar cinturón en la cabina?","o":["El conductor y todos los acompañantes","Solo el conductor","Todos, pero solo en carretera","Solo en viajes de más de 10 km"],"w":"Todos, siempre."},{"q":"Vas a mover el camión 200 metros dentro de la obra. ¿Usas cinturón?","o":["Sí, siempre, aunque sea un tramo corto","No, dentro de la obra no se usa","Solo si voy a más de 30 km/h","Solo si llevo ayudante"],"w":"El cinturón se usa en todo tramo."}]},{"s":"camion_conduccion_obra","v":[{"q":"Al llegar a una obra ves cables eléctricos sobre el punto de descarga. ¿Qué haces?","o":["No descargo ahí: busco otro punto y coordino con la obra","Descargo rápido y me voy","Descargo con cuidado de no levantar la rampla","Pido que alguien levante los cables con un palo"],"w":"Un contacto con cables puede ser mortal."},{"q":"El punto de descarga es un relleno blando junto a una zanja. ¿Qué haces?","o":["No entro: coordino otro punto firme con la obra","Entro rápido para no alcanzar a enterrarme","Entro si el suelo se ve seco y compacto","Descargo con el camión algo inclinado, con freno"],"w":"El terreno blando o el borde de una zanja pueden ceder con el peso."},{"q":"Se puede descargar con el camión en pendiente si se pone el freno de mano.","vf":false,"w":"Falso. No se descarga en desnivel: se busca terreno plano y firme."}]}]},{"id":"pvd","sec":"admin","title":"Trabajo con computador: ergonomía y pausas","thumb":"pvd_intro","learn":[{"s":"pvd_intro","t":"Muchas horas frente a la pantalla","x":"Administrativos, oficina técnica y jefaturas pasan horas frente al computador. Una mala postura no duele el primer día, pero <b>sumada día a día</b> puede terminar en dolor de cuello, espalda, hombros y muñecas, e incluso en una enfermedad profesional. Ajustar tu puesto toma cinco minutos: pantalla, silla, teclado, luz y pausas."},{"s":"pvd_pantalla","t":"La pantalla","x":"<ul><li>El <b>borde superior a la altura de los ojos</b> o un poco más abajo.</li><li>A unos <b>50 a 70 cm</b>: más o menos un brazo estirado.</li><li><b>De frente</b>, no girada a un lado, para no torcer el cuello.</li></ul>Si la pantalla está baja, ponle una base o unos libros firmes debajo. Si usas dos pantallas, la principal va al frente."},{"s":"pvd_silla","t":"Silla, espalda y pies","x":"<ul><li>Regula la altura: <b>codos en ángulo recto</b>, a la altura del escritorio.</li><li>Espalda <b>apoyada en el respaldo</b>, sobre todo la zona lumbar.</li><li><b>Pies planos</b> en el suelo o en un apoyapiés, sin cruzarlos bajo la silla.</li><li>Hombros relajados.</li></ul>Si tu silla no se puede regular o está dañada, avisa a tu jefatura."},{"s":"pvd_teclado","t":"Teclado y mouse","x":"<ul><li>Teclado <b>cerca</b>, frente a ti, a la altura de los codos.</li><li><b>Muñecas rectas</b>: ni dobladas hacia arriba ni hacia los lados.</li><li>Mouse <b>al lado del teclado</b>, sin estirar el brazo.</li><li>Antebrazos apoyados en el escritorio.</li></ul>El brazo estirado todo el día carga el hombro y el cuello."},{"s":"pvd_vista","t":"Descansa la vista: 20-20-20","x":"Es una <b>recomendación práctica</b>, no una norma legal: cada <b>20 minutos</b>, mira algo lejano, a unos <b>6 metros</b>, durante <b>20 segundos</b>. Parpadea a propósito: frente a la pantalla parpadeamos menos y los ojos se secan. Ojos cansados, ardor o visión borrosa son señales para descansar; si se repiten, consulta."},{"s":"pvd_pausas","t":"Pausas activas","x":"Estar quieto también cansa: la postura sostenida carga músculos y articulaciones. Cada cierto rato:<ul><li><b>Levántate</b> y camina un poco.</li><li>Estira cuello, hombros, espalda y muñecas, sin forzar.</li><li>Cambia de postura.</li></ul>Aprovecha tareas como ir a la impresora, contestar una llamada de pie o salir a terreno para moverte."},{"s":"pvd_notebook","t":"Notebook y celular","x":"<ul><li>El notebook plano en la mesa obliga a agachar la cabeza. Si lo usas muchas horas, ponlo sobre una <b>base</b> y usa <b>teclado y mouse aparte</b>.</li><li>El <b>celular</b>: súbelo a la altura de los ojos en vez de doblar el cuello por largos ratos.</li><li>Evita trabajar en la cama o el sillón.</li></ul>"},{"s":"pvd_luz","t":"Luz y reflejos","x":"<ul><li>Pon la pantalla <b>al costado de la ventana</b>, no de frente ni de espaldas a ella.</li><li>Usa cortinas o persianas si el sol pega en la pantalla.</li><li>Ajusta el brillo a la luz del lugar.</li><li>Limpia la pantalla.</li></ul>Los reflejos te obligan a forzar la vista y a torcer la postura para leer."},{"s":"pvd_sintomas","t":"Señales de alerta","x":"Los <b>trastornos musculoesqueléticos de extremidades superiores (TMERT)</b> avisan antes:<ul><li>Dolor en cuello, hombros, codos o muñecas.</li><li>Hormigueo o adormecimiento en manos y dedos.</li><li>Pérdida de fuerza.</li></ul>Si se repiten, <b>avisa a tu jefatura</b> y consulta en la <b>ACHS</b> (fono 1404). No te automediques: consultar a tiempo evita que avance.","k":"Hormigueo o dolor que se repite: avisa y consulta en la ACHS."},{"s":"pvd_auto","t":"Autocuidado: “termino y paro”","x":"La mayoría de las lesiones se relacionan con una acción insegura. Frente al computador, la típica es <b>“termino esto y paro”</b>: horas encorvado sin moverte, ignorando el dolor. La decisión segura: <b>ajusta tu puesto y haz la pausa ahora</b>. Y avisa si tu silla, pantalla o iluminación no sirven: también es autocuidado."}],"quiz":[{"s":"pvd_pantalla","v":[{"q":"¿A qué altura debe estar el borde superior de la pantalla?","o":["A la altura de los ojos o un poco más abajo","Por encima de los ojos, para mirar hacia arriba","A la altura del pecho, para mirar hacia abajo","Donde quede, si la pantalla es grande"],"w":"Así el cuello queda recto."},{"q":"¿A qué distancia se ubica la pantalla?","o":["A unos 50 a 70 cm, cerca de un brazo","A unos 20 cm, para leer mejor","A más de un metro y medio","Lo más cerca posible de la cara"],"w":"Un brazo estirado es una buena referencia."},{"q":"Trabajas con la pantalla girada a un costado. ¿Qué corriges?","o":["La pongo de frente para no girar el cuello","Nada, si el giro es poco","Giro la silla de vez en cuando","Subo el brillo para verla mejor"],"w":"La pantalla principal va de frente."}]},{"s":"pvd_cel_mal","v":[{"q":"Revisas correos en el celular por largo rato. ¿Qué postura es correcta?","o":["Subir el celular a la altura de los ojos","Bajar la cabeza y apoyar el mentón","Sostenerlo a la altura de la cintura","Usarlo recostado en el sillón"],"w":"Sube el celular en vez de doblar el cuello."},{"q":"¿Qué provoca usar el celular por horas con el cuello doblado?","o":["Dolor de cuello y hombros por la carga sostenida","Solo cansancio de la vista, sin otro efecto","Nada, si el celular es liviano","Molestias solo en las manos por sostenerlo"],"w":"La cabeza inclinada carga el cuello todo el rato."},{"q":"Mirar el celular con el cuello doblado por largos ratos puede causar dolor de cuello.","vf":true,"w":"Verdadero. Por eso se sube a la altura de los ojos."}]},{"s":"pvd_teclado","v":[{"q":"Al escribir, las muñecas deben estar:","o":["Rectas, con el teclado cerca","Dobladas hacia arriba, apoyadas en el borde","Inclinadas hacia los lados","Colgando, sin apoyar el antebrazo"],"w":"Muñecas rectas y antebrazos apoyados."},{"q":"¿Dónde va el mouse?","o":["Al lado del teclado, sin estirar el brazo","Al borde del escritorio, lejos del teclado","Delante del teclado","Sobre las piernas"],"w":"El brazo estirado carga hombro y cuello."},{"q":"Usas el mouse con el brazo estirado todo el día. ¿Qué corriges?","o":["Lo acerco junto al teclado y apoyo el antebrazo","Cambio a un mouse más grande y pesado","Empiezo a usarlo con la otra mano","Nada, mientras todavía no me duela"],"w":"Acércalo antes de que aparezca el dolor."}]},{"s":"pvd_vista","v":[{"q":"La regla 20-20-20 es una norma legal obligatoria en Chile.","vf":false,"w":"Falso. Es una recomendación práctica para descansar la vista."},{"q":"¿Qué es la regla 20-20-20?","o":["Una recomendación práctica para descansar la vista","Una exigencia legal del DS 594 para oficinas","Una obligación establecida en la Ley 16.744","Un protocolo obligatorio del MINSAL para pantallas"],"w":"No es una norma: es un buen hábito."},{"q":"Un compañero dice que la regla 20-20-20 es una obligación legal. ¿Es así?","o":["No, es una recomendación práctica","Sí, la exige el DS 44","Sí, la exige el protocolo TMERT","Solo es obligatoria en oficinas públicas"],"w":"Es un hábito recomendado, no una ley."}]},{"s":"pvd_vista","v":[{"q":"Según la regla 20-20-20, cada 20 minutos debes:","o":["Mirar algo lejano unos 20 segundos","Cerrar los ojos 20 minutos","Mirar la pantalla de cerca 20 segundos","Caminar 20 minutos"],"w":"Mira lejos 20 segundos y parpadea."},{"q":"En la regla 20-20-20, ¿a qué distancia aproximada miras?","o":["Unos 6 metros","Unos 20 cm","Unos 60 cm","Unos 2 metros"],"w":"Mirar lejos relaja el enfoque de los ojos."},{"q":"Frente a la pantalla, los ojos se secan principalmente porque:","o":["Parpadeamos menos","La pantalla emite calor","La letra es pequeña","Miramos a lo lejos"],"w":"Por eso se recomienda parpadear a propósito."}]},{"s":"pvd_silla","v":[{"q":"Los pies deben quedar:","o":["Planos en el suelo o en un apoyapiés","Colgando de la silla","Cruzados bajo la silla","Apoyados en la base con ruedas"],"w":"Pies apoyados, espalda en el respaldo y codos en ángulo recto."},{"q":"¿Cómo regulas la altura de la silla?","o":["Codos en ángulo recto, a la altura del escritorio","Lo más baja posible","Lo más alta posible para ver la pantalla","Con las rodillas más altas que la cadera"],"w":"Los codos a la altura del escritorio."},{"q":"Tu silla no se puede regular y te duele la espalda. ¿Qué haces?","o":["Aviso a mi jefatura","Me siento en el borde de la silla","Me acostumbro con el tiempo","Aguanto hasta fin de mes"],"w":"Un puesto que no se ajusta se avisa."}]},{"s":"pvd_luz","v":[{"q":"¿Dónde conviene poner la pantalla respecto de la ventana?","o":["Al costado de la ventana","De frente a la ventana","De espaldas a la ventana, con el sol encima","Frente a la ventana con la cortina abierta"],"w":"Al costado se evitan reflejos y encandilamiento."},{"q":"El sol se refleja en tu pantalla. ¿Qué haces?","o":["Cierro la cortina o muevo la pantalla al costado","Subo el brillo de la pantalla al máximo","Me inclino para ver entre los reflejos","Uso lentes de sol mientras trabajo"],"w":"Se elimina el reflejo, no se fuerza la vista."},{"q":"¿Qué provocan los reflejos en la pantalla?","o":["Forzar la vista y torcer la postura","Nada, solo son una molestia","Daño en la pantalla con el tiempo","Solo sueño después de almuerzo"],"w":"Te inclinas y fuerzas la vista para leer."}]},{"s":"pvd_notebook","v":[{"q":"Si usas notebook muchas horas, lo recomendable es:","o":["Ponerlo en una base y usar teclado y mouse aparte","Usarlo sobre las piernas en el sillón","Bajar el brillo al mínimo","Inclinar la pantalla hacia atrás"],"w":"Así la pantalla sube y las manos quedan bien."},{"q":"¿Por qué el notebook plano en la mesa es un problema si se usa muchas horas?","o":["Obliga a agachar la cabeza","Se calienta más","Gasta más batería","La pantalla se ve más chica"],"w":"La pantalla queda baja y el cuello se dobla."},{"q":"Trabajar con el notebook en la cama es una buena alternativa si la silla es incómoda.","vf":false,"w":"Falso. Se evita la cama o el sillón; la silla incómoda se avisa."}]},{"s":"pvd_sintomas","v":[{"q":"Tienes hormigueo en las manos varias veces a la semana. ¿Qué haces?","o":["Aviso a mi jefatura y consulto en la ACHS","Espero a que se pase solo","Tomo antiinflamatorios por mi cuenta","Me pongo una muñequera y sigo igual"],"w":"Es una señal de alerta: se avisa y se consulta a tiempo."},{"q":"¿Cuál de estas es una señal de alerta de TMERT?","o":["Adormecimiento en manos y dedos","Hambre antes de almuerzo","Sueño después de almuerzo","Sed durante el día"],"w":"Dolor, hormigueo, adormecimiento y pérdida de fuerza."},{"q":"¿Dónde consultas si crees que tus molestias se deben al trabajo?","o":["En la ACHS, avisando a mi jefatura","Solo en la farmacia","Espero el examen anual","Solo con un masajista particular"],"w":"La ACHS evalúa si es de origen laboral."}]},{"s":"pvd_pausas","v":[{"q":"Las pausas activas también sirven para quien trabaja sentado frente al computador.","vf":true,"w":"Verdadero. Estar quieto también cansa."},{"q":"¿Qué es una pausa activa?","o":["Levantarse, estirar y caminar unos minutos","Revisar el celular sentado","Tomar un café en el escritorio","Cambiar de programa en el computador"],"w":"Pausa activa es moverse."},{"q":"Llevas dos horas sin levantarte terminando un informe. ¿Qué haces?","o":["Hago una pausa ahora: me levanto y estiro","Termino el informe y después paro","Me acomodo mejor en la silla y sigo","Me tomo un café sin levantarme"],"w":"“Termino y paro” es el acto inseguro típico."}]}]},{"id":"oficina","sec":"admin","title":"Riesgos en la oficina","thumb":"of_intro","learn":[{"s":"of_intro","t":"La oficina también tiene riesgos","x":"En la oficina no hay grúas ni camiones, pero sí accidentes:<ul><li>Caídas por cables, cajones abiertos o pisos mojados.</li><li>Golpes por archivadores que se vuelcan.</li><li>Incendios por zapatillas sobrecargadas.</li><li>Caídas al subirse a una silla.</li></ul>Y el camino de ida y vuelta al trabajo. En la oficina de obra o en la casa matriz, las reglas son las mismas."},{"s":"of_caidas","t":"Caídas al mismo nivel","x":"<ul><li><b>Cables</b> por el piso: ordénalos por la orilla o con canaletas.</li><li><b>Cajones</b> abiertos: ciérralos apenas los uses.</li><li>Alfombras levantadas, piso mojado o café derramado: <b>limpia, señaliza o avisa</b> de inmediato.</li><li>No camines leyendo el celular, sobre todo en escaleras.</li></ul>Las caídas al mismo nivel son de los accidentes más frecuentes en oficinas."},{"s":"of_cajones","t":"Archivadores","x":"<ul><li>Abre <b>un cajón a la vez</b>: con varios abiertos arriba, el peso se va hacia adelante y el mueble se vuelca.</li><li>Pon lo <b>pesado en los cajones de abajo</b>.</li><li>Cierra cada cajón al terminar.</li><li>Los muebles altos deben estar firmes o anclados al muro: si se mueven, avisa.</li></ul>"},{"s":"of_electrico","t":"Riesgo eléctrico","x":"<ul><li><b>No conectes una zapatilla a otra</b> (en cadena): se sobrecargan y pueden provocar un incendio.</li><li>No enchufes estufa, hervidor y equipos en la misma zapatilla.</li><li>Desenchufa tomando el enchufe, no tirando del cable.</li><li>Cable pelado, enchufe caliente u olor a quemado: <b>no lo uses y avisa</b>.</li><li>Nunca agua sobre equipos eléctricos.</li></ul>","k":"Sin zapatillas en cadena; lo dañado no se usa y se avisa."},{"s":"of_silla_mal","t":"La silla no es escalera","x":"Para alcanzar un archivo alto, <b>nunca te subas a una silla</b>, menos si tiene ruedas: se desliza o gira y la caída es segura. Tampoco a cajas ni al escritorio, aunque alguien sujete. Usa una <b>escalera o un piso de altura adecuado</b>, o pide ayuda. Deja lo de uso frecuente a una altura cómoda.","k":"Nunca te subas a una silla, menos si tiene ruedas."},{"s":"of_orden","t":"Orden y aseo","x":"<ul><li>Nada de cajas ni archivos en el piso, en los pasillos, frente a las salidas ni tapando extintores.</li><li>Escritorio ordenado: menos cosas que caen.</li><li>Café o agua derramada: límpiala de inmediato.</li><li>Tijeras y cartoneros, cerrados y guardados.</li></ul>El orden es la medida de prevención más barata que existe."},{"s":"of_evac","t":"Emergencias y evacuación","x":"<ul><li>Conoce las <b>vías de evacuación</b>, la <b>zona de seguridad</b> y dónde están los extintores.</li><li>Puertas, pasillos y extintores, siempre <b>despejados</b>.</li><li>En un sismo: <b>agáchate, cúbrete y afírmate</b>, lejos de ventanas y muebles altos.</li><li>Evacúa caminando cuando se indique, sin ascensor y sin volver por tus cosas.</li></ul>"},{"s":"of_trayecto","t":"Accidente de trayecto","x":"Es el que ocurre en el <b>trayecto directo, de ida o regreso</b>, entre tu casa y el trabajo (Ley 16.744, art. 5). Si interrumpes el trayecto por un motivo personal, puede perder la cobertura. Si te pasa:<ul><li>Avisa a tu jefatura lo antes posible.</li><li>Atiéndete en la <b>ACHS</b> (fono 1404).</li><li>Guarda pruebas: parte o constancia de Carabineros, testigos u otros medios.</li></ul>"},{"s":"of_auto","t":"Autocuidado: “es un segundo”","x":"La mayoría de los accidentes se relacionan con una acción insegura. En la oficina, la típica es <b>“es un segundo”</b>: subirse a la silla, saltar el cable, dejar el cajón abierto. La decisión segura: <b>busca la escalera, ordena el cable, cierra el cajón</b>, aunque tome un minuto más. Y avisa las condiciones inseguras: también es autocuidado."}],"quiz":[{"s":"of_silla_mal","v":[{"q":"Necesitas un archivador del estante alto. ¿Cómo lo alcanzas?","o":["Con una escalera o un piso adecuado","Subiéndome a la silla con ruedas, con cuidado","Subiéndome a la silla, si un compañero la sujeta","Empinándome sobre una caja de resmas"],"w":"La silla y las cajas no son escaleras."},{"q":"¿Por qué es peligroso subirse a una silla con ruedas?","o":["Se desliza o gira y provoca la caída","Porque se raya el tapiz","Porque se descalibra la altura","Solo si la silla es de plástico"],"w":"La silla se mueve justo cuando estás arriba."},{"q":"Subirse a una silla sin ruedas es seguro si es solo un segundo.","vf":false,"w":"Falso. Ninguna silla es escalera; usa una escalera o piso adecuado."}]},{"s":"of_electrico","v":[{"q":"¿Se puede conectar una zapatilla a otra si faltan enchufes?","o":["No, se sobrecargan y pueden provocar un incendio","Sí, si las dos zapatillas son nuevas","Sí, si son de la misma marca y potencia","Sí, si solo conectas el computador y la pantalla"],"w":"Las zapatillas en cadena se sobrecargan."},{"q":"Conectas estufa, hervidor y computador en la misma zapatilla. ¿Qué riesgo hay?","o":["Sobrecarga e incendio","Solo que se corte la luz, sin otro riesgo","Ninguno, si la zapatilla tiene interruptor","Que se apague el computador"],"w":"Los equipos que calientan consumen mucho."},{"q":"Las zapatillas eléctricas conectadas en cadena pueden sobrecargarse y provocar un incendio.","vf":true,"w":"Verdadero. Por eso no se conectan una a otra."}]},{"s":"of_cajones","v":[{"q":"¿Por qué conviene abrir un solo cajón del archivador a la vez?","o":["Porque con varios abiertos el mueble puede volcarse","Para que no se mezclen los papeles","Para que el mueble no se raye","Para que los cajones no se descuadren"],"w":"El peso se va hacia adelante y el mueble cae."},{"q":"En un archivador, ¿dónde va lo más pesado?","o":["En los cajones de abajo","En los cajones de arriba","Repartido en los de arriba","Encima del mueble"],"w":"Lo pesado abajo da estabilidad."},{"q":"Un archivador alto se mueve al abrir un cajón. ¿Qué haces?","o":["Aviso para que se fije o se ancle","Pongo un papel bajo la pata y sigo","Abro los cajones con más cuidado","Lo dejo así si no se ha caído"],"w":"Un mueble inestable se fija antes de que caiga."}]},{"s":"of_caidas","v":[{"q":"Un cable cruza el pasillo de la oficina. ¿Qué haces?","o":["Lo ordeno por la orilla o aviso para canalizarlo","Lo salto cada vez que paso","Le pongo una alfombra encima sin avisar","Lo dejo, porque es de otro escritorio"],"w":"Los cables por el piso causan caídas."},{"q":"Ves café derramado en el pasillo. ¿Qué haces?","o":["Lo limpio o lo señalizo y aviso de inmediato","Lo esquivo y sigo","Espero que lo vea el personal de aseo","Le pongo una hoja encima y sigo"],"w":"Un piso mojado es una caída esperando ocurrir."},{"q":"¿Cuál es una causa típica de caídas al mismo nivel en la oficina?","o":["Cables por el piso y cajones abiertos","Sillas con respaldo alto y ruedas","Pantallas con demasiado brillo","Escritorios con cubierta de vidrio"],"w":"Cables, cajones y pisos mojados."}]},{"s":"of_electrico","v":[{"q":"Notas olor a quemado en un enchufe. ¿Qué haces?","o":["Dejo de usarlo y aviso de inmediato","Sigo trabajando y aviso al final del día","Le echo agua para enfriarlo","Lo desenchufo tirando del cable y uso otro"],"w":"Lo dañado no se usa y se avisa; nunca agua."},{"q":"Ves un cable pelado en el hervidor de la oficina. ¿Qué haces?","o":["No lo uso y aviso","Lo envuelvo con cinta y lo uso","Lo uso con cuidado","Lo uso solo con las manos secas"],"w":"Un cable dañado puede electrocutar o provocar un incendio."},{"q":"¿Cómo se desenchufa correctamente un equipo?","o":["Tomando el enchufe, no tirando del cable","Tirando del cable con firmeza","Moviendo la zapatilla hasta que salga","Con cualquier mano, aunque esté húmeda"],"w":"Tirar del cable lo daña por dentro."}]},{"s":"of_evac","v":[{"q":"En un sismo, la conducta recomendada es:","o":["Agáchate, cúbrete y afírmate","Correr por la escalera","Pararte junto a la ventana","Salir en ascensor"],"w":"Lejos de ventanas y muebles altos."},{"q":"Al evacuar después del sismo, ¿qué es correcto?","o":["Caminar a la zona de seguridad sin volver por mis cosas","Correr por la escalera para salir primero","Volver rápido por el notebook y el celular","Usar el ascensor para salir más rápido"],"w":"Se evacúa caminando, sin ascensor."},{"q":"Durante un sismo, ¿de qué te alejas?","o":["De ventanas y muebles altos","De escritorios firmes","De la zona de seguridad","De muros interiores sin ventanas"],"w":"Los vidrios y los muebles altos pueden caer."}]},{"s":"of_trayecto","v":[{"q":"Un accidente en el trayecto directo de tu casa al trabajo no está cubierto por la Ley 16.744.","vf":false,"w":"Falso. El accidente de trayecto está cubierto (art. 5 de la Ley 16.744)."},{"q":"Sales del trabajo, pasas al supermercado por un asunto personal y ahí te caes. ¿Es accidente de trayecto?","o":["Puede no estar cubierto: se interrumpió el trayecto directo","Sí, cubre todo lo que pase después de la jornada","Sí, siempre que después sigas hacia tu casa","Solo si vas en locomoción colectiva o a pie"],"w":"La cobertura es para el trayecto directo."},{"q":"¿Qué es un accidente de trayecto?","o":["El que ocurre en el trayecto directo casa-trabajo, de ida o regreso","Cualquier accidente que ocurra en vacaciones","Solo el que ocurre dentro de la oficina","El que ocurre en un paseo de fin de semana con compañeros"],"w":"Trayecto directo, ida o regreso."}]},{"s":"of_trayecto","v":[{"q":"Si sufres un accidente de trayecto, ¿qué te sirve como prueba?","o":["Parte de Carabineros, testigos u otros medios","Basta con contarlo días después","Solo una foto en redes sociales","Solo un certificado de un médico particular"],"w":"Avisa, atiéndete en la ACHS y guarda pruebas."},{"q":"Tienes un accidente de trayecto. ¿Dónde te atiendes?","o":["En la ACHS, avisando a mi jefatura","En cualquier consultorio, sin avisar","Espero a ver si duele mañana","Solo en una clínica particular"],"w":"El organismo administrador es la ACHS."},{"q":"¿A quién avisas si tienes un accidente de trayecto?","o":["A mi jefatura, lo antes posible","A nadie, si es leve","Solo a mi familia","A Recursos Humanos a fin de mes"],"w":"Avisar pronto facilita la atención y la cobertura."}]},{"s":"of_orden","v":[{"q":"Hay cajas apiladas frente a la puerta de salida. Eso es:","o":["Una condición insegura que debo ordenar o avisar","Algo normal en una oficina","Un problema solo de aseo","Aceptable si queda un espacio para pasar"],"w":"Salidas y pasillos siempre despejados."},{"q":"¿Dónde no se deben dejar cajas ni archivos?","o":["En pasillos, salidas y frente a extintores","En los estantes destinados a archivo","En la bodega, ordenados por fecha","En los cajones de cada escritorio"],"w":"Se necesitan libres en una emergencia."},{"q":"Un extintor quedó tapado por cajas. ¿Qué haces?","o":["Despejo el acceso o aviso","Lo dejo, igual se ve","Muevo el extintor detrás de las cajas","Espero el próximo simulacro"],"w":"El extintor debe estar visible y accesible."}]},{"s":"of_auto","v":[{"q":"Te piden un archivo del estante alto con urgencia. ¿Cuál es la decisión segura?","o":["Ir por la escalera aunque tome un minuto más","Subirme a la silla, porque es un segundo","Subirme al escritorio, que es más firme","Pedir que me sujeten la silla con ruedas"],"w":"Un segundo de apuro puede costar meses."},{"q":"Avisar una condición insegura, ¿es parte del autocuidado?","o":["Sí, evita que otro se accidente","No, es tarea solo de la jefatura","Solo si me afecta a mí","Solo si ya hubo un accidente"],"w":"Avisar también es autocuidado."},{"q":"Avisar una condición insegura, como un cable suelto, también es autocuidado.","vf":true,"w":"Verdadero. Avisar protege a todos."}]}]},{"id":"montaje_sip","sec":"obra","title":"Montaje seguro de paneles SIP","thumb":"pz_izaje_ok","mins":6,"learn":[{"s":"pz_obra","t":"El panel SIP","x":"Un panel SIP tiene dos placas de <b>OSB</b> y un núcleo de <b>poliestireno expandido (EPS)</b>. Es liviano para su tamaño, pero un panel completo <b>suele superar los 25 kg</b> y mide más de 2 metros: es incómodo de tomar y, con viento, se comporta como una <b>vela</b> que puede botarte o arrastrarte. El EPS es combustible: mantén los paneles lejos de chispas y llamas."},{"s":"pz_irl","t":"Antes de montar: planifica","x":"Revisa con tu encargado el <b>plano y la secuencia de montaje</b>, quién hace cada tarea y los riesgos informados de la tarea. Delimita la zona, despeja los accesos y verifica que estén los puntales, las herramientas y tu EPP.<ul><li><b>Con viento fuerte o lluvia intensa no se montan paneles.</b></li><li>Nadie monta paneles solo.</li></ul>","k":"Con viento fuerte, no se montan ni se trasladan paneles."},{"s":"panel2","t":"Traslado manual de paneles","x":"La Ley 20.949 fija un máximo de <b>25 kg</b> de carga manual para hombres y <b>20 kg</b> para mujeres y menores de 18 años; las embarazadas no cargan. Por eso un panel se mueve <b>entre dos o más personas</b> o con ayuda mecánica. Una sola voz de mando: “arriba, vamos, abajo”. Espalda recta, levanta con las piernas y mira el camino. <b>Guantes</b> siempre: el OSB tiene astillas y cantos."},{"s":"pz_izaje_ok","t":"Izaje de paneles","x":"Si el panel se sube con grúa o pluma: eslingas y ganchos <b>certificados y revisados</b>, zona delimitada, <b>un solo rigger</b> que da las señales y <b>cuerdas guía</b> para controlar el giro desde lejos. <b>Nadie se pone bajo la carga</b> ni entre el panel y un muro. Si el viento mueve el panel, se suspende el izaje y se baja de forma controlada."},{"s":"pz_alt_arnes","t":"Montaje en altura","x":"Desde <b>1,8 m</b>: arnés de cuerpo completo con la cola conectada a un <b>punto de anclaje o línea de vida</b> resistente, nunca a un panel sin fijar, a un puntal ni a la baranda. Usa andamios con <b>tarjeta verde</b> y bordes con baranda y rodapié. No te pares sobre un panel sin fijar ni camines por vigas sin protección."},{"s":"pz_alt_borde_ok","t":"Aplomar, apuntalar y fijar","x":"Un panel de muro recién parado puede <b>volcarse</b> con el viento o con un golpe. Mientras se aploma, alguien lo sostiene; luego se <b>apuntala de inmediato</b> con puntales provisorios y se fija según el plano. No lo sueltes hasta que esté asegurado, y <b>nunca</b> dejes un panel suelto al terminar la jornada: apuntálalo o bájalo.","k":"Panel parado, panel apuntalado."},{"s":"pz_sierra_ok","t":"Corte de paneles","x":"Sierra con su <b>resguardo</b> funcionando y el panel <b>bien apoyado</b> sobre caballetes, nunca sostenido en el aire ni sobre la rodilla. Usa <b>lentes, mascarilla y protector auditivo</b>: el corte de OSB y EPS levanta polvo y partículas, y las sierras suelen superar los 85 dB. <b>Desconecta</b> la sierra antes de cambiar el disco o ajustar el corte."},{"s":"pz_elec_ext_ok","t":"Herramientas eléctricas y fijaciones","x":"Revisa atornilladores, taladros y extensiones antes de usarlos: cables <b>sin cortes ni uniones con cinta</b>, enchufes en buen estado y conectados a un tablero con protección diferencial. Extensiones en altura, lejos del agua y del paso. Lo dañado se saca de uso y se avisa. Nunca apuntes una clavadora a una persona y desconéctala antes de destrabarla."},{"s":"pz_acopio","t":"Acopio de paneles","x":"Los paneles se acopian <b>horizontales, sobre polines</b>, en una superficie pareja y firme, separados del suelo para que no tomen humedad. La pila debe quedar estable y baja, <b>amarrada o con peso encima</b> para que el viento no la levante. Lejos de bordes, excavaciones, tránsito de máquinas y de trabajos con chispas: el EPS es combustible."},{"s":"pz_orden_ok","t":"Orden durante el montaje","x":"Despuntes de OSB, trozos de EPS, plásticos, tornillos y clavos se retiran <b>al terminar cada tarea</b>, no al final del día: en una losa o entrepiso provocan tropiezos, cortes y pinchazos. Los vanos y aberturas del entrepiso quedan <b>tapados, fijos y señalizados</b>. Los residuos van al lugar que indique la obra."}],"quiz":[{"s":"pz_obra","v":[{"q":"¿Por qué el viento es peligroso al mover paneles SIP?","o":["El panel actúa como vela y puede desequilibrarte","El viento enfría el panel y lo vuelve frágil","El viento solo levanta polvo; el panel no se afecta","Solo es peligroso si el panel está mojado"],"w":"Un panel grande toma el viento como una vela."},{"q":"Hay viento fuerte y debes trasladar un panel. ¿Qué haces?","o":["Espero a que baje el viento y aviso a mi encargado","Lo llevo solo y rápido para exponerme menos","Lo llevo con el lado ancho contra el viento","Lo arrastro por el suelo para que no vuele"],"w":"Con viento fuerte se suspende el traslado y el montaje."},{"q":"Con viento fuerte se pueden montar paneles SIP si se trabaja entre varios.","vf":false,"w":"Falso. Con viento fuerte no se montan ni se trasladan paneles."}]},{"s":"panel2","v":[{"q":"Un panel SIP completo supera los 25 kg. ¿Cómo se traslada a mano?","o":["Entre dos o más, coordinados, con guantes y mirando el camino","Una persona sobre la cabeza, si es fuerte y tiene experiencia","Arrastrándolo por el suelo para no cargar su peso","Entre dos, cada uno a su propio ritmo y sin hablar"],"w":"Entre varios, con una sola voz de mando."},{"q":"Según la Ley 20.949, ¿cuál es la carga manual máxima para un hombre adulto?","o":["25 kg","50 kg","35 kg","30 kg"],"w":"Hombres 25 kg; sobre eso, entre varios o con ayuda mecánica."},{"q":"Según la Ley 20.949, ¿cuál es la carga manual máxima para mujeres y menores de 18 años?","o":["20 kg","25 kg","15 kg","30 kg"],"w":"Mujeres y menores de 18: 20 kg. Las embarazadas no cargan."}]},{"s":"pz_izaje_ok","v":[{"q":"Se iza un panel con grúa. ¿Dónde no debes estar nunca?","o":["Bajo la carga suspendida","Fuera de la zona delimitada","En el extremo de la cuerda guía","Junto al rigger, fuera del radio"],"w":"Nadie bajo la carga suspendida."},{"q":"El panel baja hacia su posición y empieza a girar. ¿Cómo lo controlas?","o":["Con la cuerda guía, sin ponerme bajo ni junto al panel","Lo sujeto con las manos al pasar bajo él","Me pongo entre el panel y el muro para frenarlo","Pido al operador que lo baje rápido"],"w":"La cuerda guía controla el giro desde lejos."},{"q":"Un compañero cruza bajo un panel izado “porque es rápido”. ¿Qué haces?","o":["Doy la señal de PARE y lo saco de la zona","Lo dejo pasar si el panel va bien amarrado","Le aviso al terminar la maniobra","Pido que suban más el panel"],"w":"Nadie pasa bajo la carga; cualquiera puede dar PARE."}]},{"s":"pz_alt_arnes","v":[{"q":"Montas paneles a más de 1,8 m. ¿Qué es obligatorio?","o":["Arnés de cuerpo completo conectado a un anclaje o línea de vida","Arnés puesto, conectándolo solo cerca del borde","Casco con barbiquejo, sin arnés si hay cuidado","Cinturón de herramientas bien apretado"],"w":"Sobre 1,8 m: arnés conectado todo el tiempo."},{"q":"¿Desde qué altura se considera trabajo en altura?","o":["Desde 1,8 m","Desde 3 m","Desde 2,5 m","Desde 1 m"],"w":"Desde 1,8 m se exige protección contra caídas."},{"q":"¿Dónde conectas la cola del arnés?","o":["A un anclaje o línea de vida resistente","A la baranda superior del andamio","Al panel que se acaba de parar","A un puntal provisorio bien firme"],"w":"Ni el panel sin fijar ni el puntal resisten una caída."}]},{"s":"pz_alt_borde_ok","v":[{"q":"Acabas de parar un panel de muro. ¿Qué haces de inmediato?","o":["Lo apuntalo con puntales provisorios hasta fijarlo","Lo suelto para ir por el siguiente","Lo dejo apoyado contra el panel vecino","Le pongo un tornillo y sigo"],"w":"Panel parado, panel apuntalado."},{"q":"Termina la jornada y queda un panel parado sin fijar. ¿Qué corresponde?","o":["Apuntalarlo bien o bajarlo; nunca dejarlo suelto","Dejarlo así hasta mañana si no hay viento","Amarrarlo con cinta de embalaje","Apoyarlo contra el andamio"],"w":"Nunca se deja un panel suelto."},{"q":"Un panel recién parado puede volcarse si no se apuntala.","vf":true,"w":"Verdadero. Por eso se apuntala de inmediato."}]},{"s":"pz_epp_respirador","v":[{"q":"¿Qué EPP usas para cortar paneles SIP con sierra?","o":["Lentes, mascarilla y protector auditivo","Solo guantes, porque el corte es corto","Lentes y guantes; la mascarilla, solo con OSB húmedo","Protector auditivo; los lentes, solo con disco nuevo"],"w":"Polvo, partículas y ruido: lentes, mascarilla y protector auditivo."},{"q":"¿Por qué se usa mascarilla al cortar paneles SIP?","o":["El corte de OSB y EPS levanta polvo y partículas","Solo por el olor del adhesivo","Para no respirar el humo del motor","Porque lo exige el fabricante de la sierra"],"w":"El polvo del corte daña las vías respiratorias."},{"q":"Vas a hacer un corte rápido de un panel. ¿Usas lentes?","o":["Sí, siempre: las partículas saltan desde el primer corte","No, los lentes son solo para cortes largos","Solo si hay viento que levante el polvo","No, porque la sierra tiene su resguardo"],"w":"Un corte corto basta para lesionar un ojo."}]},{"s":"pz_elec_ext_ok","v":[{"q":"¿Qué extensión eléctrica puedes usar?","o":["Una sin cortes ni uniones con cinta y con enchufes en buen estado","Una con uniones bien hechas con cinta aisladora","Una con el cable algo pelado, si no toca el agua","Cualquiera, si la herramienta es nueva"],"w":"Sin cortes ni uniones con cinta."},{"q":"Tu atornillador tiene el cable pelado cerca del enchufe. ¿Qué haces?","o":["Lo saco de uso y aviso","Lo envuelvo con cinta y sigo","Lo uso con guantes","Lo uso solo hasta terminar la tarea"],"w":"Lo dañado se saca de uso y se avisa."},{"q":"La extensión cruza un charco en la losa. ¿Qué haces?","o":["La saco del agua y la llevo en altura, lejos del paso","La dejo, si el enchufe no está en el agua","Pongo una tabla encima y sigo","La dejo, porque tiene protección diferencial"],"w":"Extensiones en altura, lejos del agua y del paso."}]},{"s":"pz_acopio","v":[{"q":"¿Cómo se acopian los paneles SIP en la obra?","o":["Horizontales, sobre polines, en superficie pareja y amarrados","Parados contra un muro, para ocupar menos espacio","Horizontales sobre el suelo, tapados con plástico","Sobre polines, sin amarrar si hay poco viento"],"w":"Horizontales, sobre polines, parejos y amarrados."},{"q":"¿Por qué se amarran o se les pone peso a los paneles acopiados?","o":["Para que el viento no los levante","Para que no se deformen con el sol","Para que nadie los saque","Para que no tomen humedad"],"w":"El viento puede levantar y lanzar los paneles."},{"q":"¿Por qué el acopio de paneles va sobre polines?","o":["Para que no tomen humedad del suelo y queden parejos","Para que el viento pase por debajo de la pila","Para que se vean ordenados ante la inspección","Para que se sequen más rápido al sol"],"w":"Separados del suelo y en superficie pareja."}]}]}]});
